/* 平成15年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h15.committeeSessions.push(...[{"id":"h15-20031125-9","meetingId":"h15-cm11","date":"2003年11月25日","dateIso":"2003-11-25","committee":"文教委員会","time":"午前１０時０５分～午後３時２２分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を84件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議案審査","agenda":"議案審査","exchanges":[{"speaker":"伊藤委員","kind":"質問","question":"ちょっと一つ伺いたいんですが、土地を都市基盤整備公団から借用されますよね。地代がどれぐらいかかるかということ。それから、ご説明のように、仮設校舎をリース契約で借りるとなっていますけれども、初めてですけれども、校舎をリース契約で借りるということを、もう少しご説明いただければと思います。この二つを教えてください。","respondent":"谷田部学務課長","answer":"土地の使用のほうなんですが、これは土地使用貸借契約ですから、土地の使用料、いわゆる賃料、その他の使用料という契約になってあります。それから、校舎のリース関係ですけれども、２７カ月借りるということで、月２７０万円ほど支払う状況となっています。","voiceIndex":5,"id":"exchange-001"},{"speaker":"伊藤委員","kind":"質問・要望","question":"リース契約で２７カ月借りるというのはわかりましたが、当然、確認されると思うんですけれども、通常の建設コストとリース契約のコストを比較をして、安いほうを選んだと思うんですが、その考え方を教えてください。それから、できれば、リース契約にしたらこれだけ浮いた、節約できたといいましょうか、そういったことがあれば教えていただきたいんですが、ありますでしょうか。","respondent":"鷹倉庶務課長","answer":"したがって、学校の規模にもよりますけれども、通常２億円、あるいは３億円ぐらいの金額がかかるです。今回、リースで２７カ月借りるですけれども、先ほどの金額から見ますと、十分おつりが来るということになろうかと思います。","voiceIndex":7,"id":"exchange-002"},{"speaker":"中塚委員","kind":"確認","question":"土地のことが、公団から無償での提供というお話があったんですけれども、一般的な話ですけれども、広大な敷地を無償で借りるというのはあまり考えられなくて、不自然さを感じるんですけれども、こういった前例といいますか、学校教育とか、区のものを大改修をするときに、公団から無償で借りるという形が、今まであったのかどうかということを確認したい。","respondent":"鷹倉庶務課長","answer":"そのときに、公共の用に供するような形での使用の場合に、公租公課が免除されるという関係になります。したがって、公団側としても、小中一貫校の仮校舎に使用をさせるということで、ある意味では、その部分でのメリットがあるということになろうかと思います。","voiceIndex":9,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"ということは、公団の土地も、こういった形で貸すと、公団側も税金の面とかの支払いがなくなるというメリットがあるということでよろしかったんですか。わかりました。それからやっぱり、何かそういった取り引き的なものはなかったということだけ確認させていただきたい。大分、設計のほうが進んでいるんで、改めて建設費のほうは、今現在、どれぐらいの見込みで進んでいるのか伺いたいと思います。","respondent":"鷹倉庶務課長","answer":"設計が進んでいるから、工事費ですけれども、まさにこれは来年度予算で、今、工事費という形で積算した上でご審議いただく内容というということになってありますので、今しばらくお待ち願いたいと思います。","voiceIndex":11,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"工事費というか、新しい小中一貫校計画の建設費が、この前、１００億円という形で伺ったことがあるんですけれども、そんなところで、また新しく詳しいものがわかれば教えていただきたいと思ったのが、その１点です。カリキュラムのことで、１点だけ質問したいんですけれども……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"小中一貫校の内容全体、移転もこの計画の中で進んでいるものなので、１点だけカリキュラムのことを質問させていただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-006"},{"speaker":"沢田委員","kind":"質問","question":"こうした案件というのは、これ単体で、建設の問題で出てくるわけではなくて、いろいろな絡み、準備の中の一つとして出てきているわけで、もちろん質問者のほうで、ある程度そこをわきまえてやるのは必要だと思いますけれども、その後の進展状況がどうなったのかというのは、別にその他のところで質問すればできることですから、二つに分けてやるというよりは効率的なので、出ている議案をわきまえつつも。","respondent":"堺委員長","answer":"さっき、私が申し上げたように、その辺をよくわきまえた上でということを申し上げているわけです。発言をやめさせるということはありませんので、その辺をわきまえた上ということを前提にしているんです。それをお願いできれば大変助かるんですが。","voiceIndex":17,"id":"exchange-007"},{"speaker":"中塚委員","kind":"質問","question":"この前質問したところとダブらない話で、１点だけ質問したいんです。この計画が進む中で、いろいろな不安の声を多く伺うんです。１点聞きたいのは、中学校からの転入を今回の計画でも認めている、１クラス分に当たるんでしょうか。小中一貫校のカリキュラムで一緒に勉強していくのかというところを伺いたいと思っているんです。こういった不安というのを、実際に僕のところでも伺っております。","respondent":"中島指導課長","answer":"英語活動におきましては、今、すべての小学校にＡＬＴを派遣して実施しているところですけれども、１年生からの単元が、今度の小中一貫校のカリキュラムで具体的になってまいりますので、その内容に合わせて、各学校でも、総合的な学習の時間における英語活動でも。","voiceIndex":19,"id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"幾つか質問をさせていただきたいんですが、まず、仮校舎の構造の中では、冷暖房関連がどうなっているのかということです。それから、仮校舎の借入期間が１２月中旬からということであると、１２月中旬から入るという形なのか、それとも、３月から利用されるのかという点です。それから、工事中の危険性について、どういう配慮をしていくのかということについて確認をさせていただきたいと思います。","respondent":"谷田部学務課長","answer":"私、先ほど、説明で日程を細かく申し上げなくて申しわけございませんでした。今回の予定の施行日が来年の１月１日ですから、１月１日をもって仮設のほうに移転するです。","voiceIndex":21,"id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"先ほどの質問の中では、危険性について、どういうふうに配慮していただけるのかということで。別のところがあるので、大丈夫だと思うんですけれども、そこら辺のお考えを。","respondent":"鷹倉庶務課長","answer":"仮校舎をつくる段階もそうですし、仮校舎に移って、本体工事をやる場合も、子どもたちの安全というのは一番大事ですので、工事事業者に対して、安全確保のところを一番重要視し、シートを張ってやるというのは当然のことですけれども、通学路について、必要があれば。","voiceIndex":23,"id":"exchange-010"},{"speaker":"西本委員","kind":"質問・要望","question":"最後に１点だけ要望があるんですが、先ほど、すまいるスクールは平成１８年度から、要は新校舎ができたときに開設するという形になるということなんですが、ほとんど平成１７年度に開校されるということで、今、動いていると思うんです。ここからちょっと私の意見も入ってくるんですが、その辺のお考えをちょっとお聞かせいただきたいんですが、どうでしょうか。","respondent":"富田教育改革担当課長","answer":"すまいるスクールについてですけれども、実施計画上では、一応平成１８年度以降ということで、当初より、平成１８年度に入るものもあるということで予定をしているものですので、現在のところ、実施校以外の他校のお子さんを受け入れるという予定はしておりません。","voiceIndex":25,"id":"exchange-011"},{"speaker":"沢田委員","kind":"質問","question":"先ほどの中塚委員と多少ダブルんですけれども、公団が無償で貸すということに対して、公租公課が免除されてツーペイになるというか、両方得なんだという話があったんですが、普通、ちょっと考えられないんですよね。公租公課の点で、免除される額というのは、年間、大体どれぐらいで踏んでいるのか、そういう検討がなされているのか、そこら辺をちょっともう少し教えてほしいんですが。","respondent":"鷹倉庶務課長","answer":"それ以外に、特別土地保有税、年額ですけれども、この辺が１,７００万円ぐらいという話は聞いてあります。","voiceIndex":27,"id":"exchange-012"},{"speaker":"沢田委員","kind":"質問","question":"公団と言えども、独立採算ですから、メリットのないものをやったら、それは法的にもアウトになる。まあ、公的なところに貸しますから、一般的に無償提供するというのとは違うというのは考慮していますけれども、改めて、そういう問題も含めて、あの地域の開発に、公団との裏の約束といいますか、別の約束みたいなものはなかったと踏んでよろしいんでしょうか。","respondent":"鷹倉庶務課長","answer":"非課税にしていくことが、公団として良しという判断をされたということだと思います。","voiceIndex":29,"id":"exchange-013"},{"speaker":"沢田委員","kind":"質問","question":"そんなことはわかりっこないと言うかもしれないけれども、契約時には、庁のトップとしてもきちっと話をしているわけですから、別に今、証拠があるわけじゃないけれども、いろいろな流れを見てみると、密接な絡みを持っているんじゃないかなと私は思っています。それが１点。だけど、こんな重要な問題で、建設費の概算すら、現在に至っても出ないというのは、どういうことなんでしょうか。","respondent":"鷹倉庶務課長","answer":"建設費ですけれども、まさに実施設計が着々と進んで最終段階に来ているですので、当然、概算は出ていますし、今、私ども、財政当局と所管という形で要求をしています。","voiceIndex":31,"id":"exchange-014"},{"speaker":"沢田委員","kind":"質問・要望","question":"これだけ、区民レベルルで見ても、大きな関心事、区長に対する要望書も上がって、請願も出ている。わきまえてやるつもりですので、１点だけ。だけれども、もし定員があって入れなかった場合にどうするのかということが非常に不安だと言われているんです。荏原第一中学校は、学校選択の定員だとか、現状はどうなっているんでしょうか。実際に相談がありましたので。","respondent":"谷田部学務課長","answer":"きょうの委員会の審査予定の報告事項の中で、小中学校の新一年生の学校の希望申請の実態についてご報告申し上げますので、その中で、具体的な学校についての状況をご説明します。","voiceIndex":33,"id":"exchange-015"},{"speaker":"伊藤委員","kind":"確認","question":"１点だけ確認したいんですが、公団との別契約があるとか、水面下での動きがありはしないかという質問が、きょうの公の委員会にあったと思うんですが、私はないと信じているんですけれども、出席されていらっしゃる理事者の皆さんの中からで結構ですから、皆さんの情報の中で、このことについてきちんと答弁してください。その確認をお願いします。","respondent":"古川教育次長","answer":"今、伊藤委員のほうから、今回の第二日野小学校の仮校舎の移転に関連する公団敷地の関係ですが、私どもは、あくまでも、これから２年間、第二日野小学校の工事に入っていく中での仮校舎の設置の場所としては、極めて近隣の場所に、条件としても整った土地があり。","voiceIndex":36,"id":"exchange-016"},{"speaker":"沢田委員","kind":"提案","question":"関連。あそこは再開発の地域だというのは知っていますよね。それから、きょう、提案されているあれだけの敷地２,９４６m2を所有しているというのは、再開発地域内の土地所有者とのして発言権があるということですよ。しかも無償提供しているということになれば、教育委員会としてどうこうというよりも、もうちょっと開発の全体の中で影響が出てくるということを言ったわけです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":38,"id":"exchange-017"},{"speaker":"石田副委員長","kind":"質問・要望","question":"私から、ちょっと教えていただきたいんですが、これは条例が出てきたわけでありまして、住所が変わるということであると、条例上の学校の場所が１０番３号になりますよというと、自治法のこともあるんだろうけれども、何でこうなのかなというのが１点。そうすると、１１番２８号というのは、その間、どういう扱いになるのかというのが、ちょっとわからないので教えていただきたい。","respondent":"谷田部学務課長","answer":"学校を設置し、または廃止しようというときには、当然、都道府県の教育委員会に届け出るということになってございまして、その中に、また位置を変更した場合についても、届けなければならないというのがあります。","voiceIndex":39,"id":"exchange-018"},{"speaker":"石田副委員長","kind":"質問・要望","question":"大分わかったんですが、もう１点教えていただきたいのは、建設予定地は、税制上は、今言った公租公課は、両方免除されるのかということ。","respondent":"谷田部学務課長","answer":"例えば事業用資産、いわゆる民間企業と同じように、事業を行う場合については課税されるケースがありますが、大体、区がいわゆる公共目的で所有しているものについては、非課税の扱いになっていると思ってあります。","voiceIndex":41,"id":"exchange-019"},{"speaker":"沢田委員","kind":"質問","question":"その理由は、小中一貫校の計画そのものは、研究に値する面があると私は思います。だけれども、具体的な学区制の中でこの問題を取り入れたことによってさまざまな問題が出てくる。調査、研究、教育でやろうとするなら、一部地域の学校に小中一貫校ではなくて、３０人学級をやったり、この後で請願審査されると思いますけれども、そちらこそ急ぐべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-020"},{"speaker":"本間委員","kind":"質問","question":"結論を言いますと、賛成します。意見を述べたいと思います。非常に努力されている部分もお伺いしました。それから、これまでずっと続けてきたであろう地域の皆さんとの、例えば避難所連絡会議だとか、あるいは備蓄倉庫の件だとかという部分は、たとえ仮校舎という形の一時的な施設になろうとも、そういった部分は怠りなく手配をしていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-021"},{"speaker":"西本委員","kind":"意見","question":"無所属の会としても、これに賛成いたします。仮校舎ということもありますので、子どもたちにとって快適な学校生活が否定されないような形での配慮を、ぜひともお願いして意見を述べします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":49,"id":"exchange-022"}]},{"id":"topic-02","title":"続きまして予定表の２、請願・陳情審査","agenda":"続きまして予定表の２、請願・陳情審査","exchanges":[{"speaker":"伊藤委員","kind":"確認","question":"質疑に入る前の段階の話なんですが、委員長に確認したらよろしいんでしょうか。それから、答弁もありましたけれども、学童保育事業を存続してください本来の趣旨からちょっと違った答弁が、きょう、聞いた感じではしましたので、その入口の部分の確認をやっぱりとっていただきませんと、内容そのものに入れないという思いがあるので、まず確認を。これは委員長にしかお願いできないと思うんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-023"},{"speaker":"堺委員長","kind":"質問","question":"今、伊藤委員のお尋ねの件につきましても、はっきり私の個人的な見解ということで申し上げますと、タイトル的には、学童保育事業ということですから、これはやっぱり文教委員会にはなじまない、厚生委員会所管の内容であるというものです。委員長としてお願いできることは、それぞれ各委員の皆さんから率直なご意見、仕切りを出していただければいいんじゃないかなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-024"},{"speaker":"伊藤委員","kind":"意見","question":"いろいろお答えしていただいて、ありがとうあります。ただ、この表現の中身等も問題ですけれども、保育事業を継続してくださいというのは、はっきり厚生委員会の所管ということが書いてあって、そのことについては、直接、間接的に読んでもいいのかれしれませんけれども、文教委員会で、継続する、しないを決定することはできない話です。ありがとうございました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":60,"id":"exchange-025"},{"speaker":"中塚委員","kind":"意見","question":"これまでもこういった意見が出ていますけれども、やっぱり委員長にお願いしたいのは、こういう案件は、よく打合せをした上で、厚生委員会と文教委員会で合同でやるのが、より活発な審議になるんではないかというのが、審議に入る前の僕の意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":61,"id":"exchange-026"},{"speaker":"石田副委員長","kind":"質問・要望","question":"委員長が大変ご苦労されてるので、私は副委員長という立場であまりあれなんですが、今、伊藤委員からも質問があったように、学童保育事業を継続してくださいという質問の中で、今、１から６まであって、さまざまお答えになったのは、すべてすまいるスクールのことであって、これを読む限り、学童保育事業を継続してくださいと言ったら、その中の項目を一つひとつとらえるならば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":63,"id":"exchange-027"},{"speaker":"沢田委員","kind":"質問・要望","question":"こうした請願が出てくる背景にあるのは、学童保育クラブを現に利用している人たちが、心の底では学童保育クラブを存続してほしいと。だから、そういう意味では、この請願の審査に当たっては、区のほうは、そのことを踏まえて、学童保育クラブ以上のものをやるということをこれまで言ってきたわけですから、誠実に答弁をしていただきたいというふうに、私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-028"},{"speaker":"西本委員","kind":"質問・要望","question":"私も、審議の前に、この１番の取り扱いについては、お願いも含めて、あります。今までいろいろな議論をされていると思いますから、その中身も含めて、やはりそちらのほうをきちんと説明した上で、こういうふうな形で、今、考えていますというような説明が、今後、審議の中でぜひともお願いしたいということで、意見を述べさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-029"},{"speaker":"沢田委員","kind":"質問・要望","question":"こういうふうに、今あるものを廃止して移行するとなったら、両方にまたがると。ところが、議会になると、その問題は向こうですから審議できないとなったら、議会は何をやっているんだと問われちゃう。教育委員会も厚生委員会のことを、ある程度責任を持って答弁してもらうというのがこれまでのスタンスですから、それはお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-030"},{"speaker":"中塚委員","kind":"質問・要望","question":"これまで文教委員会の審査の中でも、例えばおやつの問題も今まで学童保育クラブではこういう扱いをした、すまいるスクールではおやつは出さないとか、こういうふうに、当然、審査もしてきたわけですから、今回も、きちんと理事者のほうで責任を持って、学童保育クラブにかかるところも答弁していただきたいし、答弁できないのであれば、きちんと福祉事業部のほうと連絡を取って、責任ある方に来ていただいて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-031"},{"speaker":"伊藤委員","kind":"質問・要望","question":"なぜ条例があって、各委員会の決まりがあって、議会のしくみがあるかということは、そこにあるわけですから。それは、もちろん場合によっては、連合審査が必要でしょうから、委員長にお願いするのはいいんですよ。それをやっぱりこの場で求めること自体、私はおかしいと思います。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-032"},{"speaker":"中塚委員","kind":"質問・要望","question":"質問したいと思います。すまいるスクールなんですけれども、当初、品川区で要綱をつくって、独自の事業という形で始まったと伺いました。来年４月から、児童福祉法に基づくという説明ですけれども、何がどのように変更されたのかというところをご説明していただきたい。請願項目の１に１から６にそれぞれありますけれども、これに照らしてご説明していただきたいと思います。","respondent":"富田教育改革担当課長","answer":"その他は、現在のすまいるスクールの事業とそんなに違ってくるものではございませんけれども、現在もやっておりますようなゆっくりできるようなスペースの確保等、ロッカーの用意等々。","voiceIndex":77,"id":"exchange-033"},{"speaker":"中塚委員","kind":"質問・要望","question":"それが、今回になって、ゆったりとスペース、留守家庭の把握、これを取り入れたことぐらいの違いなんでしょうかね。請願項目の１には、専任職員の複数配置、また個人には専用ロッカーと、いろいろありますけれども、個々に照らして、どう変わっていくのか、また来年４月に向けて、今後、変えていくのか、もう一度、ご説明していただきたいと思います。","respondent":"富田教育改革担当課長","answer":"その他は、この間、保護者の方々、また来年４月からのお子さまが移行してくるに当たって、安心してご利用いただけるように、そういった要綱等々によるものではないのですけれども、すまいるスクールとして、こういったことに努めてまいりしょうということで申し上げたのが。","voiceIndex":79,"id":"exchange-034"},{"speaker":"中塚委員","kind":"質問・要望","question":"学童保育クラブというのは、働きながら子育てをする者にとって、なくてはならない事業として、品川区でも３８年間、一つひとつ積み重ねてきた、そういう事業です。項目に寄せられております専任指導員の複数配置ですけれども、これまでも、職員の加配の問題、児童の参加数に応じて加配をするというお話がありましたけれども、それの基準について説明していただきたいと思います。","respondent":"富田教育改革担当課長","answer":"実際にすまいるスクールを実施してくる中で、児童数が少ないけれども、参加が多いところというのも幾つか出てまいりました。そういったところにつきましては、全体としての指導員を加えてまいったという経過です。","voiceIndex":81,"id":"exchange-035"},{"speaker":"中塚委員","kind":"質問・要望","question":"今の基準で言いますと、例えば、児童数が１５０人未満であれば３人、２５０人未満であれば４人、４５０人未満であれば５人、それ以上であればプラス１という形の基準がありますけれども、この基準を変えるという考えでよろしいのでしょうか。それとも、参加の児童に応じて日々変わっていくんでしょうか。その辺のところを、もう一度、伺いたいと思うのが１点。","respondent":"富田教育改革担当課長","answer":"今年度、９月後半実施してきて、およその現在の参加状況というのは把握してきているところであります。","voiceIndex":83,"id":"exchange-036"},{"speaker":"中塚委員","kind":"質問・要望","question":"参加者でと繰り返していますけれども、その基準を示していただきたいんです。必ず週２回休まなければならないのに、１人の中で業務が多くなって、実際に１カ月半以上休めてないといった話も伺っております。その実態がほんとうに正しいのかどうかも確認したいんですけれども、改めて、専任指導員は複数配置、これは今でも求められていると思います。４月以降になったら、当然、参加数は増えますよね。","respondent":"富田教育改革担当課長","answer":"９月下旬から、新たに１５校、立ち上げをいたしました。その中では、新しい児童の参加、新しい指導体制というところで、現場では、さまざま苦労しながら実施をしてきているものと思います。","voiceIndex":85,"id":"exchange-037"},{"speaker":"中塚委員","kind":"質問・要望","question":"休日出勤として１.２５倍ですか、その辺のところがちゃんと支払われているかどうかというのも確認したいんです。専任職員が日々苦労されて、このまま改善の見込みがないままで、今の専任指導員１のままでは、ほんとうに精神的にきついという話も伺っております。新聞報道によると、当日、通っていた子どもたちはおよそ８０人、それに対して、指導員が７人だったと伺いました。お答えください。","respondent":"富田教育改革担当課長","answer":"川崎のわくわくプラザとの数の比較をされたわけですけれども、川崎のわくわくプラザとすまいるスクールとは実際、配置している人の内容ですとか、違っている事業ですので、単純に比較することはできないと考えております。","voiceIndex":87,"id":"exchange-038"},{"speaker":"中塚委員","kind":"質問・要望","question":"具体的には、先日、子どもの前歯が折れる事件が、２件続けて起きたという話も伺いました。すまいるスクールでは、児童の特に留守家庭の児童を把握するわけですから、日常通う子どもたちを把握できるわけですね。せめて、こういう子どもたちだけでも、個人のロッカーをきちんと設置してあげることが、生活の場を保障することになると思いますけれども、いかがでしょうか。","respondent":"富田教育改革担当課長","answer":"全体として、教室の活用等々を含めまして、安心して利用いただけるように、現場現場で状況が違ってまいりますので、そういったところを、今後、いろいろ検討していきたいと考えております。","voiceIndex":89,"id":"exchange-039"},{"speaker":"中塚委員","kind":"質問","question":"３０人学級のところは質問できなかったので、それは別途、後で質問するとして、今の説明に対して、事故が起きた後、指導員を集めて、どこの位置にいれば、子どもたちが見わたせるのかという指導を行ったと言うんですけれども、学童保育クラブでは、どうやって事故を防いでいるんですかね。これでほんとうに、子どもの安全が確保できるのかどうか。その点を、もう一度教えてほしい。","respondent":"富田教育改革担当課長","answer":"これまでもそういった内容できておりますし、これからも同様に、すまいるスクールの中で、そういった着替えを含めて、ロッカーのスペースでということでやってまいりたいと考えています。","voiceIndex":92,"id":"exchange-040"},{"speaker":"伊藤委員","kind":"確認","question":"それぞれ、この請願については、過去３回ですか、同趣旨の請願をこの委員会で審議をしてまいりました。むしろ、本質の部分の児童の安全確保、それからさまざまな不備を対処するためには、新しいそういう仕組みづくりしたほうがいいのではないですかということを確認したいので、学校資源の活用とか、学校の人材の活用とか、そういうことについての答弁をお願いいたします。","respondent":"富田教育改革担当課長","answer":"まだまだ不十分なところも多くありますので、今後とも、そういった他の支援を受けて、子どもたちを地域、学校、保護者を含めて育てていくという、こういう視点をさらに強化して育ててまいりたいと考えております。","voiceIndex":96,"id":"exchange-041"},{"speaker":"伊藤委員","kind":"質問","question":"いろいろありがとうあります。ですから、ここに書かれていることすべてを実行することではなくて、むしろ新しい事業に対して学校の資源、人材の有効活用をしていくことを通して、児童の安全確保、それからさまざまな環境の整備していくことのほうがプラスになっていくと思われますので、その分、もう少し力強い答弁をいただければありがたいんですが。","respondent":"富田教育改革担当課長","answer":"現在、すまいるスクールは１９校になってまいりましたが、例えば、学校の運営計画の中にすまいるスクールを位置づけるなど、また、生活指導の面におきましても、学校との全面的な連携教育を行うなど、それぞれの学校でさまざまな連携した取り組みが発展してきております。","voiceIndex":98,"id":"exchange-042"},{"speaker":"伊藤委員","kind":"質問","question":"３番のところの小中学校の新しい事業支援等の説明のことについては、現場の声をどういうふうに集約していくのかということ、それから、具体的な説明はどうされていくかということを、もう一度、答弁ください。それだけ教育の現場というのは大変なんでしょう。裏返して言えば、それだけ現場の教師の皆さんが頑張れない状態があるのかどうかということを、お聞かせください、お願いします。","respondent":"古川教育次長、中島指導課長","answer":"一つひとつを取り上げますと、どちらがいいとか、どちらがどうだという議論になってまいりますが、大きなこれからの事業の展開ということで、すまいるスクールを育てていきたいと思ってありますので。決して、３０人以下でなければ品川区の教育改革が進まないということはないと考えております。","voiceIndex":100,"id":"exchange-043"},{"speaker":"伊藤委員","kind":"質問・要望","question":"それが、先に立つべきだと考えています。ですから、この３０人以下学級のことについても、これはいろいろな議論があるかもしれませんが、もし３０人以下でなければ、品川区の事業が成り立たないとか、ここに書かれている内容というのは、この請願を読み取ると、３０人以下でなければ、すべての子どもに手が行き届かない、教育ができないということですから、できるという答弁をはっきりといただきたい。","respondent":"中島指導課長","answer":"具体的に成果を上げていただいている状況で、教育委員会では喜んでおります。３０人以下でないと、決して十分な教育ができないということはないと確信しております。","voiceIndex":103,"id":"exchange-044"},{"speaker":"伊藤委員","kind":"意見","question":"先ほど、お話しさせていただきましたように、この請願については、この委員会で、過去、これも含めて３回議論していますし、その背景が、例えば大きな法律改正があったとか、この事業に関連してさまざまな経済情勢が変わったとか、社会情勢が変わったということがあったら話は別ですけれども、どうも私はそうは思えないので、あとは委員長の議事整理にお任せいたしますけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":105,"id":"exchange-045"},{"speaker":"沢田委員","kind":"質問・要望","question":"何か、私、まだ一度も質問していないのに、請願の取り扱いにまで入っちゃうというのは、今、ちょっとどうかなという気がするんですけれども、何点か質問させていただきたいと思います。","respondent":"富田教育改革担当課長","answer":"ただいまのご質問ですが、すまいるスクールの点につきましては、９月に１５校開設ということでございまして、保護者には、７月に実施内容等についての参加意向を含めましてのアンケート調査を行い、８月の下旬から９月の下旬にかけまして、開設の説明会を１５校。","voiceIndex":106,"id":"exchange-046"},{"speaker":"沢田委員","kind":"意見","question":"要するに、関係者の意向をきちっと聞いて進めてきたのかということを聞きたいんです。","respondent":"富田教育改革担当課長","answer":"その後、再編成の内容について、変更事項について、厚生委員会でご説明をしたのが８月２６日です。したがいまして、変更事項を厚生委員会に報告する前に、８月に、こういった内容について決定をしたということであります。","voiceIndex":108,"id":"exchange-047"},{"speaker":"沢田委員","kind":"質問","question":"そうしますと、６月３０日の厚生委員会にある程度方針は出して、８月２６日の段階では、もう少し具体的な移行の方針を出して、その中間の８月中旬に、区として、学童保育クラブの移行と廃止を決定しているわけですね、区長決定。そのあとに、すまいるスクールの説明会が行われた。この決定する前の段階で、関係者への説明、あるいは、声を聞こうとする努力は、どのようにされたんでしょうか。","respondent":"古川教育次長","answer":"各段階で、具体的にどのような形でというのは、大変申しわけございません、福祉事業部が個々に対応した部分もあろうかと思いますので、そこまで、私のほうでは承知してございませんけれども、少なくとも学童保育クラブの事業を。","voiceIndex":110,"id":"exchange-048"},{"speaker":"沢田委員","kind":"質問","question":"順序が逆転をしているんですよ。法律、行動指針に基づいてないじゃないですか。しかも廃止をするという。次世代育成支援対策推進法というのは、一体何なんでしょうか。改めて、川崎市の４月直近までの間にどんな事故が起き、それをどう克服しようしているのか、区として、来年スタートするわけですから、きっと検討していると思うんですけれども、対策の方針について説明してほしいと思います。","respondent":"富田教育改革担当課長","answer":"川崎市には、私どもも視察には行ってまいりましたが、事故等の詳細については、まだ把握をしておりません。したがいまして、新聞報道等の域を出るものではありません。今後、そういった点につきましても、情報等を収集しながら、再度、検討はしてまいりたいと考えております。","voiceIndex":112,"id":"exchange-049"},{"speaker":"沢田委員","kind":"質問","question":"だから、新聞報道しかわからないというんじゃなくて、すぐに区が現地に赴いて、事故がなぜ起きたのか、品川区で起きないようにするためにどうしたらいいのかということを考えるべきだと、私は思います。１名減になりますよね。先ほどの質問に加えて、ちょっと聞きたいんですけれども、すまいるスクール三木で事故が起きない保障というのはあるんでしょうか。その２点を、まずお尋ねしたいと思います。","respondent":"富田教育改革担当課長","answer":"しかしながら、子どもたちがそういった遊び、スポーツを含めて、さまざまな活動を展開する中で、事故が１００％起きないというお約束というのは、ちょっとだれにもできないことかなと考えています。","voiceIndex":114,"id":"exchange-050"},{"speaker":"沢田委員","kind":"質問","question":"すまいるスクール三木の問題は、これは既にやっている問題ですから、これ以上言いませんけれども、こんなに手薄になったら、子どもを常時安全管理をするということに穴があくと思うんですよ。ですから、ぜひ、川崎市から教訓を学んで、事故が起きないように。ですから、私は、やっぱり常勤の最低限２人体制はどうしても必要なんじゃないかというふうに思っているんです。","respondent":"古川教育次長","answer":"もちろん常勤と非常勤の基本的な雇用条件の違いは歴然とありますけれども、私どもは、常勤であろうと、非常勤であろうと、この仕事に就く以上は、責任を持って仕事にあたるということで、日々、すまいるスクールの事業に当たっていきたいと考えているところです。","voiceIndex":116,"id":"exchange-051"},{"speaker":"沢田委員","kind":"質問・要望","question":"だから、ここについては、くれぐれも万全の対策を求めたいと思います。出欠カードの確認、それから、そのほかに物品の購入もあれば、勤務のシフトもある、毎日毎日登録者が増えてきますから、その受け付けと金銭管理がある。それに加えて、今後は連絡帳の記入が新たに加わり所在確認が加わる。そうすると、例えば５人でやっていて、非常勤が４人だったら１人はとられる。１人は学習のほうに５日制が取られる。","respondent":"富田教育改革担当課長","answer":"事故のとき、また風水害等で早めに帰宅するとき等々の緊急連絡用ということで書いていただいておりますが、これに加えて、保護者のご両親が働いていらっしゃる場合には、その就労先ですとか、あるいは、活動されている場合は、その活動先等々ということで。","voiceIndex":118,"id":"exchange-052"},{"speaker":"沢田委員","kind":"質問","question":"そのときに、自分の子どもが危ない道路で遊んでないかどうかだとか、ぐあいが悪いんじゃないかと心配したときに連絡を取ろうということですから、具体的にちょっと今、答弁がなかったんですが、すまいるスクールに子どもが来なかった場合には、そこから保護者や家庭やらに電話をするということなんですか。もし電話をして連絡がつかなかったり、何かした場合には、対策が講じられるんでしょうか。","respondent":"富田教育改革担当課長","answer":"緊急の連絡というのは、さまざま意味があろうかと思いますけれども、一応、これまでの答弁等でも申し上げてきておりますが、１、２年生の希望する保護者には、出席予定をあらかじめいただいていて、急に欠席をされた場合には、保護者あてに電話連絡をするということで。","voiceIndex":120,"id":"exchange-053"},{"speaker":"沢田委員","kind":"質問・要望","question":"じゃあ、これで最後。今の点での要望と質問を、もう一つだけさせてください。そういうことのないように、この点についても、万全の態勢をやっぱりとるようにお願いしたいと思います。最後の質問なんですけれども、障害児の保育預かりについて、前に中塚委員が質問をして、検討するとなっていたんですけれども、その後どうなったでしょうか。","respondent":"富田教育改革担当課長","answer":"すまいるスクール実施校のお子さんで、学童保育クラブを利用されているお子さんについては、学童保育クラブではなく、すまいるスクールを利用していただくということに、来年度からなってまいりますので、利用する先としては、学童保育クラブ利用のお子さんについては。","voiceIndex":122,"id":"exchange-054"},{"speaker":"沢田委員","kind":"質問","question":"これも、一歩前進したと思いますけれども、今、学童保育クラブに預けている障害児は、すまいるスクールに移行しても、そのまますまいるスクールのほうで預かっていただけると。そうすると、その態勢はとれるんでしょうか。例えば非常勤を１名つけるとかということは。","respondent":"富田教育改革担当課長","answer":"はい、全体として必要な参加児童の状況を把握しまして、必要な人員は配置してまいりたいと考えております。","voiceIndex":124,"id":"exchange-055"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから１カ所がいろいろ事件が起きた、問題が起きたということになりますと、それが全部の１２０校近くのわくわくプラザ全部にかかわってしまうというふうにとらえがちなんですが、決してそうでなくて、それぞれの中で大変工夫されていて、非常にすばらしいなというところもあります。その上に立って複数担任というような考え方はどうなんだろうかと。そういう点について、まずご質問したいと思います。","respondent":"富田教育改革担当課長","answer":"この内容を広げていくに当たりましては、専任指導員が中心になりながら、各すまいるスクールに２名の教員免許のある指導員を配置しておりますので、この３人ががっちり中心となって、他の指導補助員等々を指導していけるような。","voiceIndex":126,"id":"exchange-056"},{"speaker":"西本委員","kind":"質問","question":"何かしらの目安みたいなものをつくっていかないと、やはり学童保育クラブを見てみますと、指導員によってやり方が全然違うということがあります。そこの学校の中での特徴をどうやって生かしながら、すまいるスクールが今後どんどん発展していく中で、継続性をどういうふうに考えていったらいいのかというところの今後のやり方、そこら辺はどういうふうに進めていこうとされているんでしょうか。","respondent":"富田教育改革担当課長","answer":"そういったところは、これから運営内容、それぞれの学校の、そういった教育内容なり、方針といったものに、できるだけ近づけるような形でのすまいるスクールのあり方というのを目指しつつ、すまいるスクールとしての統一のものもつくっていくというような形で、やはり。","voiceIndex":128,"id":"exchange-057"},{"speaker":"西本委員","kind":"質問","question":"現場、現場で、いろいろの考え方の人がいらっしゃると思います。ですから、ほんとうに必要なのか、どうか、運営方法も区のほうがやってくださいということではなくて、地域の方たちと一緒に何かできないだろうかということで、やっぱり要らないんじゃないかという意見も当然出てくるかと思いますので、現場主導で何か検討できるような機関が持てないものなのか。そこら辺のお考えは、いかがでしょうか。","respondent":"富田教育改革担当課長","answer":"そういうような中で、すまいるスクールとしては、参加しているすべてのお子さんが楽しく、充実した活動を帰る時間まで十分にできるように、そういったことに力を注いでまいりたいと考えております。","voiceIndex":130,"id":"exchange-058"},{"speaker":"西本委員","kind":"提案","question":"カーテンを閉めたり、場所を変えて別々に食べさせるということがほんとうにいいのかどうか、そういう弊害を含めながら、さて、皆さんどうしましょうかという提案をしながら考えていくという機関を、少し設けていただいてはいかがかなと。同じご答弁になるかと思いますので、次にいきたいと思います。品川区の現状として、かなり少人数のクラスになっていくのではないかなと、その辺はいかがでしょうか。","respondent":"谷田部学務課長","answer":"中学校のほうは、逆に、７５％が３１人の学級で編成しているという状況になってあります。","voiceIndex":132,"id":"exchange-059"},{"speaker":"西本委員","kind":"質問","question":"もちろん中学生になりますと、生活指導というのが入っておりますので、少人数のほうが助かるという部分もあるとは思うんですけれども、そういう意味では、小学校の１年生のところで、３５人ぐらいまでは何とかなると思うんですが、４０人ぎりぎりの２クラスになるかならないかというところに対しての対処、例えばＴＴとか、そういうふうなのは設けられてはいないのでしょうか。","respondent":"中島指導課長","answer":"小学校の低学年でのＴＴ少人数の実施ですけれども、今年度、１年生からＴＴ少人数の実施している小学校というのは、大つかみですが、全体の半分ぐらいです。","voiceIndex":134,"id":"exchange-060"},{"speaker":"西本委員","kind":"質問","question":"そうしますと、現状、品川区内の公立小中学校においては、少人数というとらえ方は、ある程度、運営上、できているというふうに、かなり近い状態で運営されているというふうな理解でよろしいんでしょうか。","respondent":"中島指導課長","answer":"今、ＴＴと少人数の加配の教員という形でお答えしましたけれども、それ以外に、もうご存じの習熟度別学習を実施していますので、そちらのほうを合わせますと、１年生から実施している学校は、小学校について全体の８割です。","voiceIndex":136,"id":"exchange-061"},{"speaker":"西本委員","kind":"質問・要望","question":"３０人学級というこの請願の中でですが、今、子どもたちの状況を見たときに、品川区の現状として、少子化ということもありますから、大体はカバーはされているだろうと。これは、ちょっと意見として終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":138,"id":"exchange-062"},{"speaker":"山路委員","kind":"質問","question":"この中で柱なるのは何かなと思って、ずっとさっきからお聞きしていたんですけれども、２番目の「すべての子どもたちのための放課後の安定した居場所として、すまいるスクールを充実してください」というのが大きな柱かなと。ちょっとこの文章自体が抽象的で、もうちょっと具体的に、ここのねらいといいますか、言いたいことはどういうことか掌握されている中で、説明をしていただけますでしょうか。","respondent":"富田教育改革担当課長","answer":"請願項目の１の部分でございましょうか。〔「２番」と呼ぶ者あり〕失礼いたしました。これまですまいるスクールで実施してきております全児童対象の子どもたちの居場所としてのすまいるスクールを充実、これまで同様に充実してほしいという趣旨だろうと受けとめております。","voiceIndex":139,"id":"exchange-063"},{"speaker":"山路委員","kind":"質問","question":"申しわけございませんね、大きな質問でしたね、熱心に取り組んでいらっしゃる教育改革担当課長だから答えられると思って質問したんです。その基本法について、厚生労働省が主でしょうけれども、文部科学省も非常に関係性が深いと思いますので、趣旨をちょっと聞かせていただけますでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":141,"id":"exchange-064"},{"speaker":"山路委員","kind":"質問","question":"その中にありまして、親の責務ということを基本にすまいるスクールというのは展開して、社会全体が大きく子育てということで変わるわけですから、その中の保育、幼稚園または在宅保育、または小学児童、生徒の子育てと大きい枠の中で、社会全体が変わる中での児童のすまいるスクールというのを考えていかなきゃいけないんじゃないかという感じがするんです。そこをちょっとお聞かせいただけますか。","respondent":"富田教育改革担当課長","answer":"現時点では、すまいるスクールを全校に実施している状況ではございませんので、そういう意味では、実施計画、１０校ということで計画をしております。実施計画にのっとって、残された学校でのすまいるスクールの開設に努めていくことが、まず一つには挙げられるかと思います。","voiceIndex":144,"id":"exchange-065"},{"speaker":"山路委員","kind":"質問・要望","question":"事業所でも、これから男性の子育てに対する方向に時間を取られるわけですよね、就業時間を短くして。その辺について、現時点ではまだ希望者だけ。もちろんお子さんで一番大事なのは、本人が好きなことを目指すものが、子育てにおいては非常に伸びるというデータ等、いろいろお話も聞いているんですけれども、その先のお考えはどう検討されているか、ちょっと聞かせていただきたいと思います。","respondent":"古川教育次長","answer":"従前の考え方が、さまざまの形で、すべてのという言葉に代表されますように、個別分野での対応から、全体に対する対応というふうに大きな流れがあるのかなととらえてあります。","voiceIndex":146,"id":"exchange-066"},{"speaker":"山路委員","kind":"質問・要望","question":"現場でいろいろな意見を聞くんです。特に小中一貫校は、一番変わり目の小学校５年生に視点を置かれているという、そういう点では、特に重要な一つの事業に入ってくるんじゃないかと思うんです。その辺の確信とお母さん方に納得と安心を与えるような事業転換をしていただきたいということを、一言意見を述べさせていただきまして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":148,"id":"exchange-067"},{"speaker":"本間委員","kind":"質問","question":"一応、考え方あるいは意見を取りまとめるということならば、用意はしておりますが、質問というような部分では。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":149,"id":"exchange-068"},{"speaker":"石田副委員長","kind":"質問","question":"１点だけ、お伺いをします。その不安を解消してくれと。そこら辺の意見の把握というのはどういうふうにされていて、私が聞いている範囲では、さっき出た不安を言ってないような気がしているわけです。そこら辺の点を、どのように把握して、今度新たにスタートしたところにも生かしていくかということを、教えてください。","respondent":"富田教育改革担当課長","answer":"したがいまして、これからもそういった説明会も開いてまいりますし、また、そういう意味では、来年度の募集に当たっての説明会、また来年度以降の保護者会等々、これまで以上にそういった保護者の方への説明というものは丁寧に行って。","voiceIndex":151,"id":"exchange-069"},{"speaker":"石田副委員長","kind":"質問・要望","question":"前の１校から４校というところからスタートとして、大分、お話も聞いてきている。それをやっていかないと、１００％の合意形成はないわけですから、安易に合意形成をとるために、じゃあ、この部分はこうしましょう、こういうことはこうしましょうとやっているうちに、すまいるスクールの良さが、もしかすると、ちょっと違う方向へ動く可能性もあると思うんです。","respondent":"富田教育改革担当課長","answer":"したがって、そういった先行例といいますか、そういったところの保護者参加を参考にしながら、他校についても、そういったものを進めて安心して利用していただけるようなすまいるスクールという、いわゆる合意がいただけるような内容としていくように努めています。","voiceIndex":153,"id":"exchange-070"},{"speaker":"中塚委員","kind":"質問・要望","question":"１点だけ、すみません。これを見ますと、発生場所とか、けがの程度その後の経過、また学校数とあるんですけれども、品川区でも保健室を利用して事故の手当てをしますので、こういった事故報告集計書というのがあると思っているんですけれども、ぜひこちらを公表していただきたいというのが１点だけです。","respondent":"谷田部学務課長","answer":"私のほうで保健の関係を担当しておりますので、お答え申し上げます。私ども、そういうふうに、どこの学校で、どういう事故か起こったというようなことは公表はしてございません。","voiceIndex":159,"id":"exchange-071"},{"speaker":"沢田委員","kind":"質問","question":"すみません、二度にわたって申しわけありません。しかし、生活集団として、やっぱり４０人ぐらいが適切だというふうに言ってきて、事実上、少人数学級の気持ちというか、それは実施しているんだという態度を繰り返しに明らかにしているんですが、生活集団としての４０人が適切だという研究結果みたいなものは、どんなことに出てきているんでしょうか。","respondent":"中島指導課長","answer":"４０人という生活の集団ですけれども、一つには、これまでの学級の中でのさまざまな生活の編成、組織づくり、こういった部分で、例えば、５人のグループが八つ、それから１０人の運動のチームが四つ、給食の班といったような中での集団的な集まりが。","voiceIndex":161,"id":"exchange-072"},{"speaker":"沢田委員","kind":"質問","question":"時間がないですから、区のほうでごらんになっているかもしれないんですけれども、不登校の減少、学力の向上、欠席の減少、読書量の増加、保健室利用の減少、これは鈴木ひろ子議員が全部紹介をしたところなんです。だけど、教員の間からは、即効的に自分の支えてほしいというので、期待もあると、両面も見ているんです。少人数学級の教育に及ぶすいい面というのは。その点はいかがでしょうか。","respondent":"中島指導課長","answer":"私どもも、同様の資料を幾つか手元にありますけれども、例えば、国立教育政策研究所のほうで、１学級２０人以下の場合、大きな規模の学級よりも理数系の成績がよくて、教師から個別指導を受けた経験も多いというような結果が、事実としては出ていることは認識しております。","voiceIndex":163,"id":"exchange-073"},{"speaker":"沢田委員","kind":"意見","question":"これで終わりますので、すみません。子どもの７割ぐらいは、アンケートなんかを取ると歓迎している。生活指導上、少なすぎるというのは何度も言われたから、そうおっしゃるのかもしれないですけれども、繰り返しになるので、もうこれでやめますけれども、少人数学級のチャレンジをぜひやってほしいことだけ述べて終わりたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":165,"id":"exchange-074"},{"speaker":"伊藤委員","kind":"意見","question":"この請願につきましては、きょう結論を出すということをお願いしたいと考えています。ただ、この請願に書かれているように、現行のすまいるスクールに１００％、今やっている学童保育クラブの事業を入れることはできない話である。ましてや、そういうところに動いているという答弁もいただきましたので、そういうふうなことを願いながら、この請願につきましては不採択と考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":168,"id":"exchange-075"},{"speaker":"山路委員","kind":"質問","question":"今までも、項目につきましては、何回も議論してきましたので、きょうは別の角度から質問をさせていただいたんですが、先ほど言いましたように、すまいるスクールの事業が大事なのは当然ですけれども、事業以外の放課後授業としての子育てに非常に重要なものと思いまして、そこを重点的に質問させていただきましたが、請願項目全体からいろいろ考えますと、反対です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":169,"id":"exchange-076"},{"speaker":"沢田委員","kind":"質問・要望","question":"そのためには一定の時間もかかるでしょうから、ぜひ、区教育委員会として現地を調べてもらって、今後の対策を報告をしていただきたいということだとか、それから、所在確認をやるというんですけれども、現実に、今の専任１人と非常勤４人、あるいは５人ぐらいの体制で、すまいるスクールの子どもがこれから、来年４月以降増える、私、率直に言って、やっていけるのかと感じます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":170,"id":"exchange-077"},{"speaker":"本間委員","kind":"質問・要望","question":"子どもたちのための放課後の安定した居場所としてのすまいるスクールを充実してほしいというような部分で、今、スタートしたばかりですけれども、お話を聞きましたとおり、実績をもとに来年実施の増えるところも含めまして、あるいは、これまでのモデル校の実施を含めて、着々とその成果を積み上げてきている段階だと思っていますので、これはこれとして、十分趣旨が、１、２。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":171,"id":"exchange-078"},{"speaker":"西本委員","kind":"質問・要望","question":"無所属の会としては、１番と２番の関係性というのが、よく理解できないというのが多少あります。それから、３０人という人数でくくるということよりも、子どもたちの現状に応じた形で、いろいろな工夫があるべきではないかという視点に立って、私たちは考えておりますので、本日、結論を出していただきたいということと、態度表明としては、不採択でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":172,"id":"exchange-079"},{"speaker":"沢田委員","kind":"意見","question":"先ほどは、扱いについての可否をやったので、もしきょう結論を出すというのでは、もう意見を述べた方もいらっしゃいますけれども、私は述べていませんので、述べさせていただけるとありがたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":175,"id":"exchange-080"},{"speaker":"沢田委員","kind":"質問","question":"３番についてもそうです。だから、私は、そういう点から言って、根本の問題がそこにあると思いますけれども、ここで言っている一つ一つのことは、今までの学童保育クラブでやられたことを、引き継ぎ、発展をさせてほしいという願いですから、１、２は当然だと思います。子どもたちのためにも、ほんとうに３０人学級は、私は少人数学級と置きかえて読みますけれども、当然、採択すべきものだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":177,"id":"exchange-081"}]},{"id":"topic-03","title":"続きまして、３の報告事項","agenda":"続きまして、３の報告事項","exchanges":[{"speaker":"伊藤委員","kind":"質問・要望","question":"所管が直接でないと思いますので、わかる範囲で答弁していただきたいんですが、意見の中で、２の能力・業績及び職責に基づく給与制度の構築についてと書かれていますけれども、このことについて、何回も私たち、質問しているんですね。人事委員会の勧告と言ったんですけれども、これに対しての品川区の対処法、能力性ですとか、答えられますか。","respondent":"鷹倉庶務課長","answer":"これは人事委員会当局が進めていくものですので、私どもも、幼稚園職員の部分での検討はありますけれども、全般に係わる部分ですので、発言は控えさせていただきたいと思います。","voiceIndex":183,"id":"exchange-082"},{"speaker":"沢田委員","kind":"質問","question":"先ほどの荏原第一中学校なんですが、１４０人の住民基本台帳の数と、増減すると４７がプラスになりますね。そうしますと、荏原第一中学校というのは、これを足して４０で割ればいいんですけれども、キャパシティというんでしょうか、どんな感じなんでしょうか。","respondent":"谷田部学務課長","answer":"これは、今後、私立の中学校への入学ですとか、過去何年間で私立中学校への進学、それも私ども押さえてありますので、その辺の私立中学校等へ進学等も兼ね合いながら、４学級の中で１６０人の中に収まるだろうと、私ども予測していますので。","voiceIndex":190,"id":"exchange-083"},{"speaker":"沢田委員","kind":"質問","question":"あわせて小学校のほうも聞きたいんですが、全体として、私思っていたよりも、去年とカウント方法が違ったということなのか、よくわからないんですけれども、その中の第四日野小学校が、マイナス２５のプラス２となっているんですけれども、これは何か事情があるんでしょうか。","respondent":"谷田部学務課長","answer":"２５人は、ブロック外の現象を見てありますので、実際には、ブロックの中で１４人、ほかの学校を選んだです。","voiceIndex":192,"id":"exchange-084"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4488#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":73510,"voices":198}},{"id":"h15-20031125-5","meetingId":"h15-cm11","date":"2003年11月25日","dateIso":"2003-11-25","committee":"総務委員会","time":"午前１０時０５分～午後１時４０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"１の第５９号議案 選挙長等の報酬および費用弁償に関する条例の一部を改正する条例","agenda":"１の第５９号議案 選挙長等の報酬および費用弁償に関する条例の一部を改正する条例","exchanges":[{"speaker":"林（宏）委員","kind":"質問","question":"１つは、今の説明の中にも出てきたんだけれども、不在者投票という呼び方というか、名称というか、それと期日前投票という、一般の人たち、有権者の人たちにはどういう説明をしていけばいいのか。それから、報酬については、前は幾らだったんですか。","respondent":"野田口選挙管理委員会事務局長","answer":"今回変わるのは、地域センターと本庁で行われる、名簿登録地の市町村で行われる不在者投票が期日前投票というふうに変わるんですけれども、呼称については、法律名が期日前投票ですので、そういった形で法律上の周知はしなくてはならないんですけれども、要は。","voiceIndex":7,"id":"exchange-001"},{"speaker":"林（宏）委員","kind":"確認","question":"それに付随してもう一方で、本人確認ということが非常にしづらいというのか、今回も捕まった人がいますよね、本人以外で。その辺の確認についての、いわゆる選挙管理委員会としては、１００％本人以外の人は投票されては困るということですよね、本来は。それが何％、１００％になりますかね。何のチェックもなく投票できちゃうでしょう。説明してください。","respondent":"野田口選挙管理委員会事務局長","answer":"本人以外の人が来たときに、それをチェックするためにそういった表示をしておきます。そのときに、その時点で生年月日、あるいは身分証明書等の本人確認をした上で、それで対応しています。そういった意味で、１００％本人であるかどうかという確認はなかなか難しい。","voiceIndex":9,"id":"exchange-002"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"それでいいかどうか。Ａ投票所に林宏は行きなさいと。その辺の確認というのは、これから電子投票というようなことも言われてきて、確認の仕方も変わってくるんだろうけれども、公平、それからさっき言った、１００％確認をしていくんだという、投票率を上げるということと同時に、本人確認ということに相当神経を使っていただくというのが大前提だと思うんですよね。","respondent":"野田口選挙管理委員会事務局長","answer":"ただ、不在者投票と変わらないのは、投票日の当日、何らかの用があって行かれない見込みですよということと、それが間違いなくそのとおりですという宣誓書を不在者投票と同じように提出する、このことについての手続きは変わってございませんので、そういった意味で。","voiceIndex":11,"id":"exchange-003"},{"speaker":"土井委員","kind":"質問・要望","question":"その報酬等の内容等についてはわかります。ちょっとお伺いをしておきたいのは、期日前投票所における投票管理者、あるいは投票立会人、どのような形でどういう選出がされて任命をしていくのかというところをお聞かせをいただきたいと思うんです。","respondent":"野田口選挙管理委員会事務局長","answer":"投票立会人についても、２名から５名ということになってありますけれども、今回の場合については２名ということですので、そういったことできちっと配置していくです。","voiceIndex":14,"id":"exchange-004"},{"speaker":"土井委員","kind":"意見","question":"投票立会人については、明るい選挙推進協議会のほうに推薦をお願いをして、それを選挙管理委員会の中で任命をするという形で権限を委譲するという形になっている。投票管理者については、同じでないようでもあり、同じのようでもあるように今聞こえたんですけれども、そこをもう１回。","respondent":"野田口選挙管理委員会事務局長","answer":"説明が不十分だったので。投票管理者も投票立会人も明るい選挙推進協議会のほうに推薦を依頼していくという、全く同じです。すみません、ちょっと補足説明を。","voiceIndex":16,"id":"exchange-005"},{"speaker":"土井委員","kind":"意見","question":"そうすると、皆さんに対する、ふだんからそれができる方なのかできない方なのか、ないと言ったら失礼に当たるけれども、お力を持ちになっているのかないのかということ等の認定をするという形の中でやらなきゃいけないし、こういう制度ですよ、こういうふうにするんですよ、事務処理はこういうのがあるんですよ、トラブルがあったらこうするんですよという流れをきちんと。","respondent":"野田口選挙管理委員会事務局長","answer":"今回、新たに選挙期日前投票制度もつくられましたので、その説明会も、投票所と全く同じような流れになりますけれども、それもきちっとそういった説明会、あるいは明るい選挙推進協議会の研修会等においてでも。","voiceIndex":18,"id":"exchange-006"},{"speaker":"土井委員","kind":"質問","question":"中身的には、お話をされている内容はわかりました。例えば開票事務にしても、投票事務についても、最初、投票管理者と事務者とがいらっしゃるという体制だというふうに思いますけれども、そうすると、投票管理者は、いわゆる選挙管理委員会がいろいろ推挙があって任命をした方、それから実際上事務をやる人は区の職員なのか、そこら辺も聞かせてください。ちょっと教えていただくと。","respondent":"野田口選挙管理委員会事務局長","answer":"繁忙期とか夜の部分もありますので、そういった部分は人材派遣会社のほうから、人をそれなりに研修等を行って、きちっと配置して、そういった人員体制で大体３名ぐらい。","voiceIndex":20,"id":"exchange-007"},{"speaker":"土井委員","kind":"質問","question":"ちょっとお話したんですけれども、この中身は、今回の投票、これはどうだったのか、要するに報酬的にはどういうふうにされたのかという問題がある。それから派遣会社ですと、それは派遣会社が教育するのかうちが教育するのかわかりませんけれども、研修をするのかわかりませんけれども、そういう問題は、報酬的なものも含めてどのように処理しているんですか。","respondent":"野田口選挙管理委員会事務局長","answer":"だから、３分の１ぐらいが軽減されるということになるのが前回の選挙での比較です。それから、地域センターで行っている場合については、日曜日を除けば、基本的には勤務時間内で対応しますので、勤務時間内についてはそういう対応ということでお願いしています。","voiceIndex":22,"id":"exchange-008"},{"speaker":"土井委員","kind":"質問","question":"派遣会社に頼むのはどういうときなんですか。もう１回ちょっと、日曜日とかそういうときだけなんですか。","respondent":"野田口選挙管理委員会事務局長","answer":"特に夜等については、やっぱり職員が残れないような状況もありますので、そういったことについては人材派遣会社、それから日曜日とか土曜日、そういったときに職員で手当できない部分については人材派遣会社の方を手厚く配置している、そういった対応です。","voiceIndex":24,"id":"exchange-009"},{"speaker":"土井委員","kind":"質問","question":"わかりました。となると、人事といったら語弊があるかもしれないけれども、人材派遣会社にその後すとーんととんでいくのになんかちょっと違和感を覚えなくもないんだけれども、いろいろな方が役所の中にいらっしゃいますよね。いろいろな方々が、もしくは役所関係者。そこら辺との関係は、すぐ人材会社にとんでいくのと我々との関係で、承知されてやっていらっしゃるんですか。","respondent":"野田口選挙管理委員会事務局長","answer":"ところが、選挙時に、選挙管理委員会の事務局というのは７、８名で回していますので、そういうアルバイトの募集とか従事者を登録してどうのこうのと、こういうことをやっている時間的な余裕がないものですから、そういった意味で。","voiceIndex":26,"id":"exchange-010"},{"speaker":"土井委員","kind":"意見","question":"わかりました。昔いろいろな選挙事務をやった人もいらっしゃるわけね。だから、そういうところをこれからうまいぐあいに活用というか、やっていただくと、選挙管理委員会のほうで研修をしたりする時間がかなり省略できるとか、そういう問題等々も出てくるだろうと思いますので、よく掌握していただいて、対応していただくということをお願いをしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":28,"id":"exchange-011"},{"speaker":"築舘委員","kind":"質問・要望","question":"ちょっと今聞いていてわからないところがあったので、もう１回ちょっと教えていただきたいんですけれども、たしか１３地域センターで、本庁も含めてやるわけですよね。その場合に投票管理者というのはどういう方が、要するに、明るい選挙推進協議会から推薦をされたということをさっきご説明があったんだけれども、どういう方がやるのか。","respondent":"野田口選挙管理委員会事務局長","answer":"現在でも投票所の投票管理者については、明るい選挙推進協議会のほうに推薦を依頼して、推進委員の中から依頼して行っております。全く同じように、期日前投票についても同じような形で協議会に推薦依頼をして、推薦依頼するという……。","voiceIndex":29,"id":"exchange-012"},{"speaker":"築舘委員","kind":"質問","question":"さっき土井委員と話をしていたのは、時間外で地域センターの人がやるというのは、投票立会人なんですか。","respondent":"野田口選挙管理委員会事務局長","answer":"投票管理者は、いわゆる投票を朝８時半から夜の８時までのいわゆる投票手続きについてすべての責任を持つ、そういった管理をする。その管理のもとに事務に従事する、それは地域センターの職員と、それから先ほど言ったアルバイトさんです。","voiceIndex":35,"id":"exchange-013"},{"speaker":"武内委員","kind":"質問","question":"今までは、不在者投票のときは投票管理者及び投票立会人というのは、主に職員の方がやっていらっしゃったわけですか。","respondent":"野田口選挙管理委員会事務局長","answer":"そういった意味では、投票管理者は常時その場所にいなくてもよかったということですけれども、今度は投票所と同じようになったので、直接そこに常駐して、その手続きを管理する、こういうものです。","voiceIndex":38,"id":"exchange-014"},{"speaker":"武内委員","kind":"意見","question":"単純に考えると、今までよりもトータルして費用がかなりかかってくるということだと思うんですが、これは１３地域センターで、いわゆる期日前投票の期間が１０日から１週間があると、それ掛ける投票管理者１万１,５００円、それと投票立会人が２人とすれば、そういうような費用がかかってくるということになってくると。","respondent":"野田口選挙管理委員会事務局長","answer":"そのとおりです。","voiceIndex":40,"id":"exchange-015"},{"speaker":"武内委員","kind":"質問","question":"これは、選挙はどれぐらい経費がかかるんでしょうか、概算でわかれば。","respondent":"野田口選挙管理委員会事務局長","answer":"その内訳は、本庁は、１６日間掛ける投票管理者１名と投票立会人２人分。それから地域センターのほうは、今１週間と考えていますので、その１週間分掛ける１３カ所分ということで経費がかかるというものです。","voiceIndex":42,"id":"exchange-016"},{"speaker":"宮崎委員","kind":"確認","question":"ちょっと１点だけ確認したいんですけれども、今回の費用弁償の件なんですけれども、この費用弁償と選挙のやり方、先ほど封筒に入れなくて直接投票箱に入れるやり方になって、これはいいんだけど、以前の説明のときに、もう既に投票箱に入れる投票になるという、そういう説明だったものですから、この前の総選挙でそういうふうになるのかなと思ったら、そうじゃなかったんですよね。","respondent":"野田口選挙管理委員会事務局長","answer":"８月の時点でも説明したと思うんですけれども、この制度が適用されるのは今年の１２月１日に行われる選挙からこの制度から適用される。今、直近で予想されている選挙が参議院選挙だということで、参議院選挙のお話をしました。","voiceIndex":45,"id":"exchange-017"}]},{"id":"topic-02","title":"では、総務委員会を再開いたします。 (2) の第６０号議案、土地の取得","agenda":"では、総務委員会を再開いたします。 (2) の第６０号議案、土地の取得","exchanges":[{"speaker":"土井委員","kind":"質問","question":"それを１点伺いたい。区有地がちょっとまとまってあるので、その辺も含めてちょっとお伺いをしたいというのが１点。それはすなわち、考えようによっては、契約金額等々も含めたこの金額であってみたり、あるいは財源的な意味での裏づけの問題であってみたりするのではなかろうかというふうに思っているものですから、その辺についてまずお伺いをしたいというふうに思っています。","respondent":"西島経理課長、市岡企画財政課長","answer":"前段の部分については私のほうからお答え申し上げます。この土地ですが、昭和２２年３月から国から借り受けておりまして、その前を調べてみたんですが、そこはちょっとわかりませんので調べてみたいと考えています。それを時価の５％相当を要求されますので、本件の場合、後ほどご説明があるかと思いますが、国有財産の特別措置法で２分の１の減額をまず受けております。","voiceIndex":53,"id":"exchange-018"},{"speaker":"土井委員","kind":"質問","question":"それであっても、１割分というのは、これから幾らなのかどうなのかという問題と、借地料がこれからどうだ、今までどうだったのか、これからどうなのかという問題との対比の問題があると。ただ、末永くずっと何十年、何百年とたっていけば、完全に自分のものになるわけですから、借地料になりませんので、その辺の判断があるんだろうと思うんですけれども、ちょっと具体的に教えていただけますか。","respondent":"市岡企画財政課長","answer":"少し細かい数字になりますが、実は、この用地購入費、予算でいえば２７億３,０００万円を計上してございました。これは先ほどちょっと申し上げたとおり、国有財産の地方公共団体には用地取得といことで、法律上、２分の１減額を受ける前提です。","voiceIndex":56,"id":"exchange-019"},{"speaker":"林（宏）委員","kind":"質問","question":"品川区で今までの賃借料８,０００万円弱、年間全校で払っているわけですけれども、今説明があったように、品川区としての自主財源の出し方というか、金額の部分と財調という部分、それからここに入っている更新料という、細かい数字になりますけれども、賃借料の品川区の部分について、何校で、幾らで、来年度にかかわる部分は幾らぐらいだったかというのを手元に資料があったら教えてください。","respondent":"西島経理課長","answer":"来年度、国から借りている土地ですけれども、１０校全部でございまして、その合計額が平成１５年度でいきますと約６,５００万円、第二延山小学校ですと、正確にいいますと１,５８０万６,７７４円です。","voiceIndex":59,"id":"exchange-020"},{"speaker":"林（宏）委員","kind":"意見","question":"とすると、本来は、こういう時代だから国もお金が欲しいという言い方はいいかどうかわかりませんけれども、無償で払い下げるというか、渡すというか、一番我々が望むところなんですけれども、来年度に限ってどういう交渉過程があって、財務省のほうの答えはこういうことなんだけれども、それに至る若干の説明をしていただけますか。","respondent":"市岡企画財政課長","answer":"この第二延山小学校については、具体的な改築計画を総合実施計画の中でも、それから当初予算の中でも、改築は数年先として、まず品川区として望ましい学校をつくるためにはぜひ校庭を自由に使えるような権利関係にしていったと、こういうことからスタートしまして。","voiceIndex":61,"id":"exchange-021"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"ゼロより多いのは仕方ないとして。そういう意味から、ぜひこれからも賃借料の低廉化というか、そういう部分も含めてやっていっていただきたいと思いますし、ここはほとんど九〇何％が国有地だったんだけれども、ほかの学校でこういう例はあるんですか。大概は部分的に借りているという学校だと記憶していますけれども、一番比率的に、あるいは半分以上の国有地が入っている学校というのはあるんですか。","respondent":"西島経理課長","answer":"次に大きいのは大間窪小学校、これがやはり４,０００平米ほどあります。３,０００平米台のところでは、後地小学校、それから大原小学校、延山小学校、この辺あたりが３,０００平米台の土地を国から借りているです。","voiceIndex":63,"id":"exchange-022"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"さっきどういうふうにしたら、いきさつがいろいろあって、そういう学校が出たという、各学校によっていろいろな理由、位置づけが違うと思うんだけれども、さっきからしつこいようだけれども、義務教育という施設をつくっていく土台というか、土地については、これからも、今半分以上のところもまだあるということであれば、ぜひ粘り強く交渉していただきたいなというふうに思いますし。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-023"},{"speaker":"本田委員","kind":"質問","question":"４８％ではなくて、もっと大きい減額をしているところもあるんではないかと思うんですけれども、東京２３区の中では同様の扱いが提示されているんだろうと思うんですが、その辺はどうですか、交渉の中で話は出ていないんですか。","respondent":"市岡企画財政課長","answer":"この減額、２分の１の公式の減額からさらに借地料を払ってきたという経緯が考慮されて減額をされたという、そういう申請をした自治体は品川区さんが初めてですということは、口頭ですけれども、お聞きしました。","voiceIndex":66,"id":"exchange-024"},{"speaker":"本田委員","kind":"質問","question":"全国的には地方交付税でしちゃっていると。残っている品川区の１０校、部分的な土地になりますけれども、これは今後、どういう計画で、できれば財調措置のほうでやっていったほうがいいのか、それとも５０％とかわずかなパーセントであっても、全部区有地にしちゃったほうがプラスなのか、その辺の検討はどういう方向になっているんでしょうか。","respondent":"市岡企画財政課長","answer":"今、それを詳しく見通すということは困難ですので、そういう動きと、それからもう一つは、財調がいつまでもこういう形で借地料を完全にカバーする制度としていくかどうかというのも、これも先行き不透明なところがありますから、そういう制度のスキームの動きをよくにらみながら。","voiceIndex":68,"id":"exchange-025"},{"speaker":"川西委員","kind":"質問","question":"この機会に改めて、今までの質問の中のまとめになるんですけれども、他の残っている学校用地、国有地について、実際に関東財務局から積極的に区で買い取らないかという正式な要請というのは全然ないのかあるのかということが１つです。それから、借地料の推移というのは、評価額がどんどん変わるんだけれども、国有地の場合はどうなっているのか教えてください。","respondent":"市岡企画財政課長","answer":"関東財務局からは、積極的に買ってほしいという動きは一切ありません。おそらく買う側の自治体の要請に基づいて交渉するほうが有利だという、そういう前提があると思います。","voiceIndex":71,"id":"exchange-026"},{"speaker":"林（宏）委員","kind":"質問","question":"いわゆる１２月１日からデジタル化がされるという、メディアがそういうことを言われているんだけれども、ケーブルテレビ品川の場合の、それの対応というのがなかなか聞こえてこなくて、まちの人にも、どういうふうになるのというようなことを聞かれるんだけれども、それについて、たまたまケーブルテレビが総務委員会所管なので、あした、一般質問の関連ではないんだけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1632#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":19756,"voices":81}},{"id":"h15-20031126-6","meetingId":"h15-cm11","date":"2003年11月26日","dateIso":"2003-11-26","committee":"区民委員会","time":"午前１０時０５分～午後０時１４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"南委員","kind":"質問","question":"１８名の方の発表ということで、それぞれ学校から１名ずつということですけれども、以前にも伺ったかもしれませんけれども、改めて各学校で選考がどういうふうに行われているのかということをお伺いしておきたいと思うんです。","respondent":"志村地域活動課長","answer":"やり方等につきましては、校長会それから中学校のＰＴＡ連合会にお諮りいたしまして、決まりといいますか、例えば先ほどご説明しましたように、１,６００字から１,８００字にしようということでお願いしています。","voiceIndex":5,"id":"exchange-001"},{"speaker":"南委員","kind":"質問","question":"できたら、だれでも、どこで暮らしても地域というのは係わりを持たざるを得ないわけですから、子どもといえども地域に係わって暮らしているわけで、そういう点で地域活動課でセクションとして分担されてやっているということですけれども、子どもを育てるにあたって、地域というテーマで認識を持ってもらって、社会生活をしてもらうという点では大事ですから、やっぱり取り組み方は各学校に任せることは。","respondent":"高星委員長、久保田防災課長","answer":"ほかになければ、１の中学生の主張大会についてを終了いたします。２の平成１５年度「防災フェア」および「職員防災訓練」の実施について、理事者から説明をお願いいたします。そのほか、各小中学校、現在９校を考えておりますけれども、そちらのほうも活用する予定です。参加予定数につきましては、職員ほか２７０名です。","voiceIndex":7,"id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"それと二つ目は、防災フェアも１６日でこちらも１６日、１２時までは２時間程度バッティングするんですけれども、その辺はどういうふうに見ていったらいいのかというのを含めて教えていただきたいと思います。","respondent":"久保田防災課長","answer":"今回、初めて品川建設防災協議会の皆様の参加を得るわけですけれども、今考えているのは、震災になったときに道路上に倒壊家屋とかあるいはいろんな障害物が出てくるだろうということから、災害時協定でもお願いしているのが。","voiceIndex":12,"id":"exchange-003"},{"speaker":"南委員","kind":"確認","question":"１６日の防災フェアのほうはオープニングですよね。だけど、オープニングですから、当然区長やそれなりの役職の方が参加されるわけで、職員防災訓練のほうは最後までは参加されない体制でやるというわけですね、確認したいと思います。それから、初めての道路上の障害物除去のところは、例えばどういう場所で訓練するというふうに想定していらっしゃるんでしょうか、２点を伺いたいと思います。","respondent":"久保田防災課長","answer":"重機での訓練ですけれども、今考えているのは第２駐車場のところですけれども、あくまでも想定訓練ですので、駐車場に影響を与えないような形での態勢を取りながら、例えば想定される倒壊家屋の瓦れき等を片づけるという作業にしたいというふうに考えております。","voiceIndex":14,"id":"exchange-004"},{"speaker":"松澤委員","kind":"意見","question":"職員防災訓練、防災フェアの参加団体ですが、品川区防災協議会と品川建設防災協議会と紛らわしい名前なんですけれども、両方ともどういうような組織なのかお教え願いたいと思います。","respondent":"久保田防災課長","answer":"品川建設防災協議会につきましては、区内の建築および土木、電気機械の業者が集まって結成している民間団体でございまして、こちらと品川区は災害時協定を結んでおります。そういう関係です。","voiceIndex":16,"id":"exchange-005"},{"speaker":"松澤委員","kind":"質問・要望","question":"例えば、自分のところのダンプカー置き場が区外にあった場合、あるいは協定を結ぶからには常時そういうのを待機させておきたいと思ったら、どこかにブルドーザーを１台確保するとか、そういうような形での重機を置く場所を提供するとか、そういうような話あるいは要望等々は来ていないのかどうか。","respondent":"久保田防災課長","answer":"これから、そういう形のものも詰めていく必要があるだろうというふうに、私ども認識しております。","voiceIndex":20,"id":"exchange-006"},{"speaker":"松澤委員","kind":"質問","question":"随分時間がかかりましたけれども。当然、これは一つの大きな義務だというふうに思って、それはこの場所だろうというふうに思うんですけれども、今回、私たちの目に触れた形でその方たちが参加されるということですけれども、これ以外にどういうような形で災害対策職員待機寮の職員は防災に対しての仕事というか、意識とか啓蒙をしているのか、その辺をお伺いしたいと思います。","respondent":"久保田防災課長","answer":"待機寮職員につきましては、ほとんど毎月というぐらい、１カ月に１回は訓練をするようになってあります。","voiceIndex":22,"id":"exchange-007"},{"speaker":"松澤委員","kind":"質問","question":"いろんなところで私は会っているけれどもわからない職員もいますので、頑張っているんだなと思います。待機寮の職員で意識を持って参加しているというのは、今聞いてわかったんですけれども、待機寮職員はこうやって頑張っているんですよという形で何か広報するような形があれば、もっと区民の目に職員の活躍が触れるかなという気がするので、今後の広報面はいかがでしょうか。","respondent":"久保田防災課長","answer":"私どもも防災関係のものでＰＲする機会はいろいろあると思うので、今ご指摘の部分も含めて、今後やはり検討していきたいと考えています。","voiceIndex":24,"id":"exchange-008"},{"speaker":"嶋委員","kind":"質問・要望","question":"催し物の中の最後に感謝状贈呈式等とございましたが、感謝状の内容を教えていただきたいと思います。","respondent":"久保田防災課長","answer":"区内の地域では区民消火隊、ミニポンプ隊を組織していただいております。おおむね１０年以上従事していただいた方について、順次感謝状を贈呈するような仕組みになってあります。毎年、そういう形で贈呈式をやっているです。","voiceIndex":26,"id":"exchange-009"},{"speaker":"嶋委員","kind":"質問","question":"そういう意味では、この１０年以上順次という、恒例というか通例というだけではなく、１年を通して配慮していただいて、ああいう方たちにも本当に私が「お先に失礼します」と言ってくるのが恥ずかしいぐらい、高齢の女性の方たちが交通整理をしてずっと残っていらしたのを見ると、そういう方たちに感謝状を差し上げたいなという思いがありましたのでお聞きいたしましたので、何かございましたら。","respondent":"久保田防災課長","answer":"消防団につきましては別の制度で、表彰という形で規定を設けていまして、これもそれぞれの活躍度合いに応じて、消防署を通じて表彰するような仕組みになってあります。","voiceIndex":28,"id":"exchange-010"},{"speaker":"木下委員","kind":"意見","question":"大井北の出入口を取りやめというお話だったんですけれども、理由をお聞かせ願いたいのと、当初の予定が５,２００億円が４,２００億円、随分金額が変わるものだなと思いましたので、その辺の理由がございましたらお教えいただければと思います。","respondent":"金井環境課長","answer":"先ほども若干申し上げましたけれども、基本的には当初ここに出入口を予定していた、できるだけ地域の皆さんの便宜をよくするようなサービスでそうなったんだけれども、本当にそれがいいサービスなのかどうかも含め、さらにコストも含め検討した結果。","voiceIndex":38,"id":"exchange-011"},{"speaker":"木下委員","kind":"質問","question":"要するに、コスト削減ということで廃止して、そのため金額的にはそれだけ下がったという理解でよろしいでしょうか。","respondent":"金井環境課長","answer":"東京都に確認したわけではございませんが、そのとおりだというふうに、私どもも思っております。","voiceIndex":40,"id":"exchange-012"},{"speaker":"南委員","kind":"質問・要望","question":"建設委員会での報告というのは、今回はあるんでしょうか。環境部分はこちらですから、それでこちらには来ているんですけれども、経費の変更も含めて、建設委員会のほうはどういうふうになっているのか、わかるところがあれば教えていただきたいと思います。ですから、そういう心配があれば説明会に出ていただいて、いろいろと意見交換して意見を言うべきだというふうに思うんです。","respondent":"金井環境課長","answer":"頻度というのは、非常に建築関係の専門的な内容だと思うんですが、基準といいますか参考といいますか、頻度になっておりますが、１秒間に１０ｍの風が大きな建物を建てたときに、周辺ですとか、建物の形ですとか、位置ですとか。","voiceIndex":44,"id":"exchange-013"},{"speaker":"南委員","kind":"質問・要望","question":"それと、ちょっと教えていただきたいのは、１０番の景観のところなんですけれども、説明を聞いていて「眺望の変化の程度は小さいものと考えられる」と、それは「一体的な景観として認識されるため」ということで、一体的というのは道路ができたりあるいは換気塔ができる、そのものだけではなくて、まち全体の一体的なものをとらえて景観を評価して。","respondent":"金井環境課長","answer":"今、東京都が浮遊粒子状物質の規制をやっています。さらに国の方針で世界一厳しくしようということになっております。東京都から説明を受けたときに、そういった状況で平成２６年になれば、もっと下がるんじゃないですかという質問をしたんです。","voiceIndex":46,"id":"exchange-014"},{"speaker":"南委員","kind":"質問","question":"いろいろ説明していただいて、ありがとうございました。上空はいいけれども、地表面で大体１.５ｍぐらいのところで私たちは呼吸しているわけですから、なかなか上空と地表のところのあれというのは、結構大きな差があるんじゃないかなということで、説明をいただいたんですけれども、なかなか心配はぬぐい去れないというのが率直な感想だということを申し上げて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-015"},{"speaker":"藤原委員","kind":"質問","question":"評価結果ですけれども、評価をしたのはどこの関係でしょうか。","respondent":"金井環境課長","answer":"これは事業者であります首都高速道路公団です。","voiceIndex":49,"id":"exchange-016"},{"speaker":"藤原委員","kind":"質問","question":"五反田の換気所ですけれども、最初の計画は民間の土地を買って、そこに換気所をつくる予定だったのが、高速道路のところにつくるので用地買収等のお金がかからないのでコストダウンをしたのであるならば、最初の計画で高速道路内につくればいいと思うんですけれども、最初の計画は民間の用地を買収してでも換気所をつくろうとしたわけにも係わらず、コストダウンはすごくいいことなんですけれども。","respondent":"金井環境課長","answer":"多分、用地買収がうまく進まなかったんじゃないかなと思いますけれども、この間１年以上ありますので、住民の関係と用地の買収の関係に時間がかかったのかなと思いますけれども、多分そういうことが含まれているのではないかと思います。","voiceIndex":51,"id":"exchange-017"},{"speaker":"藤原委員","kind":"質問","question":"大気の件で、この数字を見てもぴんと来ないんですけれども、技術力の向上でトンネルの中から出てくる排気が外に出るときは、実際に山手通りとかの排気よりもきれいな大気が出てくるという認識があるんですけれども、それは間違いないでしょうか。","respondent":"金井環境課長","answer":"ここはどうかというと、まだわかりませんけれども、当然１０年後に向けて集塵機ですとか、一番効率のいいものを使って換気をしていくというのは、こちらの考え方です。","voiceIndex":53,"id":"exchange-018"},{"speaker":"松澤委員","kind":"意見","question":"中央環状品川線ができれば、当然のことながら環状六号線の交通量も減るし、首都高速の交通量も大幅に減るだろうと予想されますし、環境面の排ガスなんかの二面性があるのかなというふうに思っているんです。五反田に出入口があるということで、品川区民の利便性にとってもいいかなと。隣に東急池上線のガードがありますけれども、ちょっと高いですよね、幅と高さはどれぐらいのものかわかりますか。","respondent":"金井環境課長","answer":"用地買収のときには大体２,０００m2から２,５００m2の用地が必要だということでございましたので、それは作り方の形状にもよると思うんですが、路内ですので、前に当委員会で若干ご説明をさせていただきましたが、今、建設中の新宿線は路内なんですが。","voiceIndex":55,"id":"exchange-019"},{"speaker":"松澤委員","kind":"質問","question":"東京タワーの形だって、フランスのエッフェル塔の真似をしたんだとか、あるいはほかでそれより高いのをつくったときには、それぞれ特徴のある形にしていますので、ただ棒状の、これが一番風害に影響がないんですよ、環境にいいですよという形もあるかもしれないですけれども、それなりのモニュメント的なものができればいいなというふうに思いますけれども、その辺はこちらのほうから言えるんですか。","respondent":"金井環境課長","answer":"先ほども書いてありましたけれども、地域の景観等を考慮するということになっておりますので、その辺はまだまだ意見は言えると思いますので、これからまだちょっと長く続きますので機会があれば、そういうことも含めて意見を申し上げていきたいというふうに思っております。","voiceIndex":60,"id":"exchange-020"},{"speaker":"南委員","kind":"質問・要望","question":"換気塔のことが出ていたので、ちょっと改めて伺いたいんですけれども、５０ｍ級だということが今質疑の中ではっきりしましたけれども、それぐらいの塔を建てるにあたって必要とする最低の敷地はどのぐらいを想定しているのか、私の記憶では２,０００m2ぐらいという記憶があるんですけれども、２,０００m2となるとかなりの広さかと思うんです。","respondent":"金井環境課長","answer":"今、ご説明申し上げましたけれども、大体２,０００m2から２,５００m2というのを記憶しております。","voiceIndex":63,"id":"exchange-021"},{"speaker":"南委員","kind":"確認","question":"そういうものであるということを確認しておきたいなというふうに思ったので、あえて質問させていただいたんです。どのぐらいの大きさで、基礎がどういう形状になるのかという、具体的な図面が全然ないからあれですけれども、想定されるところで、想定の話だからどこまで言えるかどうかわかりませんけれども、新宿を例に取られて説明されたところで、もう１回その辺を確認しておきたいと思います。","respondent":"金井環境課長","answer":"基礎構造の形は、５０ｍになるかどうかわかりませんが、周辺の建物より高くするということは間違いないです。それから、敷地を確保するには２,０００m2ぐらいが必要だですが、形にもよりますが路内できちっとすれば、そんなに平米も要らないかもしれません。","voiceIndex":65,"id":"exchange-022"},{"speaker":"南委員","kind":"意見","question":"道路の真ん中というのは、五反田換気所のことを指すわけですね。大井北のところも路内だというから、南品川のところはどういうふうになるかなんですけれども、具体的な図面を見てからというと始まっちゃうから微妙だなと思うんですけれども、そういうことを危惧するということを強調して終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":67,"id":"exchange-023"},{"speaker":"松澤委員","kind":"質問","question":"先ほど訂正がありますよということで、評価書「案」が抜けているとか、評価書の完成がここに入りますよという指摘がありましたけれども、この文書そのものはここだけで使わなくて、またほかで使うわけですか、これを訂正したものを出すということでしょうか。","respondent":"金井環境課長","answer":"これは当委員会用に用意した資料ですので、ほかに出す予定はございません。","voiceIndex":71,"id":"exchange-024"},{"speaker":"南委員","kind":"質問","question":"カレンダーのどこかに出ているんだと思うんですけれども、各戸収集が始まっていますね。八潮団地の高層に住んでいる方の玄関前にも各戸収集の体制があると地域の方から聞いたんです。町場の方たちの対応だと思ったので、もしあればでいいんですけれども、その辺を整理して教えてもらいたいと思います。","respondent":"中山清掃リサイクル課長","answer":"このごみリサイクルカレンダーについては、まだあえて各戸収集のメッセージは入れてございません。ある程度、広がってまいりましたら、今後どういうふうに広報するか、また検討課題だと思います。","voiceIndex":89,"id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2378#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":32356,"voices":95}},{"id":"h15-20031126-7","meetingId":"h15-cm11","date":"2003年11月26日","dateIso":"2003-11-26","committee":"厚生委員会","time":"午前１０時０４分～午後０時０９分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成１５年請願第２３号、東京都食品安全基本条例（仮称）制定に区議会より要望を出すことに関する請願","agenda":"平成１５年請願第２３号、東京都食品安全基本条例（仮称）制定に区議会より要望を出すことに関する請願","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"請願趣旨のところにも、今回国の食品衛生法の一部改正で、保健所設置の自治体は監視指導計画をつくり云々と書いてあるんですけれども、この部分については品川区としては具体的にどうなっているのかについて教えていただきたいと思います。","respondent":"島袋品川区保健所衛生課長","answer":"これは今年の７月に食品衛生法が改正されまして、保健所設置区、都市ですけれども、食品安全監視指導計画をつくって、これを区民に公表して、その実施経過についても公表するというふうに、法律上で改めたところです。現在、我々のほうで保健センターと保健所の中で協議中です。","voiceIndex":6,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"請願項目の中で、３番目に、東京都の特性を踏まえた都独自のというふうなことで書いてあって、特に化学物質の影響が懸念される、子どもに対しての子ども基準の設置に配慮することというふうになっているんですけれども、いろいろ資料を見ていましたら、１９９７年５月にマイアミで８カ国の環境大臣会合というのがあって、子どもの影響は深刻で。","respondent":"島袋品川区保健所衛生課長、青山品川区保健所長","answer":"食品の基準、規格、制定などにつきましては、必要な措置を国のほうへ提案、要求するという文面が含まれておりますので、ご了解願いたいと思います。しかしながら、この点については文言としてアレルギー疾患に対してどうこうというところまで細かくは踏み込んではいませんけれども、総体の中でアレルギー、遺伝子組み換え食品等々を含めて、その安全性について調査をし、分析をし。","voiceIndex":8,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"子どもたちがこれから健康に大きくなっていくというふうなところでは、早急にここら辺のところは研究をして、しっかりと安全な食事、大気汚染とか、総合的なところでもやっていかなければいけないという部分もありますけれども、安全な食品というふうなところでは、検討をして、子どもたちにしっかりと安全な食品を食べさせていくというふうなところでやっていく必要があるんだなということを改めて思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":11,"id":"exchange-003"},{"speaker":"須藤委員","kind":"質問","question":"今東京都のほうの説明があったんですけれども、この請願項目で１、２、３、４、５、６というふうに書かれているわけですけれども、東京都のほうもかなり食に関しては真剣に取り組んでいるなというのが、この後の経過で見られるんですが、ここで書かれている請願項目で、東京都でいろいろ整理をしているところで、漏れているようなところがあるんでしょうか。","respondent":"島袋品川区保健所衛生課長","answer":"例えば遺伝子組み換えとか、子ども基準とか、そういう個々の名前はありませんけれども、基本的には都民の生命と健康を侵されない云々とか、国へ提案するとか、環境へ配慮するとか、都独自のとか、こういう文言は入っておりますので、基本的には。","voiceIndex":12,"id":"exchange-004"},{"speaker":"須藤委員","kind":"意見","question":"食については、今説明があったように、区民の関心も非常に高いことは当然ですけれども、同時に、国民全体としていろいろ考えてきているなというような感触があるわけで、今ここで請願が幾つか挙げられておりますけれども、もう少し広い範囲で東京都なり、国なりでいろいろ整理をしてきているんだろうというふうに思うんですが、今ご説明いただいたように、この請願自体については。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":14,"id":"exchange-005"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"基本法のところに加えてほしいなと思うのは、特に遺伝子組み換えの作物については、ここのところ心配なことがよく起こっていますし、このことに関しては、消費者がちゃんと選択できるような表示、どういう経過を経て、目の前に食品があるのかというのがきちんと分かるようにという意味では、遺伝子組み換えに関しては、ここにも２点目の項目に書かれていますけれども、選択権の確保、そして検査体制の強化。","respondent":"島袋品川区保健所衛生課長","answer":"先ほど副委員長のおっしゃいました、都民の意見表明ですけれども、これにつきましても、役割として、食品について、都の施策に協力するとともに、意見表明をやっていくというふうに明示されておりますので、それはクリアされていると思います。","voiceIndex":15,"id":"exchange-006"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"「権利」と入っているのは、凄く重いなと思うんですけれども、都民の健康を守ることを最も重要視するという意味では、この辺も強化をしていただきたいなという思いがあります。","respondent":"島袋品川区保健所衛生課長、青山品川区保健所長","answer":"食の権利の件ですけれども、先ほど副委員長がおっしゃいましたように、食の安全を確保することにより現在及び将来の都民の健康を守るということと、もう一つ、こういうことが書いてございまして、「食品の安全が確保されていることは。今回は条例制定ですので、あまり個々の細かい事柄についてまでは論及せず、大きな理念の部分、仕組みの部分で条例は制定されてまいりますので、ご理解いただきたいと思います。","voiceIndex":17,"id":"exchange-007"},{"speaker":"須藤委員","kind":"質問","question":"東京都がこういう条例をつくってきて、保健所単位で指導、計画等々というお話があるわけですけれども、品川区自体はこれに照らしてどういうふうに今後考えていらっしゃるのかなということも併せてお聞きいたします。","respondent":"青山品川区保健所長","answer":"食の安全の確保というのは、区民の生命を守る、健康を守る上で第一義的なものというふうに考えておりますので、その点で、現在の予定では、東京都が都議会の第１回定例会にこの条例提案をするということですので、具体的な条例案を見ながら、同時に。","voiceIndex":20,"id":"exchange-008"},{"speaker":"三上委員","kind":"質問・要望","question":"このメンバーの人たちというのは、行政の関係とか、政党の人とかという形だけで終わっているのか、それとも幅広い都民の中から、公募がされたのでしょうか、そういったような形ででも、民間の人たちが入った調査会であったのかどうかということと、人数的なことも含めて、お知らせいただきたいと思います。そこらあたりをどういうふうにお考えになっているかお伺いしておきたいと思います。","respondent":"島袋品川区保健所衛生課長","answer":"２番目にご質問のあった、答申のほうですけれども、２１日に出されたものを、取りまとめまして、特に留意点としましては、危険発生、未然防止の措置ということで、この辺のことを、安全性が確認できないとか。","voiceIndex":22,"id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ＥＵが０.９％までということに対して、日本は５％以下という状況になっていると思うんです。体をつくる、健康の元になるところですから、しっかりとやっていただきたいというのが今回の請願だと思うんですけれども、そういうところで後追いにならないためにもしっかりとやっていくことが必要ではないかなというふうに思っています。そこら辺の遺伝子組み換えのところで何かあったらお願いいたします。","respondent":"島袋品川区保健所衛生課長","answer":"後追い云々ですけれども、今回、資料にありますように、法では対処できないから、これは危険発生の恐れがあって、法で基準というのは規格が定められていないものがありますので、その場合には、食品評価委員会に諮りまして、都知事のほうで安全調査をして。","voiceIndex":24,"id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういうところに消費者の参加というか、消費者側からの意見の反映というのはどういう形で保障されるんでしょうか。","respondent":"島袋品川区保健所衛生課長","answer":"消費者の関係ですけれども、事業者、東京都、消費者、都民ということで、都民の意見を反映する。都民が食品について意見を言うということが役割として入っておりますので、そこで評価できるのではないかと思います。","voiceIndex":26,"id":"exchange-011"},{"speaker":"三上委員","kind":"質問","question":"ですから、食べることについての安全基準、それはあくまでもその人、その家庭にあってのお母さん、お父さん方がどういうふうに自分たちが食べていくかということについての情報提供ということがしっかりとなされていく体制はつくっていくべきではないかなと、こういうふうに思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-012"},{"speaker":"須藤委員","kind":"質問・要望","question":"私どもは、本日理事者から説明いただいたり、委員の方々からお話をいただいてきておりますので、結論を出していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"それと、先ほどから遺伝子組み換えのことについては論議になってきましたけれども、日本の場合は混入率が５％以下の物は表示がされないということになりますので、そういうところでは、この中でも検査体制を強化したり、環境に配慮した施策、それから国への提案というふうなことについても書かれておりますので、これをＥＵ並みに引き下げていくということについて。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":32,"id":"exchange-014"}]},{"id":"topic-02","title":"平成１５年請願第２４号、一人一人の子どもたちが大切にされる品川区を求める請願","agenda":"平成１５年請願第２４号、一人一人の子どもたちが大切にされる品川区を求める請願","exchanges":[{"speaker":"須藤委員","kind":"質問","question":"請願の内容ではなくて、委員長か、書記にちょっと伺いたいんですが、イラストが表と裏に入ってきているんだけれども、こういう請願というのは今まで扱ったことがあるのか。図をしたりというような場面で絵が入ったりというのは我々も見ているんだけれども、請願書にこういうイラストを使うということは、どういう考えで受けたのかなという思いがちょっとあるので、その辺を伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-015"},{"speaker":"須藤委員","kind":"意見","question":"入る前に議会はどう思っているのかなというような感じがちょっとしています。そのあたり、どこまでが許容されるのか、議長がどういう考えて受けたのか、そこを聞かせてください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":42,"id":"exchange-016"},{"speaker":"飯沼副委員長","kind":"意見","question":"私の記憶によると、このような形式で既に出されていて、今まで何ら問題がなかったので、これは別に問題ないと踏まえているんです。調べていただくのは結構ですが、今まで特に問題にされていなかったという点をお伝えしておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":44,"id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"保育園の子どもたちがほとんどそのまま学童保育クラブを利用するということになるわけですけれども、そこら辺のところで保育園の父母に対しての説明ということについては、今回はどのように考えられたんでしょうか。","respondent":"辻田児童課長","answer":"現在実施しております説明会等につきましても、保育園、幼稚園を通じてご案内を申し上げまして、今そういう方も参加しているという状況です。","voiceIndex":46,"id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これはあまりにも遅過ぎるのではないかと思うんです。いつも学童保育クラブの申し込みというのが１１月から始まると思うんですけれども、１０月上旬にということで、それ以前にこういうことが出されているわけですから、今後は保育園のように影響されるところについては同じような形で情報を入れていくというふうなことが一つ必要なのではないかということが１点です。","respondent":"辻田児童課長","answer":"基本的には私どもが政策形成して、そして区民の代表である議会の中でご報告申し上げる。そして、その後に保護者の方々等にご説明をしていくというルールがあると思います。私どものほうとしては、そういうルールに従って進めてきたです。","voiceIndex":48,"id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１１月から募集が始まるということですから、その間２カ月しかないわけです。準備をされているほうは、長い間準備をされているわけですから、突然というふうには思われないと思いますよ。２カ月というのはあまりにも短過ぎると思います。ということで、こんな大きな施策の転換のときには、次世代育成のこの趣旨に則ってぜひこれからもやっていただきたいというふうに思うんですけれども、いかがでしょうか。","respondent":"辻田児童課長","answer":"責任を持って、この事業を組み立てて実施していくですので、決して心配されるということはないと思います。今回、まだ３カ所ですけれども、説明会を開いた結果、皆さんはそれなりに理解をしているという具合に私どものほうは受けとっております。","voiceIndex":50,"id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"川崎市で品川区と同じような形で始まったわくわくプラザに関しても、３年間ぐらいかけて論議をしていると思います。そういうところでは、国のほうからもこういうふうな形で計画の策定段階からしっかりと利用者、区民、住民の意見を聞きながら、それを反映させながら、情報提供しながらやるようにというふうな方向が出されているわけですから、これを貫いていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-021"},{"speaker":"飯沼副委員長","kind":"質問","question":"そういった面では、まず親御さんの声を聞くところはもちろんですけれども、子どもたちのためにより良いものにするという、声を聞きながら、良いものに変えていくんだという努力に欠けていると思うんですけれども、その辺はいかがでしょうか。","respondent":"辻田児童課長","answer":"学童保育クラブに行けなくなるとおっしゃいましたけれども、少なくともすまいるスクールの中では放課後児童健全育成事業を継続して実施してまいります。","voiceIndex":54,"id":"exchange-022"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"「意欲」ではなくて、「努力」に欠けるのではないかと言ったんです。これは意見です。次に４番の保育園のところにいきますけれども、請願趣旨のところに、「子ども一人一人の発達を保障する保育がますますできにくい実態が現れています」という書き方をして、職員配置の改善を求めていますけれども、１点目は、現在の保育園での実態をどう捉えていらっしゃるのか、聞きたい。これは行政でとられた調査です。","respondent":"金子保育課長","answer":"平成１２年、平成１３年とやった園につきましては、２年連続ということで回収率はかなり落ちました。その反省に立ちまして、私どもとしましては、現在本格実施として３分の１の園で実施しております。","voiceIndex":56,"id":"exchange-023"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"一番最後のところに結果が出ているんですが、３７園で自由意見を書かれた方が２,０８６人いらっしゃったんです。その中で、項目はいろいろあるんですけれども、第１位が職員配置の問題で、２８６名の方が書いていらっしゃるんです。残りの２７８名の方が「悪い」と書いてある。特に行政について問われている部分なので、この辺をどう検討されたのか、ご答弁をいただきたいと思います。","respondent":"金子保育課長","answer":"これにつきましては、今申し上げたとおり、一つの園を例示として、具体的にはありませんけれども、どういう問題があって、どういうふうな改善策を実施していくのかということを、当委員会でお示ししたところです。","voiceIndex":58,"id":"exchange-024"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"最初のご説明のところに、「国基準の１.５倍の配置がある」、この言葉は耳にたこができるぐらい何回も伺っているわけですけれども、一つは、国基準に対する考えをお伺いしたいのと、国基準の１.５倍いるんだという説明の中には、職員は十分足りているという印象を受けるわけですけれども、どの時点で１.５倍いるのか。","respondent":"金子保育課長","answer":"私どもとしましては、入園弾力化等々さまざまなサービスもしておりますので、あるいは最低でも１１時間から１２時間の開所時間というような形で、各園には加算の配置をしておりますので、国基準をベースに。","voiceIndex":60,"id":"exchange-025"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"もうちょっと先にいきたいんですけれども、今回ここに配置を求められている１歳児、３歳児、２歳児、５歳児、４、５歳の１人担任を解消して、複数にしてほしい。実際このご要望に即した人員配置にすると、品川区はあと何人保育士を増やしたらいいかとか、その辺で試算をされたことがあるかどうか、そこをお聞きしたいと思います。","respondent":"金子保育課長","answer":"試算については、したことがありません。","voiceIndex":62,"id":"exchange-026"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"先日スウェーデンに視察にいっていらした方からスナップ写真を見せていただいたら、いろいろな形態が選べて、少人数の中で豊かな保育がされているというのを見て、この内容を改善していきたいなと思っているんですけれども、職員配置の、ここに書かれている、要望のところに対してのご意見をお聞かせいただきたいと思います。","respondent":"金子保育課長","answer":"繰り返しになってしまうかもしれませんけれども、先ほども申し上げたとおり、私どもは国基準、委員もご存じかと思いますが、１歳児、２歳児については６対１になっております。これに加えて加算の配置をしておりますので、運営上は十分な配置というふうに考えております。","voiceIndex":64,"id":"exchange-027"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"今回の請願は行政のところに求めている中身でもあるわけです。そういった面では、現状の認識がどうなっているのかというのをきちんとお伺いしないと判断ができないと思いますし、そういった面では必要な項目と考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-028"},{"speaker":"大西委員","kind":"質問・要望","question":"ずっと議論を聞いているわけですけれども、私は、先般原小学校で行われた説明会に行ったわけですけれども、これはきのうも申し上げたんですけれども、思いのほか出席されている方が少ないというところに、落胆と安堵を感じたんですね。一部過激なことを言われる方々がおられましたけれども、あとは、こういうふうであってほしいなという要望を出されていた。その点は真摯に受け止めるという発言もありました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-029"},{"speaker":"三上委員","kind":"質問","question":"１０年くらい前のときにどういう状態だったか。そのとき私が一般質問で聞いたときに、組合で時間内組合活動はどれぐらいとっているのか、年間２万４,０００時間とっている。果たして本当に、４番の「保育園の正規職員の配置基準を改善してください」、私は適正であるというふうに今思っているんですけれども、そこらあたりに対して理事者側としてはどういうふうに思っていらっしゃいますか。","respondent":"金子保育課長","answer":"現在の保育園の職員の配置基準ですけれども、先ほども申し上げたとおりですが、現在の充実した運営のためには適正な配置であるというふうに考えておりますし、今後もまたこれが固定した数字ではなくて。","voiceIndex":71,"id":"exchange-030"},{"speaker":"三上委員","kind":"質問・要望","question":"まさにそのとおりで、見直しというのは、その都度何かあった場合に見直しをしていくということは、これは当たり前のことであって、行革という言葉の中にあって、それは何かというと、小さなことであったって改善しなければならないことがあれば、それはするべきである。？職員の配置の改善を求めます」ということについては、これは当てはまらないと受け止めていいんでしょうか。","respondent":"金子保育課長","answer":"？で指摘されている部分については、「職員の手が行き届かなくなっています」というのは、実態に当たっていないというふうに考えております。","voiceIndex":73,"id":"exchange-031"},{"speaker":"三上委員","kind":"確認","question":"そこのところだけ確認して、私は終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-032"},{"speaker":"須藤委員","kind":"意見","question":"そのときに説明をということで、厚生委員会での皆さんからのお話があって、先ほど来説明があったように、区民の皆さんに教育委員会と福祉事業部児童課とで一緒に説明に入っていただいているというようなお話をきのう説明いただいたんですけれども、公正な審査をするについて、そのあたりについての状況をもう一度ご説明いただければと思うんです。","respondent":"辻田児童課長","answer":"３回の説明会を実施いたしまして、確かにかたくなに移行を反対される方は少しいらっしゃいます。ただ、全体の中ではこの事態を冷静に受け止めていただいているという状況です。","voiceIndex":76,"id":"exchange-033"},{"speaker":"須藤委員","kind":"質問・要望","question":"すまいるスクールとか、政策転換をする間に、区民の方々が今までと違った現状に入ってくるというのは戸惑いがあろうかと思うんです。ただ、行政でやっていることですから、税のあり方というものを大きく捉えながら、健全育成という立場でつくっていかなければいけないだろう、こんなふうにこの請願を見ながら考えました。論議はしているので、そろそろ決をとっていただきたいということをお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-034"},{"speaker":"飯沼副委員長","kind":"提案","question":"もう１点、１.５倍というのが私はどうしてもひっかかります。さっき提案をした、子どもと職員配置をきちんと出していただきたいのはお願いしておきますけれども、この間の品川区の職員を減らしながら事業の拡大をしているという意味では、１.５倍は当然必要な人員、もしかしたら、きちんと見たら、割っているのではないかなと思われるところもあります。元気な子どもたちが１週間に１回しか散歩に行けない。","respondent":"金子保育課長","answer":"そういう意味では、０歳、１歳、２歳、あるいは各年齢ごとの発達に応じて、それのふさわしい保育計画を設定しているわけですから、これを実践していく過程では、現場からこういった工夫を積み上げて、これからも充実した保育ができるように。","voiceIndex":79,"id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"６番の、子育て支援の一環としての乳幼児医療費助成の所得制限撤廃というところについてちょっとお聞きしたいんですが、４月から８５％から９０％に対象者を広げたということでご報告がありましたけれども、今まで品川区はこれは福祉の一環ということで利用されていたと思うんですけれども、そういう中で９０％に引き上げた理由はどのような理由で引き上げたのかを教えていただきたい。","respondent":"辻田児童課長","answer":"要するに、そこまでは私どものほうとしては福祉施策としての対応が必要であろうという具合に考えた。これは収入です。総所得金額で申しますと、２人ですと８２７万円とかありますけれども、収入でいきますと約１,０００万円というところで一つの区切りをしたです。","voiceIndex":81,"id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"少子化社会対策基本法というのができましたけれども、ここの中ではこういうふうに言っているんです。そういうところで、あくまでも福祉というふうなことで、ほかの自治体がこういうふうな形になっても、品川区としては最後まで福祉ということで、子育て支援の一環というふうなところでの、少子化社会対策基本法も出ているわけですけれども、こういう中でもそういう方向でいこうというところでしょうか。","respondent":"辻田児童課長","answer":"私どものほう、子育て支援を考える場合に、乳幼児医療費だけがその制度だと思っておりません。バランスの良い子育て支援をしていくためには、当然医療費の助成、それから保育園などで多様な形でのサービス提供、児童センター、学童保育クラブでもそうです。","voiceIndex":83,"id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"トータルでというところですが、予算も見ながらということですけれども、この場合、品川区としてはあと幾らあれば９０％を１００％にできるのでしょうか。その数字も教えてください。","respondent":"辻田児童課長","answer":"約５％を上げるごとに３,０００万円から３,５００万円ぐらいの経費がかかるのではないかと私どものほうは予想しております。ということは、今９０％ですから、平均して約６,８００万円ぐらいの持ち出しが区のほうとしてしなければならないということです。","voiceIndex":85,"id":"exchange-038"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この問題では、２３区のほかの区はすべてやっているわけですから、品川区だけになってしまったわけです。だから、ここのところでは唯一２３区のうち一つになってしまったというところで、ぜひやっていただきたい。そういうところからしても、２３区ただ一つ残ったというところを、いつまでも福祉施策ということでなく、子育て支援というふうな観点からなくしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-039"},{"speaker":"須藤委員","kind":"質問・要望","question":"いろいろ議論をされてきておりますので、採決をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-040"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"一人ひとりの子どもが大切にされる品川区を本当に多くの方が求めていると思います。子どもたちが健やかに成長する環境をつくっていくということは、保護者の皆さんと、地域と、行政が力を合わせてやっていくことで、これから改善する点が多々あると思います。今回の１万筆を超える区民の皆さんの願いをしっかりと受け止めて、私たちは採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3066#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":33785,"voices":99}},{"id":"h15-20031126-8","meetingId":"h15-cm11","date":"2003年11月26日","dateIso":"2003-11-26","committee":"建設委員会","time":"午前１０時０６分～午後３時００分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を14件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の都市高速道路中央環状品川線の都市計画案説明会の開催","agenda":"の都市高速道路中央環状品川線の都市計画案説明会の開催","exchanges":[{"speaker":"菊地委員","kind":"質問・要望","question":"この環状線の話が出て、品川区の中でも説明されてから１年ちょっとたつんですけど、北品川のマンションでしたか、地盤が緩くて地下を掘るのは危険じゃないかというような請願でしたか、陳情でしたか、出ていたかと思うんですけども、この辺のお話で、ルートの問題で、あれ以後、もし変化しているようなことがあれば、ルートですとか、その後の住民の皆さんとのお話があれば、ちょっと教えていただきたい。","respondent":"藤田都市計画課長","answer":"そうした技術が概ね実施していけるだろうというような方向づけまで出たというふうに聞いておりますので、当然のことながら、首都高速道路公団が入った実験をやっておるものですので。","voiceIndex":5,"id":"exchange-001"},{"speaker":"菊地委員","kind":"質問","question":"ちょっと調べますと、環状６号線なんかは１日で車の台数が５０万台を超えるという数字が出ていて、実際に高速道路を建設することで、特に品川区内に出入口、五反田につくることになりますけれども、当初から五反田周辺の皆さんで五反田ぜんそくとかと昔からいわれていて、逆に車を集中させることにつながるんじゃないかという心配事が出されていましたけれども、ちょっともう一点、言い忘れていたんですけど。","respondent":"藤田都市計画課長","answer":"今回の中央環状品川線の関係につきましては、先ほどもご案内のとおり、集中している交通を分散していくという観点から設置をするものですので、必ずしも集中して環境が悪化していくということではなく、分散することで環境については改善が図られていくということと。","voiceIndex":7,"id":"exchange-002"},{"speaker":"菊地委員","kind":"質問","question":"区としては子どもたち、大人も含めてぜんそく云々というところの心配事はあまり聞いていないということなんですか、今のお話というのは。東京都でこの問題としてとらえていることだけで、区としては聞いていないということなんでしょうか。そこをもう少し何かあれば。","respondent":"藤田都市計画課長","answer":"換気塔の件ですけれども、当初民地の中に建設をする予定であった換気塔でございまして、地元の皆様方の話の中で最終的に検討を進める中で、道路上の中に換気塔を設けることになったということで、その辺でも若干環境の改善は図れているかなということと。","voiceIndex":9,"id":"exchange-003"},{"speaker":"原委員","kind":"質問","question":"この品川線の内容については、前にもご報告をいろいろと私も聞いているところですけれども、この説明会なんですが、東京都が企画をして、区はどこまで係わってやれるのか、このお願いの部分にも、近所の方に来てくださいと書いてあるんだけど、東京都はどのぐらいの範囲で説明会のお知らせを配布して、住民といっても、どれぐらいの範囲の中で係わりがあるのかなと考えていらっしゃるのかお聞きしたい。","respondent":"藤田都市計画課長","answer":"１２月１日から３日までの間には、沿線の３０ｍの範囲と換気塔の半径５０ｍの範囲につきましては、各戸のポスト配布をする予定になってあります。１２月６日には東京都において新聞折り込みでまた再度お知らせをするという予定になっております。","voiceIndex":11,"id":"exchange-004"},{"speaker":"原委員","kind":"意見","question":"その３０ｍがいいのか、５０ｍがいいのかという判断の基準はどこから出ているのかよくわかりませんけれど、これだけの範囲でやっておけばまあいいやということだと、あまり説明する根拠はないのかなというふうに思うんですけど、例えばマンションだと何メートル以内とか、いろいろ決められた状況があると思うんですけど、こういった道路工事、ましてや地下を掘りますよという場合に、どういう考え方。","respondent":"藤田都市計画課長","answer":"委員おっしゃるとおり明確な基準というものはないというふうに聞いてありますけれども、今回中央環状線の場合は、今工事をやっております新宿線、それと既に交渉を終わっておりますけれども、王子線のほうとございまして、そういった中で説明会等を経験する中で。","voiceIndex":15,"id":"exchange-005"},{"speaker":"藤田委員","kind":"質問","question":"私もその地元説明会に行こうと思うんですが、目黒区のほうは夜７時から行われるのに、品川区は全部６時半からになっていますね。仕事をして、６時半までに学校に行くというのはね。目黒区はちゃんと７時になっていますけども、これは東京都のほうからそういう指定があったのか、品川区のほうで６時半にしてくださいと言ってなったのか、その経緯がもしわかればお伺いしたいというふうに思います。","respondent":"藤田都市計画課長","answer":"もう一点、換気塔の関係ですけれども、当然アセスメントの中で十分な検討をするようになろうかと思いますけれども、先ほど申し上げました最新技術の脱硝装置等の開発も進んでおります。","voiceIndex":17,"id":"exchange-006"},{"speaker":"藤田委員","kind":"質問","question":"それと、「広報しながわ」等に載せるというのは、この今我々がいただいたこれを載せていくということですか。ただ、どういう記事になっていくんでしょうか。やはり、その辺が一番、我々後から参加しなかった人とか、中途半端な広報をしたら、非常に苦情みたいな形で来るわけですから、丁寧な対応というものをお願いしたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-007"},{"speaker":"本多委員","kind":"質問","question":"大井ジャンクションの起点が決まりまして、京浜運河だとか目黒川の下の部分を走るという以前からの計画だと思うんですが、大体川の水面あたりから４０ｍぐらい下がったところで掘削が始まるというような感じだと思うんですが、構造とかはどんな調査をされたんですか。川の下とか調査というんでしょうか、構造的に大丈夫かどうかというような、そんなところを聞きたいんですが。","respondent":"藤田都市計画課長","answer":"そういった観点からいうと、構造的には十分大丈夫です。シールド工法でやろうということで考えておるものですので、工法的にも周りに影響が出ないような形で進んでいくものです。","voiceIndex":20,"id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"この中に詳細が載っているかどうかちょっと説明不足なのかわからないんですけど、避難、非常用の出入口というんですか、これは図面上には今明記されていないんですけど、あくまで出入口のみで、ほかは一切ないというような考え方なんですか。","respondent":"藤田都市計画課長","answer":"地上に抜けるのは、どうしても出入口と、あと換気塔のところもおそらく上にはあがれるのかなと、そういう構造だというふうに思います。","voiceIndex":22,"id":"exchange-009"},{"speaker":"須貝委員","kind":"質問・要望","question":"先ほどから質問があったんですけど、五反田の出入口ですか、ここはほんとうに環状６号線は混み方がちょっと通常じゃなく、一般の道路よりはかなり混んでいるように我々が通っていても見受けられるんですけども、ここの要望なんですけど、ほんとうに適切な、また車の出入りがほんとうにスムーズにいくような構造だけは、品川区として、またここが交通渋滞になると大変な場所になっちゃうので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-010"}]},{"id":"topic-02","title":"補助第２６号線と東京急行電鉄大井町線との立体交差事業に伴う工事説明会開催","agenda":"補助第２６号線と東京急行電鉄大井町線との立体交差事業に伴う工事説明会開催","exchanges":[{"speaker":"山村委員","kind":"質問","question":"補助第２６号線の大体の完成予定は何年ぐらいになるのかということと、さっき皆さん言われていたんですが、この案内が行かれている範囲は、町会に言うだけで、別にポストに入れるということはされているのか、そこら辺を教えてください。","respondent":"藤田都市計画課長","answer":"案内のほうですけれども、今回につきましては工事の説明ということで、全体事業の説明とはまた違うものですので、地域の町会を通じた回覧等の周知を図っていくということで確認しておるところです。","voiceIndex":29,"id":"exchange-011"},{"speaker":"藤田委員","kind":"質問","question":"今回こうした立体交差部に係わる用地の取得がほぼ完了したというふうに書いてありますが、ほぼというのは、まだ若干のあれはあるんでしょうか、すべて完了したというふうには書いていないんですけど、どういうふうに受け取ったらよろしいんでしょうか。","respondent":"藤田都市計画課長","answer":"今回の工事の部分につきましては整理はついておるところですけれども、２６号線全体の事業といたしまして、まだ買収が完了していないということで、読み取りにくい表現で大変申しわけないんですけれども、一応用地買収のほうは、全体といたしまして。","voiceIndex":31,"id":"exchange-012"},{"speaker":"藤田委員","kind":"質問","question":"はい、わかりました。それで、一つは難工事というふうに思うんですけれども、大井町の線路の、どれくらいの深さに道路が入っていくんでしょうか。そういうの、わかりますか。かなり深いんでしょうね。","respondent":"藤田都市計画課長","answer":"ちょっと今手元に資料がないんですけれども、そんなに深いところではないというふうに確認しています。","voiceIndex":33,"id":"exchange-013"},{"speaker":"藤田委員","kind":"質問・要望","question":"わかりました。いよいよということですが、やっぱり先ほど言いましたように、説明会につきましても、親切な、後で問題が起こらないような丁寧な説明会をぜひ行っていただきたい。要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-014"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3770#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":10352,"voices":42}},{"id":"h15-20031126-9","meetingId":"h15-cm11","date":"2003年11月26日","dateIso":"2003-11-26","committee":"文教委員会","time":"午前１０時０５分～午後０時１１分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を11件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"品川区立図書館の開館時間の延長","agenda":"品川区立図書館の開館時間の延長","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"先ほど２０名ぐらいが、きのう７時過ぎても残っていて、「時間ですからお帰りください」と言ったんですけれども、その人たちが、今度１時間延長できるという話だったんですが、全体として７時以降まで利用したいという人がどのぐらいいるものなのかということ。もしわかったら教えてほしいんですけれども。","respondent":"古里品川図書館長","answer":"何％ぐらいの人が７時以降ご利用なさるかということなんですが、アンケート等については、具体的な実施をしてございません。これは、昨年度来の懸案でございまして、それを今年度実施するというものです。","voiceIndex":6,"id":"exchange-001"},{"speaker":"沢田委員","kind":"質問","question":"そのときに、予算は限られているでしょうからあれでしょうけれども、全体として、この地区館はこういう技術系、ここは音楽系だとかというふうに分担をして、全体で必要なときにはいろいろなところの役に立つみたいな図書の収集というんでしょうか、そういうのがあってもいいのかなと、先ほどちょっと雑談程度で話したんですけれども、そこら辺について、ちょっと説明願えるとありがたいんですけれども。","respondent":"古里品川図書館長","answer":"今、委員ご指摘のような収集、それぞれの館の特徴については、今のところ特に定めてございませんけれども、区民のためにより幅の広い資料を集めるというのも図書館の役割ですので、そういう方向で、現在、工夫ができないか、館内で検討中です。","voiceIndex":8,"id":"exchange-002"},{"speaker":"山路委員","kind":"提案","question":"図書館の時間延長に関しましては、我が党の三上議員が、しつこく延長してほしいと数年前から言って、また中島議員も一般質問で提案しまして、やっと延長できるようになって、きょう視察をさせていただきまして非常に嬉しいんです。経費のところをひとつ聞かせていただきたい。機械がついていないところですね。それから、新着図書の選定というのは、どうやられているのか、聞かせていただけますか。","respondent":"古里品川図書館長","answer":"臨時職員を１３日配置をする予定です。隔日４時間ということで、４館にそれぞれ臨時職員を配置するという予定です。職員が１時間遅くシフトをしますので、午前中に行う仕事の分が、人手が足りなくなるということで、午前中に配置をするということにしています。","voiceIndex":10,"id":"exchange-003"},{"speaker":"山路委員","kind":"質問・要望","question":"１０時ごろまで延長という相談がかなり来ているんですね。もう１点、新刊の選定ですけれども、検索でその図書館にないものを、品川全体を調べて、そこにもまた欲しい図書がないとすると、私は、検索システムが国立図書館までつながっているんじゃないかと思っていたんですけれども、その辺のネットワークというのは、どの辺までどういうふうになっているのか、ちょっと説明していただけますでしょうか。","respondent":"古里品川図書館長","answer":"図書館のシステムにつきましては、国立図書館のインターネットが設置をされていますが、その中では、都立図書館の横断検索へそのままつながるようになっています。東京都、それから２３区の自治体全体に対して検索をすることが可能になってあります。","voiceIndex":12,"id":"exchange-004"},{"speaker":"山路委員","kind":"質問・要望","question":"そういう要望は、ちょっと聞いているんです。探してもなかなかネットワーク的に見つからないので、その辺まで、すぐ図書館で見つかるようにしていただければ、非常に助かるんだということがありますので、これは要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-005"},{"speaker":"西本委員","kind":"確認","question":"そこで、先ほど、利用率のお話をしていただいたんですが、利用がもっと増えてほしいというところがあります。今、どうなっているのなかというところ。子どもたちは活字を読まなくなっていますので、なるべく身近にあって、活字を読んでいく、そういう教育も、今後、進めていきたいというところなんですが、ここら辺の協力関係とか、今どうなっているんでしょうか。","respondent":"古里品川図書館長","answer":"学校のほうの読書の時間に、図書館の職員が出向いて読み聞かせをしたり、あるいは、ブックトークといって本の紹介をしたり、そういうこともしていますし、学校のほうの社会科見学のプログラムの中に、図書館訪問というのを入れてございまして。","voiceIndex":15,"id":"exchange-006"},{"speaker":"西本委員","kind":"質問","question":"もう一つ、その点でお聞きしたいんですけれども、かなり協力体制はできているということですが、協力体制をとるときに、学校、もしくは保育園でも、そっちのほうからの要請でしていくのか、それとも、図書館のほうから、こういうことができますよというふうに促しているのか。そこら辺はいかがなんでしょうか。","respondent":"古里品川図書館長","answer":"実のところ小学校だけで手いっぱいでございまして、保育園については、特段そうした働きかけをしてございませんけれども、従来から、同じ区の職員として連携していますので、その形で連携をさせていただいているです。","voiceIndex":17,"id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"ＰＲ方法として、なるべく図書館のほうから、こういうことができますとか、ＰＲをどんどんしていただきたいなと思います。子どもたちが、そこの図書館に行くということで、親の層、大人の層も広がっていく。それで、８時まで利用の時間が広がっていくとなると、利用者もどんどん増えていくという相乗効果もあると思いますので、ぜひとも積極的なＰＲ等々をお願いしたいなと思って、意見とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-008"},{"speaker":"伊藤委員","kind":"質問・要望","question":"例えば、二葉、源氏前、大崎、ゆたかのそれぞれの図書館については、今のところ、そういうことがないんですけれども、ここの図書館は８時までやっています、こっちは７時までですと、同じ区立の図書館でありながら、そういうことは多分あってはいけないと思いますので、二葉をはじめほかの図書館の開館時間の延長の計画についてはどうでしょうかということをお伺いしたいんです。","respondent":"古里品川図書館長","answer":"今回まだ８時までやらない図書館があります。委員、ご指摘のとおりです。今、館内で、この件について、鋭意検討しておるところでございまして、できるだけ早い機会に、全館で８時までの実施ができるように、内部の調整を図っているところです。","voiceIndex":20,"id":"exchange-009"},{"speaker":"伊藤委員","kind":"質問・要望","question":"職員のほうですけれども、来年度まではこの体制ということですので、来年度もそうだと思うんですが、ただ、臨時職員ですから、たしか１年ごとに区切りがあるんですね。そうなってくると、図書館自体は、これからずっと続いていくわけですから、業務財政改革をしながらですけれども、きちんとした体制をとっていく必要があると思いますので、そのことについては要望しておきます。","respondent":"古里品川図書館長","answer":"そういうものの中で、委員、ご指摘のような点についても、全体的に進めていきたいと考えていますので、よろしくお願いしたいと思います。","voiceIndex":22,"id":"exchange-010"},{"speaker":"伊藤委員","kind":"質問","question":"これは、多分検討中のこともあって、いろいろな問題もあるんでしょうから、それはそれで理解する部分もあるんです。ただ単に運営事項に入っていると、私は思っているんですね、開館時間、閉会時間。それが、職場のさまざまな事情があるとは思います、それは理解します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-011"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4490#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":9368,"voices":32}},{"id":"h15-20031126-5","meetingId":"h15-cm11","date":"2003年11月26日","dateIso":"2003-11-26","committee":"総務委員会","time":"午前１０時０５分～午前１１時５８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を55件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成１５年陳情第１２号、品川区在住の私立小中学校就学者への教育費助成実現に関する陳情（陳情項目一）","agenda":"平成１５年陳情第１２号、品川区在住の私立小中学校就学者への教育費助成実現に関する陳情（陳情項目一）","exchanges":[{"speaker":"宮崎委員","kind":"意見","question":"今、ここに書いてある四つの市のところで、町田市は、ないというふうにおっしゃいましたか。私がちょっと調べたら、町田のところの私立および外国人学校生徒のほうに、保護者に対して補助金交付要綱というのがあって、やはり年ですけれども５,０００円の補助が出ている、そういうふうになっていますけれども、そこのところは。","respondent":"宮地総務課長","answer":"それについては、ちょっと調べ漏れかもしれませんが、申しわけありません。町田はちょっとないかなと思ったんですけれども。では、５,０００円ということで。","voiceIndex":8,"id":"exchange-001"},{"speaker":"宮崎委員","kind":"意見","question":"それで、武蔵野のほうも私立の養護学校等があって、そういうところに通っている子どもたちの負担を軽減するためにやっているということで、私立学校にもいろいろあるなというのが、私は実感したところなんですけれども、先ほど私立の小学校大体５％が行っている、中学校ですと２５％ぐらいというふうなお話だったんですけれども、実際に、私立の、要はどういうところに行ってるのかという。","respondent":"宮地総務課長","answer":"私立学校に通わせているお子さんの場合は、区内外の分類ができませんので、一応どういうところにどれだけ行っているかというデータはちょっと今ないんですけれども、今委員の言われたように、外国人の学校に通われているお子さんですと。","voiceIndex":10,"id":"exchange-002"},{"speaker":"宮崎委員","kind":"質問","question":"区の予算のところでいきますと、いろいろどういうふうに考えたらいいのかわからないんですけれども、この主張でいいますと、この同じ義務教育の中で、私立を選んだために税金のほうからの教育費が受けられないんだというふうな気持ちがするのも一緒なんですけれども、実際には区の予算としては、大体１人当たり子どもたちの小学校、中学校、何に幾らずつ使うか、税金が行っている計算になるんでしょうか。","respondent":"市岡企画財政課長","answer":"率直に申し上げて、すぐにはちょっと数字が出ないのと、それからどこまでをいわば児童・生徒に還元されるというふうに考えるか、例えば教員の県費・給与等も私立では当然学費の中に還元されていますけれども、公立では区が負担しているわけでありませんので。","voiceIndex":12,"id":"exchange-003"},{"speaker":"宮崎委員","kind":"確認","question":"ちょっとこういうたぐいのは初めてなものですから、ちょっといろいろ私どもも、あるいはゼロからなので、いろいろ資料が出たら、ぜひお願いできればなと思います。それを今ちょっと、それは実際に１人当たり幾らだったかなというのをあわせてください。そこのちょっと関係を確認しておきたいんですけれども。","respondent":"宮地総務課長","answer":"ただ、平均で申し上げますと２万３,０００円の月額の保育料がかかりますので、そこら辺で言えば、半分から６割ぐらいはカバーできる、そういう状況です。","voiceIndex":14,"id":"exchange-004"},{"speaker":"宮崎委員","kind":"意見","question":"今の私立幼稚園の場合ですと、幼稚園と父母負担と両方ですね。もう一つ、私学、これもここで聞くのが適当かどうかわからないんですけれども、いわゆる私学助成、東京都の方とやっていますけれども、あれというのは、たしか学校の運営費として補助が出ているんだろうと思うんですけれども、そこというのをちょっと、どういう中身だったかというのは、そこではわかりますか。","respondent":"宮地総務課長","answer":"私学助成につきましては、直接学校に補助をしている助成ですが、通常法律でかかる経費を見まして、それを上回っている金額の２分の１を助成する、そういう仕組みになっているというふうに認識しております。","voiceIndex":16,"id":"exchange-005"},{"speaker":"宮崎委員","kind":"意見","question":"わかりました。そういう中で実際にほかの自治体でもやっていますし、また私立幼稚園では、そういう形で自己負担軽減というのをやっていますので、ぜひこれはそれで、こういう方向で検討できればなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":18,"id":"exchange-006"},{"speaker":"林（宏）委員","kind":"確認","question":"今の話、私立幼稚園の場合と、この義務教育をうたっているものを一緒に考えると、全く視点が違ってくると思う。それで、これは一つは、この陳情の肩書が代表となっているんだけれども、これは何の会、会なのか何かの団体の代表という意味でついているのか、それをちょっと確認できますか。この代表という肩書が、例えば私立学校のＰＴＡとかあるのかどうか、僕もわからないけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-007"},{"speaker":"林（宏）委員","kind":"意見","question":"個人的に出されているのと、何かそういう教育関係のグループというか団体の代表として出されているのかという、ちょっと陳情のニュアンスが違ってくると思うんですよね。わからなければしようがないということで。義務教育の政策を出している行政として、お子さんたちが区立へ行きたいんだけれども、入る余地がないという、そういうキャパシティの問題をまず聞かせてください。","respondent":"宮地総務課長","answer":"この問題につきましては、品川区の中で４０校、今小学校があります。","voiceIndex":21,"id":"exchange-008"},{"speaker":"林（宏）委員","kind":"質問","question":"いいですか。教育委員会の所管の部分に入っていっちゃうんですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-009"},{"speaker":"林（宏）委員","kind":"意見","question":"そういう意味で、選択する公立学校があるという考え方で僕はこの陳情を見させていただいているんですけれども、そのぐらいの行政、区立小中学校を施策としてやっている行政として、どうぞ私立を選ばないで公立の学校に来てください、大丈夫ですよという自負を教育長あたりにしてもらわないと困るんだけれども、全体を眺めるという意味では助役がいらっしゃるので、品川区の教育施策について。","respondent":"濱野助役","answer":"品川区としては、学校設置者という立場で区長がいるわけでありますけれども、その学校設置者としての立場から言っても、品川区の区民の子弟の方々が公立の小学校、中学校においでいただいて。","voiceIndex":29,"id":"exchange-010"},{"speaker":"本田委員","kind":"質問","question":"ちょっと理解するのでお聞きするんですが、この種の陳情・請願というのは過去になかったと思うんですけれども、２３区でこういう運動が起きているんですか。それからもう一つは、もちろん出してないわけですから、財調なんかでも関係ない話だろうと思いますが、需要算定なんかでは、こういうことが議論に上る課題、上った課題なんでしょうか。","respondent":"市岡企画財政課長","answer":"それから３点目に、義務教育の無償との関係ですけれども、これは先ほど来ご説明させていただいているとおり、憲法上は公教育として無償の義務教育が保障されているということが憲法上の必要な解釈でございまして、個人の選択の中で。","voiceIndex":31,"id":"exchange-011"},{"speaker":"本田委員","kind":"質問","question":"子どもの教育がどうあるべきかというのは大変な大きなテーマで、今、品川区は非常に改革的な取り組みをやっているというふうに聞いているわけですけれども、そういうことを含めてこの陳情では言わんとしているのかなとも思うんですけれども、そうすると、総務委員会でこれを議論するのはちょっと違うなと思いながら受けとめているんですが、不況が長引いて経済的な負担を担っているというのは理解できますし。","respondent":"市岡企画財政課長","answer":"いわゆる憲法で、公の支配に属さない団体への公費の支出ということが制限されておりますが、私学については、一定の教育水準を公的な目的のために維持する助成なので、この公金の支出の規制には当たらない、こういうふうになってあります。","voiceIndex":33,"id":"exchange-012"},{"speaker":"川西委員","kind":"質問・要望","question":"若干文教委員会に入っちゃうから、質問しにくかったんですけれども、義務教育の無償ということと、それから４行目の今も出ていましたけれども、税金の二重払いで、いわゆる学費を自己負担するという関係からしますと、先ほどどなたかから質問が出て、今日はご答弁できなかった状況なんですが、義務教育、小中における私学の施設助成ですよね。施設助成。私学の。委員長にお聞きしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-013"},{"speaker":"土井委員","kind":"質問","question":"それで、質問にならないんですけれども、要するに、そういう先ほどからご説明があったようなことの状況を踏まえると、じゃあ、どうしてもこっちへ行かなければいけないということになれば、極めて特殊な何か、要するに公立ではないけれども、極めて特殊な何かの部分がありますよ、養護学校みたいな話がちょっとありましたけれども、そういうようなものだという話になってくると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-014"},{"speaker":"築舘委員","kind":"質問","question":"要するにさっき川西委員もちらっと言ったけれども、私立の小中学校に対する個人的なものは出ていないけれども、そういう品川区内にあるということで、補助というんじゃないけれども、そういう施設とか、そういうあらゆる何らかの形でプラスになっていることというのがあると思うんですけれども、その点はどうでしょうか。","respondent":"宮地総務課長","answer":"それが公立の小中学校を経営する、かかる経費になりますが、それを上回る経費の２分の１を目安にということで支出をしているところで、都のデータで申し上げますと、東京都は全国の中でも上位３位以内に入るぐらいの高い助成金を出しているというふうにうかがってあります。","voiceIndex":38,"id":"exchange-015"},{"speaker":"築舘委員","kind":"質問","question":"ですから、区立小中学校というのは義務教育でもありますから、それに対する無償というか、そういう意味での、品川区の場合は学校選択の自由もあるし、それで私立に行きたいということは、やはりそれなりのさっき林（宏）委員も言ったように、特色のある、スポーツにしても、また何か、そういうどうしても私立に行くことによって、自分で負担をしても、それは行きたい、こういう状況だからこそ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-016"},{"speaker":"武内委員","kind":"質問","question":"主に多摩地域のところで助成を行っているということなんですけれども、単純に考えて、そちらのほうに、私学に通っているお子さんが、割合として２３区より多いということなんでしょうか。","respondent":"宮地総務課長","answer":"そもそも生徒数に対してキャパシティが、公立として用意できない、その部分をやむを得ずという選択もあったと思うんですが、そういう場合に出しているという形があります。","voiceIndex":41,"id":"exchange-017"},{"speaker":"武内委員","kind":"質問","question":"先ほど品川区においては、キャパシティの問題もないということで、また不登校、いじめ等に対しての学校選択とかいろいろな問題とか対応を十分できるということもお聞きしましたし、またこの陳情書の一番最後のほうにある、不況が長引く中で学校をやめなければならない子どももいますという、確かにそういう方もいると思うんですけれども、実際に今よそで行われている助成の額を見ますと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-018"},{"speaker":"宮崎委員","kind":"確認","question":"いろいろ義務教育として無償の教育を用意していますよ。ちょっと私も教育のほうはあまりよくわからないので、発言してはいるんですけれども。それで、現実にやっぱり私学への助成というのはいわゆる経営のほうに助成ということなんですけれども、目的は、父母負担の目的じゃなかったかなと思うんですけれども、そこのところというのはどうだったんでしょうか、ちょっと確認しておきたいんですけれども。","respondent":"宮地総務課長","answer":"私学そのものの経営の健全化だとか、それから全体としては児童・生徒の負担軽減につながると思いますが、その施設経営に対する国・都からの私学助成という、そういう形でバックアップしているということで、これは保護者補助金のように、幼稚園のような形では。","voiceIndex":44,"id":"exchange-019"},{"speaker":"宮崎委員","kind":"質問","question":"わかりました。だから、やっぱり当然私立、僕らの側では公立にぜひ来てくださいというのはありますけれども、それは私立も含めて選べるという状況にあるわけですから、それは当然負担の問題というのは壁になっていくということは、やっぱりそういう障害はなくしていくということが必要じゃないかと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-020"},{"speaker":"川西委員","kind":"質問","question":"今もあるんですか。よく知らない。あれはキャパシティの問題もありましたけれども、専門教育選択、あれは都立高校が飽和状態の時期に始まったと記憶しているんですけれども、その辺で、あれはどういう根拠で創設されたのか、おわかりになったら教えてください。あれはご存じですか。義務教育か義務教育でないかということの判断はよくわかった上で、ごく参考に伺っておきたいということです。","respondent":"宮地総務課長","answer":"今のところは、ちょっとこの調べた中ではございませんが、もしそういうことがあるとすれば、やはり高校のキャパシティの問題で、それはどうしても公立に対する人口増とかその他でもっていかざるを得ない。","voiceIndex":47,"id":"exchange-021"},{"speaker":"土井委員","kind":"意見","question":"先ほどからいろいろお話がありましたけれども、我が品川区においても、それぞれの学校が特色ある教育という形で、それぞれがいろんな意味でのそれぞれの学校における付加価値と言うのも適切であるかどうかわからないけれども、特色を出してやっているわけですね。私学のほうもそれだけおやりになっている。さまざまな付加価値のある、その付加価値の選択の話だと思うんですよ。私学を選ばれたのは。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":50,"id":"exchange-022"},{"speaker":"中島委員","kind":"質問","question":"ここで質問が適当なのかどうかわからないんですけれども、ここで税金の二重払いというところがあるので、これは国制度で教科書は無償配付になっていますよね。義務教育の。それは当然税金で賄われているものだと思うんですが、私学の方の教科書代というのはどういうふうになっているのか、ここでわかりますか。","respondent":"宮地総務課長","answer":"私学につきましても、教科書代は無料で配付することになっております。","voiceIndex":51,"id":"exchange-023"},{"speaker":"中島委員","kind":"質問","question":"そうすると、そこではやはり税金が私学にも使われているという判断になるわけですか。わかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-024"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"そんな中で、子どもだけはどうしても学校に行かせたい、続けたいという。高校に行くと奨学金というのがあって、それを利用して、自分がそのお子さんが稼げるようになったときに返済するという仕組みの中で続けられるんだけれども、中学生の場合だと奨学金制度がないので、それを何とか国のほうで創設というか、範囲を広げてほしいということで要望が来て、ちょっと動いて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-025"},{"speaker":"林（宏）委員","kind":"質問","question":"今日やるかやらないかですか。それとも、両方一緒に言っていくんですか。今日の取り扱いについて先にやりますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-026"},{"speaker":"林（宏）委員","kind":"意見","question":"それで、義務教育としては、公立中学校できちんとやっていくということなので、私学へ行っていらっしゃる方への行政補助というのは、私たちは願意に沿いがたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":67,"id":"exchange-027"},{"speaker":"武内委員","kind":"意見","question":"先ほど述べたとおり、実際にここで取り上げられている不登校、いじめ、シックスクール、アレルギー等の問題が、現在品川区の中でクリアできるものという認識に立っていますので、ここでは個々のあれに難しい場合があるかもしれないけれども、そういうような認識になっておりますので、不採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":68,"id":"exchange-028"},{"speaker":"宮崎委員","kind":"意見","question":"私は、この陳情を賛成です。まだ私自身もよくこなれていないところも正直言ってありますけれども、一つは、公立私立ともやっぱり公教育を公立私立で構成しているというふうに私は思います。賛成です。採択。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":69,"id":"exchange-029"},{"speaker":"土井委員","kind":"意見","question":"先ほど言いましたように、義務教育という形の中では、先ほど言った我々の品川区の教育については、少なくとも付加価値というべきか、特色ある学校という意味も含めていろいろな選択肢を用意をされているということから、この問題につきましては、ちょっと願意に沿いがたいなという思いであります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":70,"id":"exchange-030"},{"speaker":"本田委員","kind":"意見","question":"税金の二重払いということについても、もっと広く見ていった場合、必ずしもそうではないなというふうに理解をしているわけです。それで、この陳情については願意に沿いがたいなというのが率直なところです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":71,"id":"exchange-031"},{"speaker":"川西委員","kind":"質問","question":"去年、海外に行かさせていただいて、ちょうど教育問題を取り上げてきました。それで、現在の制度の中で保護者負担軽減が、助成はないけれども、施設助成、それから運営費助成という形で出されていますし、先ほどの答弁の中で教科書も配付されているということなので、現況の中で私立公立を選んでいただくということですから、この請願については願意に沿いがたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-032"}]},{"id":"topic-02","title":"仮称西五反田三丁目区民住宅超高層棟新築外構工事","agenda":"仮称西五反田三丁目区民住宅超高層棟新築外構工事","exchanges":[{"speaker":"林（宏）委員","kind":"質問","question":"このＳＵＳグレーチングというのは、どういうことなんだろう。単純に教えていただけますか。","respondent":"宍戸施設担当課長","answer":"この外構図がちょっと道路との関係がわかりにくくなっているんですけれども、道路沿いの部分でございまして、ステンレス製のグレーチングというふうになってあります。","voiceIndex":78,"id":"exchange-033"},{"speaker":"林（宏）委員","kind":"質問","question":"ＳＵＳというのは、ステンレスという意味ですか。用語の説明だけ教えていただければ。","respondent":"宍戸施設担当課長","answer":"調べさせてください、申しわけございません。","voiceIndex":80,"id":"exchange-034"},{"speaker":"林（宏）委員","kind":"質問","question":"あっちこっちに出てくる。これは何ですかと聞いている。ＳＵＳグレーチングって何ですかと聞いているんです。","respondent":"宍戸施設担当課長","answer":"排水構の部分のグレーチング。","voiceIndex":82,"id":"exchange-035"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"建設委員会じゃないけれども、お金の審査をするんですから、ここが何ですかと聞かれたら、きちんと答えられるような態度で臨んでいただきたい。何のために報告をされているのかわからないようじゃ困る。目を皿のようにして見ていたけれどもなかったということですから、その辺はこれからもお願いしておきます。","respondent":"西島経理課長","answer":"植栽工事につきましては１１月２０日に入札を行いまして、３,１００万余で契約をもう既に結んです。","voiceIndex":86,"id":"exchange-036"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"だけれども、この空地の外構工事なんだけれども、公園というところについては区民のものという考え方を持つべきだろうと僕は思うんですね。一般の人が自由に入れるというような意識でつくっていただきたいし、近隣の人、あるいは通りかかった人なんかが休めたり、そういう意識を持ってやるべきだと思うんですけれども、その辺についてのお考えはいかがでしょうか。","respondent":"宍戸施設担当課長","answer":"この超高層棟につきましては、特に総合設計制度というものを使ってあります。総合設計制度上の公開空地という位置づけですので、公園と同等の、区民の方が自由に出入りできるような構造ということで設計しております。","voiceIndex":88,"id":"exchange-037"},{"speaker":"林（宏）委員","kind":"質問","question":"そういうことをお考えになっている。今度は裏腹に、逆に、公園という位置づけになると、容積率とかいう裏腹の話で、公園ということになると公開空地で、じゃあ容積率にはどういう算定というか、数字を、もうこれは最初の容積率のときは一般の敷地として計算するんだよという、そういう考え方でいいですか。","respondent":"宍戸施設担当課長","answer":"敷地としては算入していますので、都市計画的な観点から、空地を都市の中に広げようというふうな都市計画的な観点から、むしろ容積率についてはアップします。空地をとることによってアップしますというふうなことです。","voiceIndex":90,"id":"exchange-038"},{"speaker":"林（宏）委員","kind":"意見","question":"最後に、この随意契約なんですけれども、ただ単に随意契約１億幾らという説明ではなくて、ほかと比較したり、そういう金額的なものとして妥当という主張を僕は行政はするべきだと思う。その辺を説明してほしい。","respondent":"西島経理課長","answer":"それから３点目ですけれども、経費の点でも、新しい業者が入りますと、当然仮設事務所等の問題が出てまいりますので、金額にしますと、おおよそですけれども、７００万円ほど新しくやるよりは安く発注ができるであろうというふうに考えている点から、随意契約にしたものです。","voiceIndex":92,"id":"exchange-039"},{"speaker":"宮崎委員","kind":"質問","question":"建設委員会で聞くべきなのか質問しようかちょっと迷っているんですけれども、最近、雨が集中豪雨みたいに降ってきているんですけれども、各こういうビルの場合は、それぞれの建物のところで雨水を処理するというふうになっているんですが、ここの場合はどういうふうな対応がされているのかというのはわかりますか。","respondent":"宍戸施設担当課長","answer":"インターロッキング等、透水性のものを使ってありますし、雨水貯留槽も設けてあります。","voiceIndex":94,"id":"exchange-040"},{"speaker":"宮崎委員","kind":"質問","question":"雨水貯留槽が、中にあるんでしたっけ。この防火貯水槽とはまた違うやつがあるんですか。","respondent":"宍戸施設担当課長","answer":"雨水貯留槽が別途ございまして、時間差でポンプで排出するようになってあります。","voiceIndex":96,"id":"exchange-041"},{"speaker":"川西委員","kind":"質問","question":"今、出てきましたインターロッキング等の、これは廃棄物再生品ですよね。原材料。これの仕様の規定というのは、こちら発注時にきちっとこの面積を使いなさいというのがなされているのかどうか。それと、廃棄物再生機材の使用量について、発注元というのはいかように指示なされるのかどうか。もう一つは植栽のことですけれども、高木か低木かというレイアウトというのは、どこがなされるのでしょうか。","respondent":"宍戸施設担当課長","answer":"高木や何かのレイアウトですけれども、一応設計を委託していますので、その設計事務所のほうで基本的には出してきますけれども、区として内容を精査して施行している、それによって、配置や何かについて。","voiceIndex":98,"id":"exchange-042"},{"speaker":"川西委員","kind":"質問","question":"そうしますと、その植栽のほうから言いますと、道路公園課のほうで、例えば常緑とか落葉樹とかいろいろ種類を分けて、景観上とか人の目に触れてどうなのかという配慮をなさっているかどうかが一つですね。その努力というのは、どうしてこんなに大事なお金のかかるところで使われなかったのか。今回だめだった。発注しちゃったんですから。今後の考え方を。","respondent":"宍戸施設担当課長、西島経理課長","answer":"こういうふうな配置で、あるいはこういうふうな地所について植栽をしたいというふうなことで協議をし、その中でアドバイスというのをいただいた形で設計を進めるというふうな形になっております。例えば紙なんかも、新しいパルプを使うのではなくて、再生品を使うということで指定していますので、できるものについては、今後もそういう方向では考えていきたいというふうには考えてあります。","voiceIndex":100,"id":"exchange-043"},{"speaker":"川西委員","kind":"質問・要望","question":"経理課長が答弁なさっていたら、意見を言いたくなりました。循環型社会に、区の方針の中で一番最初のほうにうたっていらっしゃるんですよね。だから、値段の問題は業者との関係ですとか、製造過程の努力で改正というのを求めるのが普通でありまして、やはりもっと循環型社会という、あの言葉に沿うような施策をよろしく。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":103,"id":"exchange-044"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ほかによろしいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":104,"id":"exchange-045"},{"speaker":"林（宏）委員","kind":"意見","question":"それについて、品川区としての負担あるいは補助というのをしなきゃいけないのか、しないでケーブルテレビ会社独自でやるのかどうかということと、一般的に普通のアンテナ、普通のアンテナというか、ケーブルでない場合は見られるように、今言ったテレビを買いかえるというのは別として、今あるテレビでデジタル放送を受信するのは一切お金がかかりませんよという宣伝をしているんだけれども。","respondent":"山田広報広聴課長","answer":"１点目のケーブルテレビの設備の投資になるわけですけれども、これに関しては、現在ケーブルテレビの中の予算を執行してやっていくという予定でおります。区が改めてこれについて個別の支援をするというふうには考えてはございません。","voiceIndex":113,"id":"exchange-046"},{"speaker":"宮崎委員","kind":"意見","question":"現在加入している方には、このセット・トップ・ボックスを取り付けることで見れますよということなんですけれども、ビルの電波障害等、住民が望まなくて、そういうケーブルテレビになっている、そういうところもあるんですが、今のお話ですと、そういうところへの対応というのはどういうふうになるのかなというのはちょっと疑問なんですけれども。","respondent":"山田広報広聴課長","answer":"ただ、今のテレビをそのままにしておかれると、２０１１年以降は見れないというのは、これは一般の方とご一緒になりますです。","voiceIndex":115,"id":"exchange-047"},{"speaker":"宮崎委員","kind":"質問","question":"ここでわかるかどうかなんですが、セット・トップ・ボックスというのは、例えばマンション１棟で１個でいいとか、何かそういうものなんですか。１個１個ちゃんとそろえるのか。","respondent":"山田広報広聴課長","answer":"それと、個々のお家については、今言いましたように、このセット・トップ・ボックスを入れていただくか、内蔵型のテレビに入れていただくというような形で全体に改善をしなければ、やはり見れないという状況だです。","voiceIndex":117,"id":"exchange-048"},{"speaker":"宮崎委員","kind":"質問","question":"そうしますと、例えば集合住宅等は、いろいろマンションでも対応しなきゃいけないことだというふうに思います。個人個人の部分での対応、二つ出てくると思うんですよね。ですから、ちょっとここのところはぜひそういうことで、対応をお願いしたいと思うんですけれども。","respondent":"山田広報広聴課長","answer":"２０１１年までですので、期間はありますけれども、いわゆるケーブルテレビのほうが、もう少し方針が明らかになってきたときに、今いろいろなケーブルテレビの中で検討していることと、結論と、それから地上デジタル放送に関して、これは総務省のほうが管轄なんですけれども。","voiceIndex":119,"id":"exchange-049"},{"speaker":"林（宏）委員","kind":"質問","question":"そこまではわかる。それで、この指定管理者という名称を使うのは、何か意味があるんですか。ただ固有名詞というか、指定管理者という名称にしとこうよということなんですか。","respondent":"榎本行財政改革担当課長","answer":"これは、地方自治法上の言葉ということで、法上は実際には法人その他団体であって、普通地方公共団体が指定するものというものを指定管理者というふうに呼んで、法律の言葉として定めたという形です。","voiceIndex":125,"id":"exchange-050"},{"speaker":"林（宏）委員","kind":"質問","question":"裏面のほうの指定の手続の順序が、まず個別の施設を限定して、１番の条例の制定が必要ですよと。２番で条例に従ってつけるというんだけれども、この指定管理者に指定されて、この施設のあれは、指定管理者にやってもらうよというふうになったときに、その指定管理者というのは、守備範囲というか、どこまで権利というか、責任というか、何がどこまでできるんですかという、意味が伝わりますかね。","respondent":"榎本行財政改革担当課長","answer":"その辺が条例の制定事項の中に明記していくという形になるんですけれども、業務の具体的な範囲、要は設備の維持管理をするのか、それとも使用許可まできちんとやるのかということは、条例の中に明記しまして、さらにもっと細かい具体的なものについては、その指定が終わった後。","voiceIndex":127,"id":"exchange-051"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、何と言ったらいいのかな、その指定管理者は、条例制定を待ちながら、区と契約をしていくということになるんだろうけれども、かなり縛られた範囲で指定管理者とされる場合と、ものすごく広げられた中で自由に羽ばたける指定管理者と、その都度変わるという理解をしておいていいんですか。","respondent":"榎本行財政改革担当課長","answer":"実際に指定管理者となるべき、候補となるべき業者がどこまでできるのかというのも、その業者のほうの範囲もありますので、その中で、実際上どこまでできるかをきちんと明記をした上で、最終的に条例として任せられるかどうかというものを提案した上で。","voiceIndex":129,"id":"exchange-052"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、随意契約の上に行政側の口出しの多いということになると、いわゆる幅広く規制緩和の中で広がっていったとは言いながら、区の権限が非常に、品川区の悪口を言うわけではなくて、行政体、指定する側の行政の力が非常に強くなって、民間を圧迫というか、苦しめるというような事態が起きるような、この制度で感じがするんですけれども、それはないんですか。","respondent":"市岡企画財政課長","answer":"何といっても、それらを含めて、指定管理者の指定をすることについては、条例そのものも、もちろん議会の議決をいただくわけですが、指定管理者の指定ということを議決事項としておりますので、議会のチェックも入りますし、執行機関としても自信を持って、よい施設、効率のいい。","voiceIndex":131,"id":"exchange-053"},{"speaker":"林（宏）委員","kind":"質問","question":"ごめんなさい、一言だけ、最後と言っておいて悪いんだけれども、これから先なんだけれども、今はもういろいろな形で委託管理業務、運営も含めた委託をしているわけですけれども、これから先は、この方式に全部を切りかえていくというお考えなんですか。","respondent":"市岡企画財政課長","answer":"何と言っても、この制度ができたばかりで、今回二つ条例のご提案をさせていただいていますが、これが一般論としていい、つまり、目的を十分発揮できるような制度になるかどうかは、やはり具体的な内容を一つずつ詰める中で判断していくべきだろうと考えています。","voiceIndex":133,"id":"exchange-054"},{"speaker":"土井委員","kind":"意見","question":"役所がつくる。そうすると、民間の活力がどこに入るのという問題が出てくる。だけれども、条例に縛られるからだめですよなんていう話になりかねないという問題等があるので、そこら辺はちょっと、もっと民間のほんとうの意味での活力を使っていけるように、柔軟にやっていかなきゃならん部分があるんじゃないかなというのを意見として述べておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":135,"id":"exchange-055"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1634#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":32617,"voices":137}},{"id":"h15-20031127-12","meetingId":"h15-cm11","date":"2003年11月27日","dateIso":"2003-11-27","committee":"清掃制度特別委員会","time":"午前１０時０４分～午前１１時５０分","status":"正式会議録","sourceType":"formal","overview":"清掃制度特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査、東京二十三区清掃一部事務組合に関すること","agenda":"特定事件調査、東京二十三区清掃一部事務組合に関すること","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"質問させていただきたいんですけれども、４ページのところで、「清掃一部事務組合の抜本的改革は次のような方向から検討を進めるべきである」というのがあるんですけれども、その中で、こういった抜本的な改革を進める上でどういうスケジュールでこれを検討していくのかということと、もう一つ、４番目に書かれている「徹底した情報公開の推進」というのは何を意味しているのかお伺いしたいと思います。","respondent":"高橋区長","answer":"これからスケジュールの検討に入っていくということです。この問題とあわせまして人事の問題があります。これから区長会でスケジュールを考えていきたいと思っています。「徹底した情報公開の推進」という問題ですが、今までとかく東京二十三区清掃一部事務組合でございました。","voiceIndex":5,"id":"exchange-001"},{"speaker":"井上委員","kind":"質問・要望","question":"私たちも廃棄物会計調査ということで、各自治体が協力をしまして、資源回収にどういった税金が投入されているかということを知ろうということで運動が進んでいるんですが、そういう中で、やはり東京二十三区清掃一部事務組合でまとめられているので、品川区のどういった計算になるのかわからないというような東京二十三区清掃一部事務組合のほうでの回答だったんですけれども。","respondent":"高橋区長、山路委員長、築舘議長","answer":"というのは、今までは、とかく２３区全体でやっておりました。品川区の分は何も出てない。きょうは議長も出席されておりますので、議長会の流れもあるので、議長のほうから説明をお願いします。それは区長会の総会の報告ということで議長会に出されたわけですが、品川区もそうですが、渋谷区、中央区、また江東区などからの議長から質問がありまして。","voiceIndex":7,"id":"exchange-002"},{"speaker":"石田委員","kind":"質問・要望","question":"これはずっと規約もありますでしょうし、規約改正の部分が出てくる、それから覚書の整理が出てくる、さまざまいろいろなものが出てくると思いますが、どこの段階で、最終議決機関はどこなのか、もう１回改めて、これは区長会、協議会、メンバーの評価というのはもちろんわかっていますが、そこら辺のところ、議会も含めてどういうところが原案があって、最終的にはどこがこういう形で決定をしていくか。","respondent":"松本環境清掃事業部長、高橋区長","answer":"その下に部長会、課長会、それぞれ構成をされておりまして、今回、実務的な意味での検討を下命されたのは、そういう意味では……。東京二十三区清掃一部事務組合は２３区で構成をされております。構成されまして、その中で組合議会がございまして、これは２３区の議長が今議員になっておりまして、議決機関。","voiceIndex":12,"id":"exchange-003"},{"speaker":"石田委員","kind":"質問","question":"そこで議会の議長も含まれているんですが、規約がもちろんありまして、規約改正等、議会があるわけですから、議長会も議会の委員であると考えていますが、そこら辺の権限がどこにあって、最終的には区長会なのか、どこなのか、議会なのかというのをもう１回改めてわかるように説明してください。","respondent":"高橋区長","answer":"おわかりですか。東京二十三区清掃一部事務組合の規約の変更、またはこれを廃止する問題等につきましては、それぞれの区の議会の議決を得て決まっていくわけです。承認をいただいて、変更なり規約の削除が行われるわけです。","voiceIndex":15,"id":"exchange-004"},{"speaker":"石田委員","kind":"質問","question":"そうすると、これは議会の議長の部分があるわけですから、議決機関、我々の議長がいらっしゃって、それを受けて、その話を持っていくということになると思うんですね。その部分の中で、最終的には、区長がお出しになったものを議会がどういう判断をするかというのは、そこの判断があって、それを持ち寄るという考え方でいいということでしょうか。もちろん議決が必要ですから。","respondent":"高橋区長","answer":"規約の変更という問題ですか。","voiceIndex":17,"id":"exchange-005"},{"speaker":"石田委員","kind":"質問","question":"わかりました。ですから、そういう形の中で、議長を先頭にした部分が各議会にある程度話がきて、議会の判断がされるというふうに理解をしておきます。７月２５日から精力的に７回動かれた。そうすると、どういうおつもりで区長はいらっしゃって、どういう働きかけをして、精力的にこれを開いていこうとされているのかまずお考えをお聞きしたい。","respondent":"高橋区長","answer":"すみません、１つ忘れていました。区長会でこの第２分科会の報告をほぼ了承いたしました。これを具体的な進め方につきまして、助役会に検討を下命しているわけです。いつまでに助役会から上げるというふうなことの期日の指定はしてございません。","voiceIndex":21,"id":"exchange-006"},{"speaker":"石田委員","kind":"質問・要望","question":"各区がある。そうなってきたら、まさに活動体としてどういうことを起こしていかなくてはならないのかなと思うわけですが、仲間づくりの部分で、議会は議会でもちろんやっていかなくはなりませんが、区長のお仲間づくりの感覚として、これを今助役会に下命をして、仲間づくりの部分でどこら辺まで突っ込めるとお考えなのか、もしそのお考えがあればお聞かせをいただきたい。","respondent":"高橋区長","answer":"第２分科会の報告の中で種々うちのほうの意見も言わせていただきました。しかし、妥協するものは妥協しなくてはならないと思っています。","voiceIndex":23,"id":"exchange-007"},{"speaker":"石田委員","kind":"意見","question":"例えばブロックにすることによってこういうふうに変わるメリットがあるんだ、品川区はこういうことを逆に言っていけるし、こういう意見を、帰属の問題も含めてこういうふうになれば、品川区はこういう使い方をして、こういうふうなメリットがあるんだということを打ち出していかないと、なかなか全体を理解してもらうというのは非常に、他区の方から耳に入ってくるのは。","respondent":"高橋区長","answer":"したがって、本来的に２３区が東京都から清掃業務を全般にわたって移管を受けたんだから、移管を受けて、後に東京二十三区清掃一部事務組合にこういうものをやってもらおうというふうな体制の見直しをもう一遍私はすべきだろうと、そういうふうに考えております。","voiceIndex":25,"id":"exchange-008"},{"speaker":"石田委員","kind":"確認","question":"覚書の中でも、例えば処理協定がブロック間で成立をしていくと、こういうこともクリアをしていかなくてはならないということがあるならば、これからの活動体として、区長が議会を、もちろん品川区議会で結構ですが、その議会をどういうふうにお考えになって、我々品川区の考えを各区へ伝えていかなくてはならない仕事があると考えていますが、議会を含めて、議長会もあるわけですから、そこら辺の議決の部分。","respondent":"高橋区長","answer":"それには連絡を密にして、この業務の進め方については意見を言い、また他区に働きかけなくてはならない場合がありますときには、議会と連絡をとって働きかけていきたいと思っています。","voiceIndex":27,"id":"exchange-009"},{"speaker":"本田委員","kind":"質問","question":"制度上のことでお尋ねしておきますが、現在の東京二十三区清掃一部事務組合は平成１７年度で暫定期間という格好でいますね。そういう制度上のことで、今の存続という方針のもとに東京二十三区清掃一部事務組合のあり方はどういうふうですか。つまり存続を２３区の議会が承諾をすると、しないという意思を示せばいいのか。お伺いします。","respondent":"高橋区長","answer":"私は、この２つを満たさなければできないんだというものの考え方ではないと思っています。","voiceIndex":29,"id":"exchange-010"},{"speaker":"本田委員","kind":"質問","question":"そういうふうな今のお話ですと、こういう各区の独自性をより柔軟に、入りやすい東京二十三区清掃一部事務組合にしていくわけには、一たん解散してつくり直すということのほうが入りやすいのかなというふうに思うんですけれども、さっきからの話をずっと聞いていると、どうも第３ブロックだけが突出しているような感じで、全体の流れはあまりいじくらないで、現状存続の方向で。","respondent":"高橋区長","answer":"だけど、これは区長会で取り決めをして、それで議会といろいろ話し合う問題、そういう問題も残っているし、また具体的にどう進めていくかという問題も残っているんだからいいじゃないかと言ってもだめでして、おおむねというふうな言葉で結ばれたんですけれども。","voiceIndex":31,"id":"exchange-011"},{"speaker":"本田委員","kind":"質問","question":"もう一つお尋ねするのは、先ほどの議長報告で、議長に聞きたいんですけれども、１１月１８日に議長会が行われて、渋谷区、江東区、品川区含めてのお話で、区長報告を受けて了承ということですが、今の報告を聞いて、江東区とか渋谷区、そういう発言があったというのは、存続という方向に全体がいっているんだけれども、議会サイドではそうじゃない態度をとるよという動きがあっての発言ですか。","respondent":"築舘議長","answer":"今の問題は、手続きといいますか、要するに区長会の総会の報告ということで、中間処理のあり方についても東京二十三区清掃一部事務組合の担当のほうから説明があったわけですけれども、そのことに関して、やはり今までずっと７回にわたって。","voiceIndex":33,"id":"exchange-012"},{"speaker":"本田委員","kind":"意見","question":"わかりました。一番新しい都政新報を見ますと、東京二十三区清掃一部事務組合はそのまま続いていって、今ある東京二十三区清掃一部事務組合は何らかの手直しというか、若干そういうことはあるにしても、このまま東京二十三区清掃一部事務組合が続いていくという印象をこの記事からは受けるんですよね。その辺はもう一度、重ねて聞くようで申しわけないんですが。","respondent":"高橋区長","answer":"そういう意味で「平成１７年度の末までに」というふうな言葉を入れてもらって、この規約が成立したわけでして、それを考えますと、やはりもう一遍見直しをするときに、現状で東京二十三区清掃一部事務組合で運営をする場合でも。","voiceIndex":35,"id":"exchange-013"},{"speaker":"本田委員","kind":"確認","question":"まだ５年間の期間の途中ですけれども、暫定期間というふうに置いたこの移管を受けて、これが各区においても、また東京二十三区清掃一部事務組合についてもどうであったのかといういろいろな問題点、よかったいい点とかそうでない点とか、そういうものをもっとわかるように出していただきながら、この東京二十三区清掃一部事務組合のあり方について我々もものが言えると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-014"},{"speaker":"土井副委員長","kind":"質問・要望","question":"そこのところは、私のニュアンス、これをいろいろ聞いていると、どうも現状追認の文章を書くための時間をくださいよというふうにしか思えない部分があるように思えてならないものですから、あえてそこら辺を伺っておきたいことと、逆に、これからの協議会での協議のあり方、もっていき方、我々の活動の仕方というところにも大きく影響を与えるのではないかと思いますので、その辺の見方。","respondent":"高橋区長","answer":"今言いましたように、決められている問題といいますと、４ページにあります「清掃一部事務組合の抜本的改革は次のような方向から検討を進めるべきである」というふうに５つの項目があります。","voiceIndex":38,"id":"exchange-015"},{"speaker":"土井副委員長","kind":"確認","question":"まさしくおっしゃったように、これはこのままいくという結論じゃないよということはそのとおりであるし、我々もそう受けとめて、これから運動をやらなきゃならんと、ここのところは確認をみんなでし合いたいと思うんですけれども、先ほどのあれも含めましての皆さんのお話にもありましたようなこの流れの中で、非常にその辺の状況をしっかり見極めておかないと、それこそ先ほどの区長のお話のように。","respondent":"高橋区長","answer":"したがいまして、助役会に検討状況を伺うと同時に、もっと早急にやってくれとかというふうなものの言い方を区長会からしていくようになると思います。","voiceIndex":40,"id":"exchange-016"},{"speaker":"林（宏）委員","kind":"確認","question":"いろいろありがとうございました。確認をしておきたいんですけれども、これは今週出た都政新報なんですけれども、これの表題のところには、共同処理を存続することなどを決定したと書かれている。高橋区長の思っているこれからの流れと、いわゆる２３区の流れは違うんじゃないかと私は危惧をする。そこの中で、平成１７年度末の問題についてどういうような話し合いが行われているか聞かせてくれますか。","respondent":"松本環境清掃事業部長","answer":"実は、この東京二十三区清掃一部事務組合の枠組みの問題については、現在のところ、検討は停止をしています。全く活動してございません。","voiceIndex":42,"id":"exchange-017"},{"speaker":"林（宏）委員","kind":"質問","question":"７月１０日付の区政会館だよりの中に、部長会会長に聞くというインタビュー記事が載っていて、この中に、「平成１８年度に向け安定的な中間処理体制のあり方を考える大事な年だと思います」と述べられている。部長会は何も話はしていないんですか、このことについて。下命がなきゃ動かないという仕組みなんですか。","respondent":"松本環境清掃事業部長","answer":"その段階で、実は助役会のほうから、８月６日の段階ですけれども、今まで地域処理の考え方、あるいは地域処理移行に伴う財産取り扱いの考え方について下命がございましたけれども、これについて「下命事項の検討の中止について」という文書をいただきました。","voiceIndex":44,"id":"exchange-018"},{"speaker":"林（宏）委員","kind":"質問","question":"下命があってからやる、指示待ち組織なんですか。私はオフレコでも各区の議論をすべきだと思う。それで情報がとれるわけですよ、各区の思いが。そういうことをやってこそ責任ある管理者だと私は思う、その人たちの集まりなんだからね。していないというんだから、次に移ります。どうやって手続きを踏んで解散するという。解散する場合は、どういう形で解散ができるのか、事務方のほうのあれでわかりますか。","respondent":"市岡企画財政課長","answer":"一般論ですけれども、地方自治法上は東京二十三区清掃一部事務組合の構成員である各地方公共団体が議会の議決を得て協議をして解散を決定するということになります。","voiceIndex":46,"id":"exchange-019"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、この規約の２項の附則の読み方なんですけれども、「共同処理を廃止するものとする」、前提は協議をするということですけれども、存続するには規約を改正しなきゃならない。となると、２３区の議会がこのことについてきちんと議論をして、廃止なのか、存続なのか、あるいは延長なのか、それは２３区の議会が結論を持ち寄らなきゃできないという、そういう考え方でいいですか。","respondent":"市岡企画財政課長","answer":"基本的にはそのとおりだと思います。ただ、いろいろ手続き的な点について若干グレーゾーンもありますので、それで区長が先ほど来ご説明しているとおり、協議会で協議をするというふうな表現になっているものと考えます。","voiceIndex":50,"id":"exchange-020"},{"speaker":"林（宏）委員","kind":"質問","question":"今違うといったのは、協議会と評議会があるんですね。この規約の中には、重要事項については評議会を開くとなっています。今回の区長会の決定を見るのに、この評議会というのは開かれたんですか。","respondent":"高橋区長","answer":"私、東京二十三区清掃一部事務組合の、全然話がございませんでしたけれども、先ほど申し上げましたように、この規約の問題について、２３区の区長で構成しております協議会で検討いたします。検討した結果、やはりこの東京二十三区清掃一部事務組合の評議会にこの問題をかけます。","voiceIndex":52,"id":"exchange-021"},{"speaker":"林（宏）委員","kind":"提案","question":"だから、もっと議論がきちんとされたのではないかという想像をするものですから、評議会が開かれていないということなら、もっと議論があってもよかったのではないかなと思っている。とすると、この第２分科会から区長会に上げたときに、このアンバランスに対しての解決への提案みたいなものはないんですか。","respondent":"高橋区長","answer":"今、助役会から報告をもらった、その内容について再度同じことをやってもらうのか、やはり区長会である程度詰めて、ある程度の問題点を出して助役会に下命したほうがいいんじゃないかとか、そういう意味で急遽、第２分科会で７回にわたってやっていただいたわけでして。","voiceIndex":56,"id":"exchange-022"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"２３区の中のある区が入れないと主張しているわけですから、こんな操業協定があっておかしいよというのは、自分たちのことだ。そうですよね。問題点をはっきり明示すべき、これは抽象的な５項目になっているんですよね。具体的に、この平成１７年度末に一応方向を見つけたけれども、解決するべき問題はこういうことであるというのを出していくべきだと思いますけれども、いかがですか。","respondent":"高橋区長","answer":"工場を移管するということにはなっていないわけでして、そういうものも含めてというふうな、座長は大田区長ですから、座長がそのような説明はいたしました。ですけれども、ほかの区がそれでいいんだよとは言っていませんでした、はっきり申し上げまして。","voiceIndex":58,"id":"exchange-023"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"東京二十三区清掃一部事務組合の引っ越しは、言ってみれば必要ないというのが、ここで議論していませんけれども、今回、自治会館のほうは総務委員会のほうに回っていますけれども、それはそういう形をこれから東京二十三区清掃一部事務組合あるいは区長会でやっていくべきなんで、ひとつ自治権というところの原点に戻っていただきたい議論をお願いしたいんですけれども、いかがですか。","respondent":"高橋区長","answer":"ですから、区長会が中間処理の問題についてあまり深くかかわっていないところもそこにあるわけでして、ですから、当分の間、それでもらったんだから。","voiceIndex":60,"id":"exchange-024"},{"speaker":"堺委員","kind":"質問・要望","question":"意見というか要望になるのかなとは思いますが、今まで論議してきた中で自分なりにある程度整理ができたんですけれども、今お話が出ておりましたように、この都区制度改革については、いただいたきょうの資料の２枚目のところにもありますように、「平成１２年４月の都区制度改革により、清掃事業が基礎的自治体である特別区が担うこととなった」という中で。","respondent":"高橋区長","answer":"したがって、地域処理にするか、自区内処理にするかという、それだけの結論を２年間かかって区長会で出なかったこと、また区長会で検討ができなかったこと、これが１つの大きな証左だろうというふうに思っています。","voiceIndex":63,"id":"exchange-025"},{"speaker":"石田委員","kind":"質問・要望","question":"すみません、１点だけ意見というか。ある場面でちょっと話をしてしまったら、ばばばばばっと言われてしまって、意見がいっぱいあるなと思ったんですが、水曜日と土曜日の、これはもちろん可燃ごみはしようがないんですが、これも検討していただきたい。これは要望にしておきますのでぜひ、こういうことがあったということだけ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5628#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=12&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":31839,"voices":75}},{"id":"h15-20031127-16","meetingId":"h15-cm11","date":"2003年11月27日","dateIso":"2003-11-27","committee":"街づくり特別委員会","time":"午前１０時０５分～午前１１時５４分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を38件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"以前、平塚の地域で工事の話がなかなか成り立たなかったところには、狭い道路に立坑をつくるので、車が通れない問題が非常に大きかったと思うんですけれども、今回、立坑が５カ所あるということでは、旧中原街道も大変狭いので、その辺の問題点は出なかったのかどうか、お知らせいただきたいと思います。","respondent":"矢部下水道河川課長","answer":"駐車場を持っている方がおりまして、その方につきましては、近くにコイン駐車場があります。そこを工事の期間の間私どもで借り上げて、そこを臨時の駐車場にしてもらうというような形で対処するというような説明をして、一応ご了解を得ております。","voiceIndex":9,"id":"exchange-001"},{"speaker":"藤田委員","kind":"質問","question":"おそらくこれは中原街道が上に上ってきて、補助２６号線が下になるのではないかと思うんですけれども、相当の幅をとって立体的にすると思うんですけれども、そのときに距離が、星薬科大学のところまで工事に支障がないのかどうか、基礎工事も打たない中で立体交差をやりますから、その辺は大丈夫なんでしょうか。","respondent":"中谷まちづくり事業部長","answer":"藤田委員お話の、中原街道と補助２６号線の交差する平塚橋の交差点につきましては、現在下水道の立坑基地となっております第一日野小学校の脇のところの新たな道路が旧中原街道方面をずっと通りまして平塚橋のところで交差するということになっておりまして。","voiceIndex":11,"id":"exchange-002"},{"speaker":"伊藤委員","kind":"質問・要望","question":"まとめてお伺いしたいんですが、一つは、要望書の効果はどれぐらいある見込みでしょうか。それから、２３区が共同で提出をしたわけですから、その具体的な回答といいましょうか、東京都側がこういうふうに考えていますとか、こういうふうにしますということは、どういうルートで２３区に戻ってくるのか。","respondent":"矢部下水道河川課長","answer":"要望活動をしたときの話では、今言ったように、逆に言うと、これを追い風にしたいという東京都下水道局のほうの意向もありますし、東京都と２３区が連携しながら。","voiceIndex":18,"id":"exchange-003"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ただ、今は確かに現状の報告でありますけれども、もう一つこれを具体化していくために、しかも、品川区長が代表になっているわけですから、実のある対処の方法とか、計画のご説明はいただいて結構なんですが、それをさらに少しでも実効のあるものに近ずけていくための今後の活動の方向性とか、方針をもう少し教えていただければ、品川区としてはどうなんでしょうということをお伺いしたいんです。","respondent":"矢部下水道河川課長","answer":"今後の活動ですけれども、もちろん今回持って行って、それで終わりという考えではございません。１２月１２日に各区の課長に集まっていただくのも、今後の取り組みをどういうふうにしようかというところを決めていきたいという趣旨で集まっていただく予定になっております。","voiceIndex":20,"id":"exchange-004"},{"speaker":"伊藤委員","kind":"質問・要望","question":"１２月１２日に２３区の課長と東京都の課長の会を開くということをお伺いして、ここの取り組みをどう展開していくのかというのを一つお話しいただいたんですが、例えば課長会、部長会、助役会、区長会それぞれあると思うんですけれども、区長会はここで出されているわけですから、組織の流れの中では、例えば課長会が部長会に上げていくとか、要望書を生かすためには。","respondent":"矢部下水道河川課長","answer":"１２月１２日は課長会ですけれども、土木主幹部長会、助役会等、その辺の動きにつきましては、今こういうふうにやるというのはちょっと出せないんですけれども、その辺も踏まえながら、今後の活動について考えていきたいと考えています。","voiceIndex":22,"id":"exchange-005"},{"speaker":"伊藤委員","kind":"質問・要望","question":"２３区共通の課題であるし、それから東京都が一括して事業をやっている話でありますので、ただ、都民、区民の生活とか、日常の安全に係わる話でありますから、東京都の財政状況が厳しいのは分かりますけれども、だからと言って、例えば品川区なり、いろいろな区が毎年水害の被害が起こっていいのかというような話だと思いますので、そういう思いがあるからこそ区長もこれを出してくださったのですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今回初めてこういう形で２３区特別連絡会というのができて、２３区としてまとまってこういう方針を出したということだと思うんですけれども、下水道に関して、今までこういうふうな動きというのは全くなくて、今回が初めてということだったんでしょうか。","respondent":"矢部下水道河川課長","answer":"ただ、それは２３区全体ではないんですけれども、その後、各区ごとにそれぞれ要望しております。現在もそれは引き続きやってはいますが、私の記憶の中では、２３区がそろった形での組織は今回が初めてではないかなと考えています。","voiceIndex":31,"id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"来年度については、６月までに予算を持っていくということが一番効果的だということですけれども、そういうところからすると、ここの議会の中では、まとめたことというのは、来年度に直接反映するのはなかなか厳しいけれども、再来年度以降については、そういうところで反映されていくということも大きいということで考えていいでしょうか。","respondent":"矢部下水道河川課長","answer":"東京都のほうも、要望書をどういうふうな形で来年度予算に反映するというのは、はっきりした回答はいただいておりませんけれども、個別の特別区別要望事項一覧表の中身につきましては担当部署のほうに渡っておりますので、ここに書かれている内容については。","voiceIndex":33,"id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"東京都と話し合いをしたときも、いろいろな運動とか、請願だとかが、凄く大きな力になるというふうなことを東京都の方からお聞きしたんですけれども、そういう意味からもぜひ今後とも力強い働きかけをお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-009"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"東京都の予算というところに絡んでくるんですけれども、区から要望はしているわけですけど、都議会の中での要望事項というのは同じような形で進んでいるのかどうか、ここら辺が区のほうとして情報をつかんでいらっしゃるのか、教えていただければと思います。","respondent":"矢部下水道河川課長","answer":"都議会につきましては、都議会の中でどういうふうに動いているというのは、私のほうでも、どういう質問があってというところまでは把握しておりません。","voiceIndex":36,"id":"exchange-010"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"議会が違うから分かりにくいのもあると思うんですけれども、予算を要望する上ではかなり使える部分があるのではないかなという気もするんですが、そこら辺を今後検討をしていただければということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-011"},{"speaker":"伊藤委員","kind":"質問・要望","question":"個々具体的な内容について、２３区共通の要望をしていくんですけれども、特別区別ですから、各区別の要望も当然あっていいわけでありますので、この一覧表の位置づけが参考資料でないと私は思っているんですけれども、その位置づけを教えてください。","respondent":"矢部下水道河川課長","answer":"そういう中で、ここまでは必要ないのではないかという区の意見がかなり出まして、２３区をまとめていくとなると、ばらばらでできませんで、１本にまとめるためには、参考資料という扱いでまとめたという経緯です。","voiceIndex":39,"id":"exchange-012"},{"speaker":"伊藤委員","kind":"質問・要望","question":"その経緯は分かりました。ですから、確かにそれは２３区はいろいろな状況があるでしょう。それは分かります。だけれども、品川区は特にこうなんだということについては、今回は２３区で一緒にできなかったにせよ、この部分は生かす必要があると思うんですが、これからの、この一覧表の位置づけとか、対処する方法ももう少し具体的にしていかないとまずいんじゃないかと思うんですが、いかがですか。","respondent":"矢部下水道河川課長","answer":"委員おっしゃるとおりだと思います。ただ、参考資料といえども、これを下水道局には提出しておりますので、下水道局が今度財務局と渡り合う中では当然これが生かされて財源確保という形になるかと思います。","voiceIndex":41,"id":"exchange-013"},{"speaker":"伊藤委員","kind":"質問","question":"２３区共通の部分がある、これは分かりますし、それはやってください。併せて、東京都にいろいろなことを要求してく中では、個々具体的なものがあったほうがはるかに説得力があると思いますので、一覧表をつくっていただいたわけですから、２３区共通の段階では参考資料としていたしかたないです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-014"},{"speaker":"伊藤委員","kind":"質問","question":"設置は分かったんですが、設置して、それをどう活用するんですかということの説明をいただければありがたいんです。","respondent":"矢部下水道河川課長","answer":"水防体制も、ここまで上がって、水が橋を越えているよというような状態になりましたら、例えば土木事務所のほうに出動をさせるとか、そういうような形の迅速な水防体制も可能になるかと思います。","voiceIndex":49,"id":"exchange-015"},{"speaker":"伊藤委員","kind":"意見","question":"たしか大雨警報の基準が緩和になりましたでしょう。だから、それに合わせてリアルタイムに立会川の状況を把握しながら、さまざまな体制がやりやすいと思いますので、ぜひそういう方向で活用してください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":51,"id":"exchange-016"},{"speaker":"藤田委員","kind":"質問","question":"聞き漏らしてしまったのかわかりませんが、照明のライトがふだんは付いていなくて、職員がパソコンを操作すると付くようになるんですが、夜間の場合はどうなんですか。職員が帰ってしまったという場合はどういうふうにやるんですか。","respondent":"矢部下水道河川課長","answer":"それで昼間については、担当する職員がパソコンの映像を見ながら、照明の付け消しをやりますので、画像として、夜間ですと真っ暗で見えないので、そのときのスポットライトを照らすような形ですけれども、それは職員がいないと操作はできないです。","voiceIndex":52,"id":"exchange-017"},{"speaker":"藤田委員","kind":"確認","question":"そうすると、ライトにあてて水位を見て初めて水位が上がったという確認ができるわけですね。そこで、警報のサインを押したり、防災のお知らせをしていくと。夜間のための照明だということですか。","respondent":"矢部下水道河川課長","answer":"ですから、鳴らすタイミングにつきましては、それが一つの基準になります。それにプラスをして、今回こういうことで安全度をさらに高めたです。ですから、これを見ながらサイレンを鳴らすということではありません。基本的にはあくまでも水位グラフを見ながらやります。","voiceIndex":56,"id":"exchange-018"},{"speaker":"藤田委員","kind":"質問","question":"もう１点、立会川に、東京駅周辺の地下水の導水をずっとやっていますね。これは常時流しているわけですね。夜間にもし集中豪雨が起こった場合でも、これはやはり流れているわけですか。だれがその判断で門を締めるのか、そこら辺をちょっと教えてください。","respondent":"矢部下水道河川課長","answer":"これにつきましては、気象庁のほうで注意報が出ましたら、ＪＲの本社のほうに２４時間体制で待機しておりますので、それが出たら、送水ポンプを切ることになってますので、そういう状態になったときには地下水は出ない形になっております。","voiceIndex":58,"id":"exchange-019"},{"speaker":"原副委員長","kind":"意見","question":"今監視用カメラのご説明をいただいたんですが、おさらいをする意味で、例えば目黒川にも付いていますね。そのシステムなどもいろいろあると思うんですが、そのかほに川ではなくて、例えばよく水害の起こるところに付けるとか、監視用カメラについてのお考えがあるのか。それから、目黒川もおさらいをしたいんですけれども、それを説明いただければと思います。","respondent":"矢部下水道河川課長","answer":"立会川のほうの話ですけれども、立会川に関しましては、開渠になっている部分につきましては、それほど延長は長くありませんので、この２カ所に設ければ大体把握できるのかなと考えております。","voiceIndex":60,"id":"exchange-020"},{"speaker":"原副委員長","kind":"質問","question":"もう一つ、この監視用カメラは川に付けるような形でやっていらっしゃるんですけれども、ほかの箇所に、例えば増水した後、床下浸水とか、床上浸水とかと起こる箇所というのは結構ありますよね。そういったところを監視するような形のものというのは考えられていないんですか。","respondent":"矢部下水道河川課長","answer":"あくまでも品川区のほうは河川の維持管理を担当するということで、河川の水位について常時観測できるような形のものを考えておりまして、その他の場所については今のところ予定しておりません。","voiceIndex":64,"id":"exchange-021"},{"speaker":"伊藤委員","kind":"質問・要望","question":"もう一つ踏み込んで、例えば携帯電話経由でパソコンにアクセスをして映像を見る仕組みは、今は技術的には十分できるはずですから、例えば区長とか、水防対策に係わる管理職の皆さんがどこにいても、水防本部が立ち上がる前の段階であったとしても自分の目で確認できるシステムを考えてはいかがですかということをお話ししたいのと、それから。","respondent":"矢部下水道河川課長","answer":"その後、伊藤委員のおっしゃるとおりの形の外部からのアクセス、あるいはホームページ等については、その結果を見て検討をしていきたいというふうに考えてあります。","voiceIndex":66,"id":"exchange-022"},{"speaker":"西本委員","kind":"質問","question":"それと、例えば外からアクセスできるような、インターネット経由の形のソフトを使われているのか。それと、遠隔操作もいろいろあったりしますので、費用の件でどれぐらいかかっているのか、そこがちょっと分かりましたら教えてください。","respondent":"矢部下水道河川課長","answer":"ということで、その辺は広くその辺を情報提供できるかというのは、今後の検討課題かなと思います。そういうような課題が残るかと思います。","voiceIndex":68,"id":"exchange-023"},{"speaker":"西本委員","kind":"確認","question":"そうすると、ここに来ない限り、この画像を見て、警報を発するとか、独自の場所に資料を出すとかという形になるということで、そこら辺の時間のラグというか、その前に水位が上がってきますから、当然サイレン等が鳴るんでしょうけれども、迅速にするためのカメラ設置になるわけですから、サイレンが鳴る前に対処するということの目的があるのかなというふうに思っていたので、そうすると、ここに来るよりも。","respondent":"矢部下水道河川課長","answer":"委員おっしゃられるように、確かに今回の映像も自宅で見れるようになれば、さらに安全度が増すかなという感じもしますので、その辺については、それが可能かどうか検討をしてみたいと思います。","voiceIndex":70,"id":"exchange-024"}]},{"id":"topic-02","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"木下委員","kind":"質問・要望","question":"これは今までもそういう事例があったということもほかの議員方からも聞いておりますので、東京都が財政的な部分でなかなかできない部分であれば、区が先行投資という形でやれないかという要望が１点。地域の方にもいろいろな要望、意見を聞きましたので、個別なことになりますけれども、地域的に土のうが置いてない地域もありますから、早急に土のうとか準備をしていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-025"},{"speaker":"木下委員","kind":"質問","question":"ということは、雨水調整池に代わるものとして、今第二立会川幹線をやっていますから、それで対応できるというふうな認識でよろしいでしょうか。","respondent":"矢部下水道河川課長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-026"},{"speaker":"木下委員","kind":"質問・要望","question":"は先ほどの細かいことは意見、要望ということで取りまとめていただきたいと思いますので、ひとつよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":80,"id":"exchange-027"},{"speaker":"伊藤委員","kind":"確認","question":"取りまとめの方向に入っていることは、皆さんももちろんそうだと思うんですが、何点か確認したいことがあるんですが、これはいつぐらいまでにまとめていくという計画でしょうかということを委員長にお伺いしたいことが一つ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-028"},{"speaker":"伊藤委員","kind":"意見","question":"今の仕切りで、自民党としましては、品川区全域のことを考えていかないといけないと考えていますので、例えばそれぞれの委員がここで発言されたとしても、おそらく品川区全域のことを見つめた、例えば私はどちらかというと荏原地域のことはわかりませんし、そういうこともありますので、一旦会派に持ち帰らせていただきまして、自民党として意見を取りまとめをして、改めて提出したいと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":83,"id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"治水対策というところでは、多くのほとんどのところが東京都の施策に係わるというところで、今回品川区が中心になって２３区で要望書という形でこういうふうにまとめて出していただいたわけですけれども、この委員会としても、東京都に対して議会として要望書を出していくということで、まとめていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-030"},{"speaker":"藤田委員","kind":"質問","question":"当委員会が今年の６月から約６カ月間かけてやってきたんです。これは治水対策に関する部分での、委員の皆さんでお骨折りいただいて、こうしたたたき台のような検討事項のまとめをいただいたんですけれども、これだけに絞ってまとめをするのか、その辺のことをお伺いしたいと思います。そちらの東急のほうはそれをやらないで、治水だけでやっていくというお考えなのか、この辺をまずお伺いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-031"},{"speaker":"藤田委員","kind":"意見","question":"了解いたしました。両方の１年間議論をしてきた途中経過でもありませんが、一定のことで議論をしてきましたという報告を出していく必要性があるのではないかと思って、発言をさせていただきました。それから、大変ご苦労をいただきまして、次回、各会派でいろいろ議論をもとに付け加えることがあれば、付け加えるという方向で、今日のところはよろしいのではないかなというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":88,"id":"exchange-032"},{"speaker":"三村委員","kind":"質問・要望","question":"会派のほうの意見としてどういう形で出せばいいのか、最終的に委員長のほうに出すのであれば、こういう形式で出してくださいというように言っていただければ、初めてなので、どういうような形で内容を整理していいのか、会派の意見を出していいのか、ちょっとわからないので、一応私たちの会派としてはどういったことでやっていってほしいかという意見を。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-033"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今回は治水ということですけれども、集中豪雨の問題がここのところ雨水対策で考えられているんですけれども、雨水対策ではとても追いつかない現状というところでは、特にこの間環境の問題でもヒートアイランド現象の問題が出されていますけれども、ここの原因をどう対策していくのかという大きい意味でのまちづくりなので、その辺も含めて、東京都全体。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":90,"id":"exchange-034"},{"speaker":"西本委員","kind":"提案","question":"ばらばら要望があると思います。それはそれで必要なことだと思います。ですけれども、この委員会としてどういう方向性でこれをまとめ上げ、例えば来年度の６月の予算の時期に区として東京都へ上げるための方向性として持っていこうとするのかというところも含めて、方向性をはっきりしてもらいたいなという要望があったんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":91,"id":"exchange-035"},{"speaker":"西本委員","kind":"意見","question":"そこら辺はどういう進め方が一番いいのか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":93,"id":"exchange-036"},{"speaker":"西本委員","kind":"質問・要望","question":"そうすると、例えば私は初めてこの委員会に出ているので、総意という形まで詰めなくていいという発想でよろしいんですか。そういうことではなくて、ある程度、こういう意見、こういう視点でこういうふうになるよというような意見を述べるという形でまとめるというところでよろしいんでしょうか。そこだけ確認をさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":95,"id":"exchange-037"},{"speaker":"伊藤委員","kind":"確認","question":"直接内容ではないんですが、もう委員長はご承知かと思うんですが、委員会の意見の取りまとめをして、直接こういうところに出すとか、そういうことでなくても、まずは議長に出す。それから、議長のところでどういう取りまとめをするかということを確認した上で、区議会としての意向を決定していくと思われますので、その対処をよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":97,"id":"exchange-038"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6266#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":28812,"voices":103}},{"id":"h15-20031128-14","meetingId":"h15-cm11","date":"2003年11月28日","dateIso":"2003-11-28","committee":"行財政改革特別委員会","time":"午前１０時０８分～午前１１時５８分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"行財政改革に関することのうち、議員定数に関すること","agenda":"行財政改革に関することのうち、議員定数に関すること","exchanges":[{"speaker":"山村委員","kind":"質問・要望","question":"品川区の定数を削減してから今まで、品川区民から、定数削減の陳情が何回出ているのか、教えていただきたい。","respondent":"福田区議会事務局長","answer":"今、調べしますが、直近のものといたしましては、陳情１件、昨年の行財政改革特別委員会の中でご議論をいただきました。","voiceIndex":5,"id":"exchange-001"},{"speaker":"山村委員","kind":"質問","question":"その陳情の内容は、定数をどの程度まで削減とか、そこまで書かれてあったんでしょうか。","respondent":"福田区議会事務局長","answer":"現在の定数４２人を４０人とするだったと思います。今、確認をしますが、間違っていれば、すぐに訂正します。","voiceIndex":7,"id":"exchange-002"},{"speaker":"田中委員","kind":"質問・要望","question":"ちょっと質問になるのかどうか、ご見解を聞かせいただきたいというようなニュアンスになるかと思いますが、資料No.１の議員１人当たりの数字、これは、私がお願いしてつくっていただきまして、大変見やすく、そういった観点からぱっと比較できるような資料をご提示いただきまして、まずはご苦労に感謝申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-003"},{"speaker":"田中委員","kind":"質問・要望","question":"この数字をベースにして、議会運営委員会の委員同士で議論をしていくという材料になるので、今回の資料は、そういう意味では、これを基礎データとして議論を進めていくという流れになってくると思うんですが、ちょっと質問という形態をとるとなると、そういう聞き方しかできなかったので、私はそういう意見なんですが、まず一たんは、当初のご見解をお聞かせいただきたい。","respondent":"福田区議会事務局長","answer":"二つ合わせてのお答えになるかと思いますが、まさに、それが一つの重要な論点だろうと。別の観点につきましても、これは当然にご議論の中でありますので、あろうかと考えております。その調和をどういうふうに保つのかということが、この委員会ではなかろうかと思っています。","voiceIndex":11,"id":"exchange-004"},{"speaker":"南委員","kind":"提案","question":"紹介していただいた幾つの市については、投票率のところを見ると、どこもみんな下がっているんですよね。その影響として、投票率が下がってきているというふうに見てしまうのは乱暴なのかどうか。これをどういうふうに見たらいいのかと思うんですけれども、ちょっと調べていただいた局長としての感想というか、その辺についてはどうなんでしょうか。","respondent":"福田区議会事務局長","answer":"その証左といたしましては、資料No.４ですが、品川区をご覧いただきたいと思いますが、先ほど申しましたように、昭和５４年から５７年まで、一貫した漸減であります。","voiceIndex":13,"id":"exchange-005"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、もっと投票率を増やす努力をしなきゃいけないし、先ほど説明では、議員削減そのことが大きな原因ではない、別の原因ももちろんあるんだというお話で、それはそうだと、私も思いますけれども、しかし、投票率の項目で見たときに、どうしたらもっと上げられるのか、それと関連して、上げる方向で、議員定数の論議をどういうふうに作用させていけるのか、そういうところの論議をしていかないと。","respondent":"福田区議会事務局長","answer":"したがいまして、比較すべきは、平成７年４月の選挙の５７.３０％と、改正後に行われました平成１１年４月の５９.９６％、この両者を比較するべきものであると考えられます。比較いたしますと、２.６６ポイントの増という形になります。これがお答えであります。","voiceIndex":15,"id":"exchange-006"},{"speaker":"塚本委員","kind":"質問・要望","question":"資料No.１のほうから読み取ることに関連して、お伺いします。そこのところを、ひとつ確認をしていきたいと思います。２３区の中でも、大都市論の中での議論があるということなんですけれども、前にも聞きましたけれども、そこのところはどう押さえるべきかなということ。２３区のほうは、ちょっと話が、見通しが難しいでしょうからあれですけれども、地方のほうの働きかけはどういうふうに動いていくのか。","respondent":"市岡企画財政課長","answer":"２点目の合併論ですけれども、これは、ご案内かと思うんですが、第２７次の地方制度調査会が、この間、いろいろ意見を出してございまして、基本的には、全国的には小規模自治体の合併という視点で、いろいろな議論が行われているというところで、２３区の中では。","voiceIndex":17,"id":"exchange-007"},{"speaker":"塚本委員","kind":"質問・要望","question":"もう少し突っ込んだ話を聞きたいんで、一般会計レベルと人口で比較したら、ほとんど差はないと、議員がどれだけ仕事をしなきゃいけないか、当然、チェックする場面が増えれば、本来、仕事をしなきゃいけないわけで、標準的なモデルを考えて教えていただきたいんですけれども、この仕事と、この仕事が増えてきて、一般会計と比較して、例えば、上下水道は一般会計の１割ぐらいの規模でやっていますよとか。","respondent":"福田区議会事務局長","answer":"財政規模との、ある程度の傾向性は読み取れるかもしれませんけれども、なかなかそれをモデル化するのは難しいのではないかなと考えています。","voiceIndex":19,"id":"exchange-008"},{"speaker":"塚本委員","kind":"質問","question":"２３区は特殊なわけですから、そこがわからない。そういうものを、一、二、モデルをつくっていただいて、職員がこんなに増えてくるから、チェックが大変ですよとか、あるいは特別会計ですから、委員会がこうなって、いろいろな決算を追いかけていかなきゃいけないという話になってくると思うんです。それは我々が少ないわけですから、そういうことを比較したいということを言っているわけです。","respondent":"福田区議会事務局長","answer":"了解いたしました。","voiceIndex":21,"id":"exchange-009"},{"speaker":"三上委員","kind":"意見","question":"もう一つ、ちょっと資料として、前回お願いしたのではなかったかなと思っていたのは、この品川区議会の中でも、４年間に、改選された議員がすべて次の改選時期までいたかどうかということが、ちょっと年度ごとにわかるような形で、グラフみたいな形か何かで。そこらあたり、わかるような一覧か何かにしていただければありがたいなと思うんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":23,"id":"exchange-010"},{"speaker":"沢田委員","kind":"意見","question":"資料No.１ですけれども、政令指定都市と、６０万人以上の大都市と、いろいろつくっていただいて、私も、今朝、来てざっと見たんで、目を全部通してないんですけれども、ほんとうに貴重な資料をつくっていただいてありがたいと思っています。よく大都市需要を見ろと、それを基準収入額にやれば対象になるじゃないかということをやったんですけれども、その辺では、実態はどうなっているのか。","respondent":"市岡企画財政課長","answer":"需要を考える場合に、例えば議会のことを取り上げれば、２３区を一つの市と見なされるために、２３区で一つの議会、一つの首長しかいないという算定をされることが問題になっております。","voiceIndex":27,"id":"exchange-011"},{"speaker":"沢田委員","kind":"質問","question":"聞きたいんですが、私、はっと思ったんですけれども、２３区で法定数、いわゆる上限を地方自治法で決めて、なおかつ６区が法定数のままという話があったんですが、この６区の議論は、どういう議論になっていたのか。何かつかんでいることがあれば、教えてほしいと思うんですが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-012"},{"speaker":"沢田委員","kind":"質問","question":"資料No.２で、1)－Ａ、あるいは2)－Ａというのは、大体都心区に集中しているんですよね。中央区、港区、新宿区、文教区、渋谷区ですか、やっぱり都心区特有の思いみたいなのがあるのかなという気がするんです。全部ということではなくてもいいんです、どんな論議をされたのか、できたら調べていただけるとありがたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-013"},{"speaker":"塚本委員","kind":"質問","question":"例えば２０人でいいかというと、そうはいかないだろうという力が働くんだろうと思います。後の資料の中に、委員会の定員数が８名から９名がいいとか、通常は、委員会数が４は必要だろうというようなことが書いてありますよね。ですから、例えば、十数人で議会を構成するということになると、ある種欧米型の議会になってしまうということなんだろうと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-014"},{"speaker":"沢田委員","kind":"提案","question":"この資料No.５の１ページ目に、「住民と行政の間で起こるトラブルの橋渡し的な機能が求められている」と言った後に、「また行政を監視し、統制し、住民の意見を行政に反映させる、さらに政策提案をすることが必要だ」というあたりで、政策提案というのは、何もこれっていうのじゃなくて、質問を通じてやる場合もあるし、予算要求でやる場合もあるかもしれないんですけれども、これは。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":35,"id":"exchange-015"},{"speaker":"須貝委員","kind":"提案","question":"ちょっと別件になりますけれども、今回、ほんとうに議員定数のことを論じているわけですから、委員長、副委員長の皆さんにも、ぜひご意見を、今、とりまとめということで動いていらっしゃると思うんですけれども、委員会の仕組みというのはあまりよく勉強していないんですけれども、やはり、今回出席されている皆さんのどんどん活発なご意見を、３名というと、ほんとうにこの中では有効な人員なんで。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":39,"id":"exchange-016"},{"speaker":"中島委員","kind":"質問","question":"この中で、例えば大田区、世田谷区、杉並区、練馬区、そのほかに葛飾区、江戸川区と、こういうところは、非常に議員の１人当たりの人数ということで、約倍までいかないところもありますし、超えているところもあるわけですよね。こうしたところと品川区と、いろいろな行政上で、何か違う部分があるのかどうか、この辺のところを、お伺いしたいと思います。","respondent":"市岡企画財政課長","answer":"ただ、行政需要という点で言えば、やはり、地域、区の特色がありまして、重点的な需要がその地域によって違いますから、おのずと各区の施策の重点を見ていただくと、大きな違いがあることがおわかりになろうかと思います。そういう認識であります。","voiceIndex":41,"id":"exchange-017"},{"speaker":"中島委員","kind":"質問","question":"その違いというのは、議員の数とかかわってくるような問題なんでしょうか。民意を反映するという面では、どうなんでしょうか。","respondent":"中尾根企画部長","answer":"その点から言うと、単純にここの数字ではないものが、当然、行政の責任にはあると。だから、したがって、人口を厳密に比較する場合だと、昼間人口なんかをもうちょっと視野に入れた議論が必要なのではないかと、このように考えてあります。","voiceIndex":43,"id":"exchange-018"},{"speaker":"中島委員","kind":"質問","question":"確かに、先ほど、私が申しましたが、千代田区、中央区、港区、この辺のところというのは特殊性があるのかなと思うわけです。品川区以下に書いてあるところというのは、特別大きな違いというのが、私はまだ理解できない部分があるんです。その辺のところの違いというのはどうなのか、知りたいと思うんですが、それは何かの形で知ることができるんでしょうか。","respondent":"中尾根企画部長","answer":"なかなかそれを表にあらわするのは非常に難しいものですから、そういった部分については、類推をする以外はなかろうかと思いますけれども、この表から読み取れるのは、そのようなことだということです。","voiceIndex":45,"id":"exchange-019"},{"speaker":"中島委員","kind":"質問","question":"ここはそうじゃないかとか、いろいろな議論というのは、いくらでもできるわけですけれども、私たちは、やはり、民意を反映するために、今、この議会で出てきているわけですから、まちの中で、皆さんのどういうご意見の多いかというと、私自身も、やはり議員の定数は減らしてほしいという声はたくさん受けているわけです。委員長のご判断にお任せしたいと思います、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-020"},{"speaker":"沢田委員","kind":"質問・要望","question":"むしろ、海外視察だとか、そういうやり方は、やっぱり見直すべきだという声は非常に強いですね。議員が議員としての本来の役割を果たすべきで、予算化したものが、ほんとうに住民のためになっているのか、どうなのかを吟味してほしい。それはやっぱり、これだけ厳しい状況ですから、正すべきもの正す立場が必要なんじゃないかと、私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-021"},{"speaker":"塚本委員","kind":"質問・要望","question":"本来、一般の財源も、そこに投入されなければいけない。直接的に、主権者、住民にリターンはないけれども、ワンクッション、ツークッション置いて、我々の利便性も増進しているわけだろうと思うんですけれども、その辺の考え方というのは、行政の世界の中で、いくらかわかってきたんですか。こういうことを基本に考えているんだというのがわかってきているんでしょうか、教えていただきたい。","respondent":"市岡企画財政課長","answer":"いろいろありますけれども、例えば地方消費税交付金、これは一定程度、夜間人口に昼間の雇用人口を加えて計算をしておりますので、行政の制度上、特別区の場合でも、昼間人口が全く考慮されていないわけではありませんが、どう考えても、そのことと。","voiceIndex":50,"id":"exchange-022"},{"speaker":"塚本委員","kind":"意見","question":"品川区の場合、働きに来てくれる人たちが、まちの活力をつくったりということは間違いないわけですけれども、観光施策のように、ストレートでないからわかりにくい部分がありますけれども、大都市の中での役割とか、あるいは、働き手をどう受け入れるかという考え方も、少しずつ整理していかないと、都市再開発は税金のむだ使いだという一方的な主張がされるようなことが、まだある時代ですから。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":52,"id":"exchange-023"},{"speaker":"高星委員","kind":"意見","question":"これまで、品川区は２回に分けて、議員定数削減をしてきた。それからもう一つは、将来、品川区がどういうまちになっていくんだろう。私が今、一番残念でならないのは、各方面の人がいろいろ指摘していますけれども、品川区のど真ん中に４００ｍに及ぶ塀みたいなものがつくられちゃって、これからどうなっていくのか、ちょっと心配でしようがないんです、ＪＲの壁ですけれども。これは意見になりますけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":53,"id":"exchange-024"},{"speaker":"田中委員","kind":"質問・要望","question":"聞き漏らしていたら、またお聞かせいただきたいんですが、今、この委員会で議論していく中で、議員定数がどうあるかということが大前提で議論されていますが、何らかの結論を出す上では、いつその結論を出すかということも、さらにその次の大きな焦点になってくると思うんで、そういう観点からお聞かせいただきたいんですが、資料No.２の２３区の比較の中で、台東区と葛飾区が。","respondent":"福田区議会事務局長","answer":"この間、提出されました議員定数の削減を求める陳情・請願につきましては１件であります。その内容でありますが、品川区議会議員の定数を４名削減し、条例定数を３８名に改める、これが趣旨です。","voiceIndex":55,"id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5742#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":32500,"voices":62}},{"id":"h15-20031205-9","meetingId":"h15-cm12","date":"2003年12月5日","dateIso":"2003-12-05","committee":"文教委員会","time":"午後２時４２分～午後２時２１分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を11件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"ただいま本会議で付託されました第６３号議案、幼稚園教育職員の給与に関する条例の一部を改正する条例の議案審査","agenda":"ただいま本会議で付託されました第６３号議案、幼稚園教育職員の給与に関する条例の一部を改正する条例の議案審査","exchanges":[{"speaker":"伊藤委員","kind":"質問・要望","question":"定期券の算定が６カ月になったと、現行が４万５,５００円を５万５,０００円に引き上げるということですが、これはあくまでも上限の金額であって、例えば、通勤距離によって当然定期券の金額は違ってきますよね。例えば近いところから通勤する人、遠くから通勤する人、定期券代は違ってきますので、その具体的な算定はどうされているんですかということを教えてください。その二つです。","respondent":"鷹倉庶務課長","answer":"第１点目の、通勤手当がなぜ４月１日からなのかですけれども、区の職員に限るということはないでしょうけれども、通常いろいろな交通の手段が変わる時期というのがこの時期じゃないかということがあるんではないかと想像されます。","voiceIndex":5,"id":"exchange-001"},{"speaker":"伊藤委員","kind":"確認","question":"確認だけですが、要は、実際の通勤距離を算定をした上で、限度額が５万５,０００円掛ける６カ月分だと、その範囲の中で支給されるということでいいんですねと、それだけなんです。","respondent":"鷹倉庶務課長","answer":"そのとおりです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"伊藤委員","kind":"質問","question":"もう一つだけ、通勤手当の１の概要のところで、手当の支給を原則として４月および１０月の年２回と書いてありますけれども、原則以外に何かあるんでしょうか。","respondent":"鷹倉庶務課長","answer":"通常、引き続き交通ルートが同じことがあるわけですけれども、途中で変わる場合もあります。あるいは、途中で入区するケース、これは通常ないですけれども、あり得ます。そういうことだとか、その辺のあり方だと思います。","voiceIndex":9,"id":"exchange-003"},{"speaker":"沢田委員","kind":"質問","question":"これは、すべて人事委員会の勧告どおりですよね。きのうの議会運営委員会で、助役のほうから説明があって、職員団体のほうとも合意を得ていると、いやいやだけれども、組合のほうとしてはということなんですが、その辺はどうだったんですか。わかれば教えてほしいというのが一つ。幼稚園の職員と、できれば区全体の職員の数がわかっていれば教えてほしいんです。わからなければ、結構です。","respondent":"鷹倉庶務課長","answer":"第１点目の勧告どおりかですが、そのとおりです。第２点目の、組合との合意を得ているのかというお尋ねですけれども、先ほど申し上げましたとおり、１１月１９日に区長会側が最終回答をし、特区連側が、非常に重大な話なので持ち帰ってという形でございました。","voiceIndex":11,"id":"exchange-004"},{"speaker":"沢田委員","kind":"質問","question":"そうすると、総務委員会のほうがメインでやって、全体総額的に、これでどれぐらい浮くかということは、資料が手元にないですか、あればちょっと。","respondent":"鷹倉庶務課長","answer":"申しわけございません、手元にございません。","voiceIndex":13,"id":"exchange-005"},{"speaker":"沢田委員","kind":"質問・要望","question":"わかりました。では、１点だけ。やっぱり国民の懐を温めて、消費購買力を増やすことが、設備投資も前に進めるんじゃないかなと思います。それから、ここでどのぐらいの金額が節減できたかということは、全体としてはわからないということなんですけれども、区として、その部分については、区民の生活、暮らしを支える分野でぜひ生かしていただきたいなということだけ、意見を述べておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"バス等を利用している場合、歩いて１km以内ぐらいでバスを使わなくてもというところでも、バスが通っていれば請求してしまうというケースも見受けられる可能性もあるんですが、この辺はどういうふうにして決められているのかということを確認したい。それから、３番の自転車等というところで、片道の使用距離と書いてあるんですが、３５km以下の場合、この辺は全く支給されないのか。","respondent":"鷹倉庶務課長","answer":"１点目の、いろいろな交通機関、あるいはバスの問題という話です。先ほど、伊藤委員の質問にも回答申し上げたとおり、まず交通経路を設定する際に、経済的かつ合理的という形で決定します。","voiceIndex":16,"id":"exchange-007"},{"speaker":"西本委員","kind":"質問","question":"１点目なんですが、通勤手当のほうはされるということなんですが、ある程度の規定、例えば最寄り駅から１km圏内のところとかそういう規定はないんでしょうか。通常会社であれば、最寄り駅から何km以内はできないという決まりがある程度決まっているケースがあるんですけれども、そういう決まりはないんでしょうか。","respondent":"鷹倉庶務課長","answer":"その場合については認められる場合もある。単に距離だけでは言えない場合もあると聞いています。それは給与の実務の関係ですけれども、そのように聞いています。","voiceIndex":18,"id":"exchange-008"},{"speaker":"石田副委員長","kind":"質問・要望","question":"１点だけちょっと教えてください。ここで、パターンとかわかれば教えていただきたいんですが、勧告するには、公民給与の実質的な均衡ということで、さまざま調査をされてから１０月７日に出てきたんだということだと思うんですね。","respondent":"古川教育次長","answer":"民間ですと、給料等は労使交渉の中で決めていく。場合によっては労使交渉によらない、例えば報酬審議会等のような第三者機関による一つのものの考え方。そしてもう１点が、いわゆる公務員に適用されている人事院、あるいは人事委員会による勧告を前提にです。","voiceIndex":20,"id":"exchange-009"},{"speaker":"石田副委員長","kind":"質問","question":"きのう、議会運営委員会でちょっと言ったんですが、基本的に、特別区は特別区で結構ですが、例えばどこかの３０万人都市があれば、ここら辺の調査から含めて、必ず基礎的自治体としてやっているはずでありますし、ここの人事委員会の部分も、品川区は品川区でということをやろうと思えば、基本的にはやれることがあるわけですから、ここの報告の部分についても、どういうところの報告のサンプルを取って。","respondent":"古川教育次長","answer":"現実に、今、２３区は共同処理ということで、人事委員会を共同設置していますが、共同設置でないということを想定すれば、その時点での給料表をつくる、つくらないも含めた区としての一定の考え方が当然問われてまいりますので、当然、人事委員会に任せるということではなくて。","voiceIndex":22,"id":"exchange-010"},{"speaker":"石田副委員長","kind":"確認","question":"今のことで、１点だけちょっと、さっき伺って、ああそうなのかなと思ったので、ここは確認だけさせてください。先ほど、３月期末のことで、差し引いていくということで、引いた額がもし多くなっちゃった場合は、そこで頭打ちという話だったんですが、０を超えちゃったら頭打ちということで決まったという理解でいいんですか。","respondent":"鷹倉庶務課長","answer":"そのとおりです。付則のところで、そういう形でうたってあります、決まりますと、そのようになります。","voiceIndex":24,"id":"exchange-011"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4492#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":11459,"voices":34}},{"id":"h15-20031205-5","meetingId":"h15-cm12","date":"2003年12月5日","dateIso":"2003-12-05","committee":"総務委員会","time":"午後１時４３分～午後２時２５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"最初に、第６１後議案、職員の給与に関する条例の一部を改正する条例","agenda":"最初に、第６１後議案、職員の給与に関する条例の一部を改正する条例","exchanges":[{"speaker":"林（宏）委員","kind":"確認","question":"ここで確認したいんですけれども、別表が何点かついていて、別表の後に３ページついていますね。これは、どこの何なんですか。第６１号議案というところから始まって、間に別表が入って、その後に３ページ分、「別表第３の云々」というところから、それは何ですか。","respondent":"桑村人事課長","answer":"基本的に、途中で別表が入ってありますが、その後は付則です。一つは施行の日、あるいは、いわゆる１２月という昇給ではなくて、一定のそれ以上の昇給の調整、あるいは、先ほど述べました所要の調整と申しますけれども、３月の期末手当といったものが付則で載っているものです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"林（宏）委員","kind":"質問","question":"ずっと続いてきてここまで付則という解釈、そうすると、一番最後の６の文案なんですけれども、「これ以外は人事委員会が定める」と書かれているんだけれども、これは区条例なんでしょ、人事委員会が定められるんですか。","respondent":"桑村人事課長","answer":"その意味では、人事機関として、専門的に、非常にテクニック的なものにつきましては、人事委員会がきちっと定めているというものです。その意味では、給与条例等につきましては、こういう定め方をしているというものです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"林（宏）委員","kind":"質問","question":"だけど、この条例の施行に関し必要な事項というと、今、人事委員会は何とかの機関と言われたけれども、品川区議会以外のところで別の人事委員会が定めるということは可能なんですか。","respondent":"桑村人事課長","answer":"ただもちろん、一定の条例に基づいてですけれども、例えば、ここでは調整の原則のやり方は条例で決まるわけですけれども、例えば、ほかの区からの異動者とか、そういったものについてどういうふうにしたらいいかとか、そういう細かいことにつきましては。","voiceIndex":9,"id":"exchange-003"},{"speaker":"林（宏）委員","kind":"意見","question":"定められると、今説明があって、僕らは定められないんじゃないかという根拠がないから、聞いておきますけれども、何となく、品川区の条例を決めるのに、よその付属機関なのか、位置づけがどうなっているかはっきりわかりませんけれども、要するに、２３区でつくっている人事委員会が条例を決めるということは、ちょっと腑に落ちないと感じながら聞いております。","respondent":"桑村人事課長","answer":"給料表そのもの、それは毎年いじっております。去年もマイナス改訂ですので、マイナスの給料表ということです。","voiceIndex":11,"id":"exchange-004"},{"speaker":"林（宏）委員","kind":"確認","question":"僕の記憶だと、表はいじらなかったと思ったんですけれども。いじったとしても、医療関係だから、別表第１、第２は前のままなんでしょ。その確認をしておきたいんです。","respondent":"桑村人事課長","answer":"その意味では、昨年度もいわゆるマイナス改訂でございましたので、給料表そのものを減額したものです。今年も同じ考え方です。","voiceIndex":13,"id":"exchange-005"},{"speaker":"林（宏）委員","kind":"質問","question":"だって、いただいた資料１は、０.６９％の減になるということが書かれているんだけれども、その次に、医師の最高限度額が書かれているんだけれども、１番目の枠と２番目の枠ってどういうふうに違うんですか。１番目は表が率で変えてある、２番目は額で変えてある、なぜそういうことが出てくるんですか。","respondent":"桑村人事課長","answer":"ちょっと説明が不足したかもしれません。給料表という、手当ではなくて、いわゆる本給です。本給につきましては、平均ですけれども０.６９％という、原則級、号数ごとに、今まで適用されたものをマイナスを掛けたという部分。","voiceIndex":15,"id":"exchange-006"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、どういうふうに計算しているんですか。０.６９％という数字の中で半端が出ますよね。それは切り上げるんですか、四捨五入なんですか。","respondent":"桑村人事課長","answer":"考え方ですが、一つは１００円単位にしているということです。それで、先ほど申し上げたように、原則級、号と同率なんですけれども、級ごとに若干ずつ違っております。","voiceIndex":17,"id":"exchange-007"},{"speaker":"林（宏）委員","kind":"質問","question":"もう一つちょっと、角度が違うんですけれども、今月の１日の広報に、職員の給与の詳細を知らせてくれましたよね。そして、あの数字はこれで変わるわけですよね。なぜすぐ変わるという時期に、ああいうものを載せて、１１日号に載せれば、変えたもので載せられるんじゃないですか。訂正を載せるんですか。それとも、これが決まってない前に、下がった数字を載せちゃっているんですか。","respondent":"桑村人事課長","answer":"それにつきましては、例えば国と比べる場合、何としても４月１日の数字というのが出てくるものですので、それに合わせて、比較するような意味も含めて、そういう数字をあの時期に出させていただいたわけです。","voiceIndex":19,"id":"exchange-008"},{"speaker":"林（宏）委員","kind":"意見","question":"最後にします。もうこれを出すのがわかっているんだったら、きょうの決定を見て、決まった後に、こういう数字で下がりますよというのを載せられるわけでしょ。だから、正確なのを伝えるとすれば、そういうほうがいいのではないかなというのを伝えておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":21,"id":"exchange-009"},{"speaker":"土井委員","kind":"質問","question":"というのは、ここでいくと、配偶者を欠く第一子となると、配偶者はいないということなのか、それとも扶養になっていないということなのかというのがちょっと気になったものですから。現実はどうなんですか。","respondent":"桑村人事課長","answer":"一つは、配偶者の方についての引き下げということ、もう一つは、配偶者がいなくて、お子さんを扶養されているという方につきましては、配偶者と同じ金額を扶養手当として出しているということです。そういう意味で、配偶者がない場合に限るというのは、そういう意味です。","voiceIndex":22,"id":"exchange-010"},{"speaker":"土井委員","kind":"意見","question":"そうしたら、そんなわざわざ小難しい表現をするから、わからないことになっちゃうんで、扶養第一人者は１万６,２００円を１万５,７００円にすると、そういう仕組みになってないのかなと思ったから聞いたんです。奥さんが給料をもらっていたときには、これは渡すような、渡さないような、でもこっちへ来ると、急に第３人目以降となっちゃうから、聞いているんです。","respondent":"桑村人事課長","answer":"今まで、配偶者があって、配偶者に職があって扶養に入っているという場合につきましては、第一子については５,５００円という金額になります。","voiceIndex":24,"id":"exchange-011"},{"speaker":"土井委員","kind":"意見","question":"父子家庭、母子家庭というときに適用するのか、それとも、配偶者が扶養家族に入っていないということで適用するのかという意味を聞いているんです。〔「欠くという意味」と呼ぶ者あり〕配偶者を欠くというのは、いないということなんでしょ。いないというのは、扶養手当という目で見ていないのか、戸籍上いないのかを聞いているんです。","respondent":"桑村人事課長","answer":"今の言い方をしますと、戸籍上にいないです。","voiceIndex":26,"id":"exchange-012"},{"speaker":"宮崎委員","kind":"質問","question":"実際に、このモデル等、そういうのはあるんでしょうか。モデル賃金というか、そういうのがあったら、実態として賃金が下がると思うんですけれども、どうなるのかということを教えていただければと思います。","respondent":"桑村人事課長","answer":"３,４８５円、マイナス０.７９％するわけですので、４３万５,４７８円という数字になるということが、２３区全体の平均ということになります。","voiceIndex":28,"id":"exchange-013"},{"speaker":"宮崎委員","kind":"意見","question":"平均というと、なかなか実態としてよくわからないところがあるんですけれども、通常、例えば国民健康保険とか、大体のモデル家族でいろいろ出していますよね。例えば勤続１０年の人、去年は勤続９年ですよね。その人が１０年になると、要するに去年と今年で、どういうふうになるのかという、わかりやすいものが何かありますか。","respondent":"桑村人事課長","answer":"これにつきまして想定している年収ですけれども、改定前が約７３５万円、改定後が７１７万円というような数字です。これにつきましては平均ですので、大体４３歳程度の職員というのを想定しています。","voiceIndex":30,"id":"exchange-014"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、４３歳で、年収が１８万円ぐらい下がるという計算ですよね。わかりました、かなりちょっと影響があるなと思います。実際に、区のほうも、当然、改定前の予算を取っていると思うんですけれども、予算への影響といいますか、区全体としてはどのぐらい出るんでしょうか。","respondent":"桑村人事課長","answer":"まだ細かい計算はしてございませんけれども、いわゆる平均しますと、大体５億円程度は減になるだろうと思ってあります。","voiceIndex":32,"id":"exchange-015"},{"speaker":"宮崎委員","kind":"質問","question":"わかりました、５億円というと非常に大きな額だなと感じます。ここら辺のところで、どういうふうにお考えでしょうか。","respondent":"桑村人事課長","answer":"それ以外のことにつきましては、いろいろな考え方があるかと思いますけれども、いわゆる公務員という、民間の方に支えられているものとしては、それに準拠していくのが正しい考え方なのかと、今のところ考えております。","voiceIndex":34,"id":"exchange-016"},{"speaker":"宮崎委員","kind":"意見","question":"そういうふうにどんどん下がっていくと、厳しくなると、デフレをさらに促進していくんじゃないかという心配があるんです。ちょっと、先ほど５億円という具体的な数字か出てきたんですけれども、これから、これをどう使うかというのもいろいろあるのかと思うんです。これはぜひ、区民の施策の充実といいますか、そういうところに回っていくようなことでやっていく必要があるんじゃないかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":36,"id":"exchange-017"},{"speaker":"本田委員","kind":"意見","question":"マイナス勧告はいつからでしたか、これはちょっと参考までに。その累積は、どのぐらいに。今回、０.６９％ですけれども、マイナスが始まってから、減額はトータルでどのぐらいになりましたか。","respondent":"桑村人事課長","answer":"先ほど申しましたように、今年は約１６.９万円と言われておりまして、去年が１４.５万円、おととしが１.７万円、その前が８万円、平成１１年度が１０万円ぐらいですので、大体、５年続けて１０万円ぐらいは金額が出るものです。","voiceIndex":37,"id":"exchange-018"},{"speaker":"本田委員","kind":"質問","question":"給与本体が減額になったのは去年ぐらいからと、期末手当等で減額するのが５年前からということで、民間との比較で適切に対応されてきたんだと思いますけれども、こういう減額というのは、それぞれの個々の公務員のご家庭にとりましては、決して好ましいことではないわけですね。今回の勧告に基づく労使間の協議というのは、特徴点は、どういうことだったんでしょうか。","respondent":"桑村人事課長","answer":"その意味で考えている根拠とは、こういうマイナスというのはかなり厳しいということがあります。もう一つは、全体、東京の特殊性というのが人事委員会勧告には入っていないんじゃないかという議論がございました。","voiceIndex":39,"id":"exchange-019"},{"speaker":"本田委員","kind":"質問","question":"公務員の場合は民間と違って、人事委員会というのが中に入って、特殊な労使関係にあるわけで、そういう意味では、極めて客観的にデータを出し、討議がされるというのが、税を払う納税者の立場から見たときに、公務員の給料につきましても、税が適切に使われているのかどうかという目で見るわけですから、今般、労使間の合意を得た内容ではありますけれども、今のようなお話を聞きますと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-020"},{"speaker":"武内委員","kind":"質問","question":"通勤手当（二）、（三）のほうが、今度、改正で上がっておりますけれども、この理由を教えてください。","respondent":"桑村人事課長","answer":"それも受けて、今まで費用弁償みたいな考え方でいたところで、限度額というのを設けていたわけですけれども、かなり遠くから来られる方もいるというので、その意味では下がるんだから、出せる人には出してくれという議論が一方にあって、人数からいいますと、私どもは。","voiceIndex":42,"id":"exchange-021"},{"speaker":"武内委員","kind":"質問","question":"これは都も一緒ですか、それとも品川区独自のものですか。","respondent":"桑村人事課長","answer":"５万５,０００円につきましては、都も区も一緒です。ただ、交通用具につきましては、東京都のほうがもう少し高いということです。","voiceIndex":44,"id":"exchange-022"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、ちょっと言葉はいけないかもしれないけれども、大ざっぱに額で比べておいて、パーセントを並べて、それで上がるときも上がる、下がるときも下がる、そういう理解をしておいてよろしいんですかね。","respondent":"桑村人事課長","answer":"その意味では、その結果、民間のほうが高いというのが出て上げたこともありますので、考え方は、委員がおっしゃったようなものです。","voiceIndex":54,"id":"exchange-023"},{"speaker":"林（宏）委員","kind":"質問","question":"それともう一つ、３５年以上というか、これに対象になる方はいるんですか、公務員に。","respondent":"桑村人事課長","answer":"いわゆる６０歳定年を前提としますと、２５歳で入れば、６０歳定年まで勤めれば３５年ということになるかと思います。","voiceIndex":56,"id":"exchange-024"},{"speaker":"林（宏）委員","kind":"質問","question":"そういう計算から、３５年以上は同額とはならないけれども、同率ですよということで、これはもうずっと、３５年というのは上限になっているんですか。","respondent":"桑村人事課長","answer":"実は、今まで３３年という数字になってございまして、国が３５年に対して、特別区、あるいは東京都は３３年にしていたんですけれども、途中での入社というんですか、入区される方というのは非常に多いという前提がございまして、その意味では。","voiceIndex":58,"id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1636#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":13296,"voices":64}}]);
